// Rebuilt and checked against the release sources before production publication.
export const GUARDIAN_BUNDLED_SOURCES: Array<{ path: string; content: string; sha256: string }> = [{"path":"regente/lib/constitution.ts","content":"export const SANITY_CONSTITUTION = [\n  {\n    id: \"S01\",\n    name: \"Mínimo suficiente\",\n    rule: \"Usar a solução mais simples e barata que cumpra adequadamente o objetivo.\",\n  },\n  {\n    id: \"S02\",\n    name: \"Objetivo obrigatório\",\n    rule: \"Nenhuma tarefa existe sem objetivo explícito e resultado esperado.\",\n  },\n  {\n    id: \"S03\",\n    name: \"Custo proporcional\",\n    rule: \"Modelos, agentes e ferramentas mais caros só entram quando o ganho esperado justificar.\",\n  },\n  {\n    id: \"S04\",\n    name: \"Não repetir trabalho\",\n    rule: \"Consultar estado, memória e resultados existentes antes de gerar novamente.\",\n  },\n  {\n    id: \"S05\",\n    name: \"Sem conversa pela conversa\",\n    rule: \"Diálogo entre agentes precisa ter finalidade, critério de parada e entrega esperada.\",\n  },\n  {\n    id: \"S06\",\n    name: \"Escalonamento progressivo\",\n    rule: \"Tentar primeiro o nível barato e simples; escalar apenas se insuficiente.\",\n  },\n  {\n    id: \"S07\",\n    name: \"Autonomia conquistada\",\n    rule: \"Processos novos começam supervisionados e ganham autonomia por evidência de desempenho.\",\n  },\n  {\n    id: \"S08\",\n    name: \"Humano por exceção\",\n    rule: \"Escalar ao humano decisões estratégicas, risco relevante, gasto relevante ou situação fora do padrão.\",\n  },\n  {\n    id: \"S09\",\n    name: \"Rastreabilidade\",\n    rule: \"Toda decisão deve indicar objetivo, nós envolvidos, motivo, risco e necessidade de aprovação.\",\n  },\n  {\n    id: \"S10\",\n    name: \"Kill switch\",\n    rule: \"Loop, anomalia, conflito ou custo excessivo interrompem a operação e exigem revisão.\",\n  },\n] as const;\n\nexport const CONSTITUTION_TEXT = SANITY_CONSTITUTION\n  .map((item) => `${item.id} — ${item.name}: ${item.rule}`)\n  .join(\"\\n\");\n","sha256":"b005de069ad75ca0cae82af94246641214671df52ce2e9d7e9cf50b1970a29cb"},{"path":"regente/lib/nodes.ts","content":"export type NetworkNode = {\n  id: string;\n  type: \"agent\" | \"tool\";\n  technology: string;\n  role: string;\n  status: \"current\" | \"assisted\" | \"integrating\" | \"confirm\";\n};\n\nexport const NETWORK_NODES: NetworkNode[] = [\n  { id: \"A1\", type: \"agent\", technology: \"ChatGPT\", role: \"Engenharia Optótica\", status: \"current\" },\n  { id: \"A2\", type: \"agent\", technology: \"ChatGPT\", role: \"Produto e fluxos Optótica\", status: \"current\" },\n  { id: \"A3\", type: \"agent\", technology: \"ChatGPT\", role: \"Conteúdo ENSAVIM\", status: \"current\" },\n  { id: \"A4\", type: \"agent\", technology: \"OpenAI\", role: \"Guardião externo: revisão independente e recovery de segunda linha\", status: \"assisted\" },\n  { id: \"A5\", type: \"agent\", technology: \"Local / Supabase\", role: \"Afinamento básico e preflight determinístico\", status: \"current\" },\n  { id: \"A6\", type: \"agent\", technology: \"Claude\", role: \"Guardião externo: contraponto, arquitetura e programação\", status: \"integrating\" },\n  { id: \"F1\", type: \"tool\", technology: \"GitHub\", role: \"Optótica Portal / repositório\", status: \"current\" },\n  { id: \"F2\", type: \"tool\", technology: \"Vercel\", role: \"Optótica Portal / execução\", status: \"current\" },\n  { id: \"F3\", type: \"tool\", technology: \"Supabase\", role: \"Banco e backend Optótica\", status: \"current\" },\n  { id: \"F4\", type: \"tool\", technology: \"Replicate\", role: \"Imagens do catálogo\", status: \"current\" },\n  { id: \"F5\", type: \"tool\", technology: \"Canva\", role: \"Prova Online / produtos\", status: \"assisted\" },\n  { id: \"F6\", type: \"tool\", technology: \"Canva\", role: \"Criativos ENSAVIM\", status: \"confirm\" },\n  { id: \"F7\", type: \"tool\", technology: \"HeyGen\", role: \"ENSAVIM / Lia\", status: \"current\" },\n  { id: \"F8\", type: \"tool\", technology: \"RapidAPI\", role: \"AliExpress / catálogo\", status: \"current\" },\n  { id: \"F9\", type: \"tool\", technology: \"Meta / WhatsApp\", role: \"Optótica\", status: \"integrating\" },\n  { id: \"F10\", type: \"tool\", technology: \"Resend\", role: \"E-mails Optótica\", status: \"confirm\" },\n  { id: \"F11\", type: \"tool\", technology: \"Cloudflare\", role: \"Domínio / rede Optótica\", status: \"confirm\" },\n  { id: \"F12\", type: \"tool\", technology: \"Google Drive\", role: \"Arquivos dos projetos\", status: \"current\" },\n  { id: \"F13\", type: \"tool\", technology: \"Google Docs\", role: \"Documentação dos projetos\", status: \"current\" },\n  { id: \"F14\", type: \"tool\", technology: \"Google Planilhas\", role: \"Matriz da rede\", status: \"current\" },\n];\n\nexport const NODE_SUMMARY = NETWORK_NODES\n  .map((node) => `${node.id} | ${node.type} | ${node.technology} | ${node.role} | ${node.status}`)\n  .join(\"\\n\");\n","sha256":"52743297c323fe37e0d24282841183837ce1ff0946d1cefb0becb09cc6b97db4"},{"path":"regente/lib/provider-registry.ts","content":"export type GuardianProviderId = \"openai\" | \"claude\";\nexport type ProviderEnvironment = Record<string, string | undefined>;\n\nexport type GuardianProvider = {\n  id: GuardianProviderId;\n  label: string;\n  roles: string[];\n  state: \"configured\" | \"requires_configuration\" | \"manual\";\n  route: \"openai_agents_sdk\" | \"manual_external_review\";\n  requestedRoute: string | null;\n  transport: \"openai_https\" | \"human_import\";\n  model: string | null;\n  configured: boolean;\n  adapterConnected: boolean;\n  automatic: boolean;\n  authenticated: boolean | null;\n  authorized: boolean | null;\n  operational: boolean | null;\n  financial: \"not_verified\";\n  requiredConfiguration: string[];\n  sourceVersion: \"0.7.0\";\n  release: \"v0.7\";\n};\n\nexport function credentialPresent(name: string, env: ProviderEnvironment = process.env) {\n  return Boolean(env[name]?.trim());\n}\n\n// Roles and transports are separate. Setting a key or model alone must never\n// advertise an adapter that does not exist. Interactive Claude reviews have an\n// explicit human-import transport; they are not Anthropic API executions.\nexport function guardianProviders(env: ProviderEnvironment = process.env): GuardianProvider[] {\n  const openAIConfigured = credentialPresent(\"OPENAI_API_KEY\", env);\n  const requestedRouteValue = env.REGENT_CLAUDE_PROVIDER?.trim();\n  const requestedClaudeRoute = requestedRouteValue\n    ? [\"manual\", \"anthropic\", \"vercel_ai_gateway\", \"google_vertex\", \"amazon_bedrock\"].includes(requestedRouteValue)\n      ? requestedRouteValue : \"unsupported_route\" : null;\n  const requestedModel = env.REGENT_REVIEW_MODEL?.trim() || env.REGENT_RECOVERY_MODEL?.trim() || env.REGENT_MODEL?.trim();\n  const model = requestedModel\n    ? /^[A-Za-z0-9][A-Za-z0-9._/-]{0,127}$/.test(requestedModel) &&\n      !/^(?:sk[-_]|cnvca|gh[pousr]_|github_pat_)/i.test(requestedModel) ? requestedModel : null\n    : \"gpt-5.6-sol\";\n  return [\n    {\n      id: \"openai\",\n      label: \"Guardião OpenAI / ChatGPT\",\n      roles: [\"programação\", \"revisão independente\", \"recovery\"],\n      state: openAIConfigured ? \"configured\" : \"requires_configuration\",\n      route: \"openai_agents_sdk\",\n      requestedRoute: null,\n      transport: \"openai_https\",\n      model,\n      configured: openAIConfigured,\n      adapterConnected: true,\n      automatic: true,\n      authenticated: null,\n      authorized: null,\n      operational: null,\n      financial: \"not_verified\",\n      requiredConfiguration: [\n        ...(!openAIConfigured ? [\"Configurar OPENAI_API_KEY no runtime do Regente.\"] : []),\n        ...(model === null ? [\"Conferir o identificador do modelo do guardião; valor inválido ou sensível omitido do relatório.\"] : []),\n      ],\n      sourceVersion: \"0.7.0\",\n      release: \"v0.7\",\n    },\n    {\n      id: \"claude\",\n      label: \"Guardião Claude — revisão externa assistida\",\n      roles: [\"contraponto\", \"revisão de arquitetura\", \"programação\"],\n      state: \"manual\",\n      route: \"manual_external_review\",\n      requestedRoute: requestedClaudeRoute,\n      transport: \"human_import\",\n      model: null,\n      configured: true,\n      adapterConnected: true,\n      automatic: false,\n      authenticated: null,\n      authorized: null,\n      operational: null,\n      financial: \"not_verified\",\n      requiredConfiguration: [\n        \"Baixar o pacote do guardião, revisar na sua conta Claude e importar o parecer no Regente.\",\n        ...(requestedClaudeRoute && requestedClaudeRoute !== \"manual\"\n          ? [\"A rota programática solicitada ainda não possui adapter validado nesta versão; não é ativada pela presença de uma chave.\"]\n          : []),\n      ],\n      sourceVersion: \"0.7.0\",\n      release: \"v0.7\",\n    },\n  ];\n}\n\n","sha256":"7db32b98e2e65001bb994668da9644db285f973eb626f66a329b50ff555ab116"},{"path":"regente/lib/phase-control.ts","content":"import type { PipelineStep } from \"./adapters\";\n\nexport const REGENT_VERSION = \"0.7.0\";\n\nexport type PhaseState = {\n  step_number: number;\n  status: string;\n  depends_on?: number[] | null;\n  revision?: number;\n  artifact?: unknown;\n  validated_at?: string | null;\n};\n\nexport function nextPhase(steps: PhaseState[]) {\n  const ordered = [...steps].sort((a, b) => a.step_number - b.step_number);\n  const next = ordered.find((step) => ![\"succeeded\", \"skipped\"].includes(step.status));\n  if (!next) return { step: null, unresolved: [] as number[] };\n  const completed = new Set(ordered.filter((step) => [\"succeeded\", \"skipped\"].includes(step.status)).map((step) => step.step_number));\n  return { step: next, unresolved: (next.depends_on || []).filter((step) => !completed.has(step)) };\n}\n\n/** Context follows declared data edges, so redo invalidates exactly the actual consumers. */\nexport function dependencyArtifacts(steps: Array<PhaseState & { node_ids?: string[] }>, target: number) {\n  const needed = new Set<number>();\n  const visit = (number: number) => {\n    for (const dependency of steps.find((step) => step.step_number === number)?.depends_on || []) {\n      if (dependency === target || needed.has(dependency)) continue;\n      needed.add(dependency); visit(dependency);\n    }\n  };\n  visit(target);\n  return steps.filter((step) => needed.has(step.step_number) && step.status === \"succeeded\" && step.artifact != null)\n    .sort((a, b) => a.step_number - b.step_number)\n    .map((step) => ({ step: step.step_number, node: step.node_ids?.[0] || \"unknown\", output: step.artifact }));\n}\n\n/** Every new mission has a deterministic local preflight; never rewrite existing missions' IDs. */\nexport function normalizeNewPipeline(pipeline: PipelineStep[]): PipelineStep[] {\n  if (!pipeline.length) return [];\n  const ordered = [...pipeline].sort((a, b) => a.step - b.step);\n  const ids = ordered.map((step) => step.step);\n  if (new Set(ids).size !== ids.length) throw new Error(\"O plano contém etapas duplicadas.\");\n  const hasPreflight = ordered[0].nodes[0] === \"A5\";\n  const mapping = new Map(ids.map((id, index) => [id, index + (hasPreflight ? 1 : 2)]));\n  const normalized = ordered.map((step, index) => {\n    const declared = step.dependsOn ?? (index ? [ordered[index - 1].step] : []);\n    if (declared.some((dep) => !mapping.has(dep) || dep >= step.step)) {\n      throw new Error(\"Dependência inexistente ou cíclica no plano. Revise a pipeline antes de executar.\");\n    }\n    const dependencies = declared.map((dep) => mapping.get(dep)!);\n    return { ...step, step: mapping.get(step.step)!, dependsOn: !hasPreflight && !dependencies.length ? [1] : dependencies, checkpoint: true, requiresApproval: true };\n  });\n  const preflight: PipelineStep = {\n    step: 1, role: \"reference\", nodes: [\"A5\"],\n    action: \"Afinar a orquestra: verificar estado, dependências, adapters e configuração sem chamadas generativas.\",\n    input: \"Estado persistente desta missão e configuração booleana do runtime autenticado.\",\n    expectedOutput: \"Relatório de afinamento básico, capacidades reais, limites não verificáveis e primeira fase elegível.\",\n    executionState: \"ready\", requiresApproval: true, dependsOn: [], checkpoint: true,\n  };\n  return hasPreflight ? [{ ...normalized[0], ...preflight }, ...normalized.slice(1)] : [preflight, ...normalized];\n}\n\nexport function buildPhaseReport(input: {\n  step: PipelineStep;\n  revision: number;\n  output: unknown;\n  states: PhaseState[];\n  completedAt?: string;\n}) {\n  const states = input.states.map((state) => state.step_number === input.step.step ? { ...state, status: \"succeeded\" } : state);\n  const next = nextPhase(states);\n  const output = input.output as { result?: unknown; notes?: unknown; deferred?: unknown } | null;\n  const result = typeof output?.result === \"string\" ? output.result : \"\";\n  return {\n    kind: \"phase_checkpoint\", version: REGENT_VERSION,\n    step: input.step.step, revision: input.revision, title: input.step.action,\n    summary: output?.deferred ? \"Fase adiada explicitamente, sem execução externa.\" : result ? result.slice(0, 1600) : \"Output persistido. Revise o conteúdo e os limites antes de continuar.\",\n    output: input.output,\n    completedAt: input.completedAt || new Date().toISOString(),\n    nextStep: next.step?.step_number ?? null,\n    unresolvedDependencies: next.unresolved,\n    final: next.step === null,\n    limitations: [\n      \"A conclusão desta fase não significa aprovação humana nem conclusão da missão.\",\n      \"Custo real e saldo não verificáveis sem evidência de faturamento.\",\n      ...(Array.isArray(output?.notes) ? output.notes.filter((note): note is string => typeof note === \"string\") : []),\n    ],\n  };\n}\n\nexport function redactSecrets(value: string, env: Record<string, string | undefined> = process.env) {\n  let text = value;\n  for (const [name, secret] of Object.entries(env)) {\n    if (/(?:SECRET|TOKEN|API_KEY|PASSWORD|PRIVATE_KEY)/i.test(name) && secret && secret.length >= 8) {\n      text = text.split(secret).join(\"[segredo ocultado]\");\n    }\n  }\n  return text.replace(/\\b(?:sk-|sk_|eyJ)[A-Za-z0-9_.-]{12,}/g, \"[segredo ocultado]\")\n    .replace(/\\b(?:cnvca|gh[pousr]_)[A-Za-z0-9_-]{8,}/g, \"[segredo ocultado]\")\n    .replace(/([?&](?:token|client_secret|api_key|access_token|refresh_token)=)[^&\\s]+/gi, \"$1[segredo ocultado]\")\n    .replace(/Bearer\\s+[A-Za-z0-9_.-]+/gi, \"Bearer [segredo ocultado]\");\n}\n\nexport function failureDisposition(error: unknown, node: string, mode?: string) {\n  const raw = error instanceof Error ? error.message : String(error || \"Falha sem detalhes.\");\n  const message = redactSecrets(raw).slice(0, 2200);\n  const status = Number((error as { status?: unknown } | null)?.status || 0);\n  const code = String((error as { code?: unknown } | null)?.code || \"\");\n  if (/insufficient_quota|billing|credit|saldo|payment/i.test(raw + code)) {\n    return { message, kind: \"billing\", retry: false, action: \"Conferir faturamento e limites do provedor; depois autorizar a retomada desta fase.\" };\n  }\n  if ([401, 403].includes(status) || /OAuth|invalid_grant|invalid_scope|credencial|não configurad|unauthorized|forbidden|permiss[ãa]o|sem acesso/i.test(raw)) {\n    return { message, kind: \"configuration\", retry: false, action: node === \"F6\" ? \"No Portal, reconecte a conta Canva correta e confira as permissões REST API. Faça o afinamento profundo e retome esta fase.\" : \"Confira a configuração do adapter no ambiente de produção. Não crie uma conta Anthropic para desbloquear nós OpenAI.\" };\n  }\n  if (/adapter|ainda não conectado|dependências|referências|precisa declarar|múltiplos|inválid|not found|422/i.test(raw) || status === 422) {\n    return { message, kind: \"deterministic\", retry: false, action: \"Revisar a entrada ou conectar o adapter indicado. Use Refazer com orientação, preservando os outputs anteriores.\" };\n  }\n  if (node === \"F6\" && mode !== \"inspect\") {\n    return { message, kind: \"external_effect_unknown\", retry: false, action: \"Verificar os designs e o run original no Canva antes de refazer. Um erro de transporte pode ocorrer após a criação; não repetir automaticamente.\" };\n  }\n  const transient = [408, 429, 500, 502, 503, 504].includes(status) || /timeout|timed out|ECONNRESET|ETIMEDOUT|rate.?limit|HTTP 50[234]|fetch failed|temporar/i.test(raw);\n  return { message, kind: transient ? \"transient\" : \"unknown\", retry: transient && ([\"A1\", \"A2\", \"A3\", \"A4\"].includes(node) || node === \"F6\" && mode === \"inspect\"), action: transient ? \"Repetir apenas esta fase dentro do limite autorizado; efeitos externos confirmados serão preservados.\" : \"Analisar o diagnóstico e autorizar a retomada ou refazer apenas esta fase com nova orientação.\" };\n}\n","sha256":"1b411102a66d36b1daf61df2f66675466ee8ae85bcd5d7a325e478b11b46b97d"},{"path":"regente/lib/phase-patch.ts","content":"const EXECUTORS = new Set([\"A1\", \"A2\", \"A3\", \"A4\", \"A5\", \"A6\", \"F6\", \"F9\"]);\nconst UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;\n\n/** Small explicit human plan amendment, not arbitrary JSON or an automatic model rewrite. */\nexport function validatePhasePatch(value: unknown) {\n  if (!value || typeof value !== \"object\" || Array.isArray(value)) throw new Error(\"Configuração de fase inválida.\");\n  const patch = value as Record<string, unknown>;\n  if (Object.keys(patch).some((key) => ![\"nodes\", \"canvaMode\", \"canvaSourceRunIds\", \"canvaDesignIds\"].includes(key))) throw new Error(\"A alteração contém campos não autorizados.\");\n  if (!Array.isArray(patch.nodes) || patch.nodes.length !== 1 || !EXECUTORS.has(patch.nodes[0])) throw new Error(\"Escolha somente um executor para esta fase.\");\n  const nodes = patch.nodes as string[];\n  if (nodes[0] !== \"F6\") return { nodes };\n  if (![\"inspect\", \"create\"].includes(String(patch.canvaMode))) throw new Error(\"Declare inspecionar ou criar no Canva.\");\n  if (patch.canvaMode === \"create\") return { nodes, canvaMode: \"create\" };\n  const sourceIds = patch.canvaSourceRunIds;\n  const designIds = patch.canvaDesignIds;\n  if (!Array.isArray(sourceIds) || !sourceIds.length || sourceIds.length > 20 || sourceIds.some((id) => typeof id !== \"string\" || !UUID.test(id)) ||\n    !Array.isArray(designIds) || !designIds.length || designIds.length > 10 || designIds.some((id) => typeof id !== \"string\" || !/^[A-Za-z0-9_-]{6,80}$/.test(id))) {\n    throw new Error(\"Inspeção exige IDs dos runs de origem e IDs Canva correspondentes, copiados dos outputs preservados.\");\n  }\n  return { nodes, canvaMode: \"inspect\", canvaSourceRunIds: [...new Set(sourceIds as string[])], canvaDesignIds: [...new Set(designIds as string[])] };\n}\n","sha256":"cb7fd1168ffc147a9eadca6de416fac01bd225b48bce5e90cf36523411d63b07"},{"path":"regente/lib/task-runtime.ts","content":"import { deriveTaskObservability } from \"./task-observability\";\n\nexport function taskRuntime(task: Record<string, any>, steps: Array<Record<string, any>>, now = Date.now()) {\n  const completed = steps.filter((step) => [\"succeeded\", \"skipped\"].includes(step.status)).length;\n  const last = Math.max(new Date(task.updated_at || 0).getTime() || 0, ...steps.map((step) => new Date(step.updated_at || 0).getTime() || 0));\n  const lease = task.execution_lease_until ? new Date(task.execution_lease_until).getTime() : null;\n  const stale = task.status === \"executing\" && (lease != null ? lease <= now : last > 0 && now - last > 15 * 60_000);\n  const active = steps.find((step) => [\"running\", \"review\"].includes(step.status));\n  const next = steps.find((step) => ![\"succeeded\", \"skipped\"].includes(step.status));\n  const observation = deriveTaskObservability({ task: { ...task, status: task.status }, steps: steps as Array<{ step_number: number; status: string }>, isStale: stale });\n  return {\n    ...task,\n    status: String(task.status),\n    progress_percent: steps.length ? Math.round(completed * 100 / steps.length) : Number(task.progress_percent || 0),\n    current_step: task.status === \"succeeded\" ? null : task.phase_report?.step ?? active?.step_number ?? next?.step_number ?? task.current_step ?? null,\n    is_stale: stale,\n    last_activity_at: last ? new Date(last).toISOString() : null,\n    next_action: stale ? \"A reserva de execução expirou. Use Recuperar execução para autorizar somente a fase pendente; outputs serão preservados.\" : task.next_action,\n    attention: observation.attention, recovery: observation.recovery,\n  };\n}\n","sha256":"9df58b2064841507e71014742d056f72ee9b002df2a9500061e31304fb889e17"},{"path":"regente/lib/workflow-state.ts","content":"/** Metadata-only policy: never expose serialized Workflow input, output or errors. */\nexport type WorkflowFailureKind =\n  | \"configuration\"\n  | \"authentication\"\n  | \"session\"\n  | \"conflict\"\n  | \"timeout\"\n  | \"dispatch_unknown\"\n  | \"response_invalid\";\n\nconst FAILURE_MESSAGES: Record<WorkflowFailureKind, string> = {\n  configuration: \"[REGENT_WORKFLOW_CONFIGURATION] A configuração da execução durável é inválida. Confira o ambiente de produção antes de autorizar outra tentativa.\",\n  authentication: \"[REGENT_WORKFLOW_AUTHENTICATION] A sessão ou a autorização Master da execução durável não foi confirmada. Reentre no portal antes de autorizar outra tentativa.\",\n  session: \"[REGENT_WORKFLOW_SESSION] A sessão protegida não pôde ser renovada ou validada. Reentre no portal; nenhum fallback de credenciais será usado.\",\n  conflict: \"[REGENT_WORKFLOW_CONFLICT] A reserva ou o estado desta execução mudou. Atualize o monitor; esta invocação não será repetida automaticamente.\",\n  timeout: \"[REGENT_WORKFLOW_TIMEOUT] A confirmação da execução excedeu o prazo. O servidor pode ter iniciado a fase; confira o estado e os outputs antes de autorizar outra tentativa.\",\n  dispatch_unknown: \"[REGENT_WORKFLOW_DISPATCH_UNKNOWN] Não foi possível confirmar a resposta da execução. A fase pode ter sido iniciada; não haverá repetição automática.\",\n  response_invalid: \"[REGENT_WORKFLOW_RESPONSE_INVALID] O servidor não retornou uma confirmação válida. Confira o estado persistente e os outputs; não haverá repetição automática.\",\n};\n\nexport function workflowFailureMessage(kind: WorkflowFailureKind) {\n  return FAILURE_MESSAGES[kind];\n}\n\n/** Only our own finite tags are consumed; raw exception text is never returned. */\nexport function workflowFailureKind(error: unknown): WorkflowFailureKind {\n  const message = error && typeof error === \"object\" && \"message\" in error\n    ? (error as { message?: unknown }).message : error;\n  if (typeof message !== \"string\") return \"dispatch_unknown\";\n  for (const [kind, text] of Object.entries(FAILURE_MESSAGES)) {\n    const tag = text.slice(0, text.indexOf(\"]\") + 1);\n    if (message.includes(tag)) return kind as WorkflowFailureKind;\n  }\n  return \"dispatch_unknown\";\n}\n\nexport function workflowHttpFailure(status: number): WorkflowFailureKind {\n  if (status === 401 || status === 403) return \"authentication\";\n  if (status === 409) return \"conflict\";\n  if ([400, 404, 405, 422].includes(status)) return \"configuration\";\n  if (status === 408 || status === 504) return \"timeout\";\n  // A 5xx or transport failure does not prove that a side effect was rejected.\n  return \"dispatch_unknown\";\n}\n\nfunction origin(value: string, localDevelopmentAllowed = false) {\n  try {\n    const url = new URL(value);\n    if (url.username || url.password || url.search || url.hash || ![\"\", \"/\"].includes(url.pathname)) return null;\n    const localDevelopment = localDevelopmentAllowed && url.protocol === \"http:\" && [\"localhost\", \"127.0.0.1\", \"[::1]\"].includes(url.hostname);\n    if (url.protocol !== \"https:\" && !localDevelopment) return null;\n    return url.origin;\n  } catch {\n    return null;\n  }\n}\n\nexport function safeWorkflowOrigin(value: string, production: boolean, env: Record<string, string | undefined> = process.env) {\n  const candidate = origin(value, !production);\n  if (!candidate || !production) return candidate;\n  // A spoofed Host/request origin must never become a bearer-token destination.\n  const trusted = new Set([\"https://optotica-regente.vercel.app\"]);\n  const configured = origin(env.REGENT_APP_ORIGIN || \"\");\n  if (configured) trusted.add(configured);\n  for (const name of [\"VERCEL_URL\", \"VERCEL_PROJECT_PRODUCTION_URL\"]) {\n    const hostname = env[name]?.trim();\n    if (!hostname) continue;\n    const configuredOrigin = origin(hostname.startsWith(\"https://\") ? hostname : `https://${hostname}`);\n    if (configuredOrigin) trusted.add(configuredOrigin);\n  }\n  return trusted.has(candidate) ? candidate : null;\n}\n\n/** SDK 5 uses wrun_ followed by a Crockford ULID; no arbitrary ID is fetched. */\nexport function safeWorkflowRunId(value: unknown) {\n  return typeof value === \"string\" && /^wrun_[0-7][0-9A-HJKMNP-TV-Z]{25}$/i.test(value) ? value : null;\n}\n\nexport const WORKFLOW_ERROR_CODES = new Set([\n  \"USER_ERROR\", \"MAX_EVENTS_EXCEEDED\", \"MAX_DELIVERIES_EXCEEDED\", \"REPLAY_TIMEOUT\",\n  \"REPLAY_DIVERGENCE\", \"CORRUPTED_EVENT_LOG\", \"STREAM_ERROR\", \"WORLD_CONTRACT_ERROR\",\n  \"DEPLOYMENT_MISMATCH\", \"RUNTIME_ERROR\",\n]);\nconst WORKFLOW_STATUSES = new Set([\"pending\", \"running\", \"completed\", \"failed\", \"cancelled\"]);\n\nexport type WorkflowObservation = {\n  verified: boolean;\n  runId: string | null;\n  status: \"pending\" | \"running\" | \"completed\" | \"failed\" | \"cancelled\" | null;\n  errorCode: string | null;\n  startedAt: string | null;\n  completedAt: string | null;\n  updatedAt: string | null;\n  checkedAt: string;\n  deploymentChanged: boolean | null;\n  detail: string;\n  inputOutputLoaded: false;\n};\n\nfunction date(value: unknown) {\n  if (!(typeof value === \"string\" || typeof value === \"number\" || value instanceof Date)) return null;\n  const time = new Date(value).getTime();\n  return Number.isFinite(time) ? new Date(time).toISOString() : null;\n}\n\nexport function workflowObservation(input: {\n  runId?: string | null;\n  run?: Record<string, unknown> | null;\n  currentDeploymentId?: string;\n  now?: number;\n  reason?: \"not_linked\" | \"unavailable\" | \"timeout\" | \"invalid_run\";\n}): WorkflowObservation {\n  const run = input.run;\n  const runId = safeWorkflowRunId(input.runId);\n  const valid = Boolean(runId && run?.runId === runId && WORKFLOW_STATUSES.has(String(run?.status)) &&\n    typeof run?.workflowName === \"string\" && run.workflowName.endsWith(\"//taskExecutionWorkflow\"));\n  const status = valid ? run!.status as WorkflowObservation[\"status\"] : null;\n  const errorCode = valid && typeof run?.errorCode === \"string\" && WORKFLOW_ERROR_CODES.has(run.errorCode) ? run.errorCode : null;\n  const deploymentChanged = valid && typeof run?.deploymentId === \"string\" && input.currentDeploymentId\n    ? run.deploymentId !== input.currentDeploymentId : null;\n  const detail = !valid\n    ? !runId || input.reason === \"not_linked\" ? \"Nenhum Workflow está vinculado a esta missão.\"\n      : input.reason === \"timeout\" ? \"A consulta ao Workflow excedeu o prazo; o estado do banco permanece a referência.\"\n        : \"Não foi possível confirmar o estado do Workflow. Nenhuma execução ou credencial alternativa foi acionada.\"\n    : status === \"failed\" ? \"O Workflow falhou. Isso não confirma a falha de todos os outputs nem autoriza repetir a fase.\"\n      : status === \"cancelled\" ? \"O Workflow foi cancelado. Os checkpoints persistidos continuam preservados.\"\n        : status === \"completed\" ? \"O Workflow terminou; a conclusão e a validação da missão dependem do estado persistente.\"\n          : deploymentChanged ? \"Esta execução permanece vinculada ao deployment que a iniciou; um redeploy não a migra.\"\n            : \"Estado operacional consultado sem carregar entradas, saídas ou sessões protegidas.\";\n  return {\n    verified: valid, runId, status, errorCode,\n    startedAt: valid ? date(run?.startedAt) : null,\n    completedAt: valid ? date(run?.completedAt) : null,\n    updatedAt: valid ? date(run?.updatedAt) : null,\n    checkedAt: new Date(input.now ?? Date.now()).toISOString(),\n    deploymentChanged, detail, inputOutputLoaded: false,\n  };\n}\n\n/** Enrich display only. Checkpoints and status are never synthesized from Workflow. */\nexport function withWorkflowObservation<T extends Record<string, any>>(task: T, observation: WorkflowObservation, now = Date.now()) {\n  const leaseTime = date(task.execution_lease_until);\n  const leaseActive = leaseTime !== null && new Date(leaseTime).getTime() > now;\n  const interrupted = observation.verified && [\"failed\", \"cancelled\"].includes(observation.status || \"\");\n  const incomplete = observation.verified && observation.status === \"completed\" && task.status === \"executing\";\n  const recoverableStatus = [\"failed\", \"blocked\"].includes(task.status) || task.status === \"executing\" && task.is_stale === true;\n  const recoveryEligibility = {\n    humanOnly: true,\n    allowedNow: recoverableStatus && !leaseActive,\n    leaseActive,\n    leaseUntil: leaseTime,\n    checkpointPreserved: true,\n    reason: leaseActive ? \"A reserva da fase ainda está ativa. Aguarde a expiração e confira os outputs.\"\n      : task.status === \"executing\" && !task.is_stale ? \"A janela segura inicial de execução ainda não expirou. Atualize o monitor.\"\n        : recoverableStatus ? \"Uma decisão humana persistida deve autorizar somente a fase pendente.\"\n          : \"Use a ação correspondente ao checkpoint atual; nenhuma retomada automática foi autorizada.\",\n  };\n  if (task.status !== \"executing\" || !(interrupted || incomplete)) {\n    return { ...task, workflow: observation, workflow_warning: interrupted ? observation.detail : null, recovery_eligibility: recoveryEligibility };\n  }\n  const message = `${observation.detail} ${recoveryEligibility.reason}`;\n  return {\n    ...task, workflow: observation, workflow_warning: message, recovery_eligibility: recoveryEligibility,\n    next_action: message,\n    attention: {\n      kind: interrupted ? \"failed\" : \"stale\", severity: \"critical\", action: \"refresh\",\n      title: interrupted ? \"A execução durável foi interrompida\" : \"Confirmação de checkpoint pendente\",\n      message, step: task.current_step ?? null,\n      attempts: task.attention?.attempts || 0,\n      error: observation.errorCode,\n    },\n  };\n}\n","sha256":"7ffe15a5f04aeee3fe5ce6e42c6d6721876206d4a2dcb02f34f6cd895dfc77b7"},{"path":"regente/lib/artifact-outputs.ts","content":"import { redactSecrets } from \"./phase-control.ts\";\n\nexport const OUTPUT_PREVIEW_CHARS = 24_000;\ntype EvidenceRow = Record<string, unknown>;\n\n/** Mask secrets without truncating the downloadable document. */\nexport function safeArtifact(value: unknown, depth = 0): unknown {\n  if (depth > 40) return \"[estrutura excede limite de profundidade]\";\n  if (typeof value === \"string\") return redactSecrets(value);\n  if (Array.isArray(value)) return value.map((item) => safeArtifact(item, depth + 1));\n  if (value && typeof value === \"object\") return Object.fromEntries(Object.entries(value).map(([key, item]) => {\n    const normalized = key.replace(/([a-z0-9])([A-Z])/g, \"$1_$2\");\n    const sensitive = /^(?:.*[_-])?(?:password|secret|token|api[_-]?key|authorization|cookie|private[_-]?key)(?:[_-].*)?$/i.test(normalized);\n    return [key, sensitive ? \"[campo sensível omitido]\" : safeArtifact(item, depth + 1)];\n  }));\n  return value ?? null;\n}\n\nexport function artifactDocument(value: unknown) {\n  const safe = safeArtifact(value);\n  if (typeof safe === \"string\") return safe;\n  if (safe && typeof safe === \"object\" && !Array.isArray(safe)) {\n    const { result, ...metadata } = safe as Record<string, unknown>;\n    if (typeof result === \"string\") return result + (Object.keys(metadata).length ? \"\\n\\n## Evidências e limites registrados\\n\\n```json\\n\" + JSON.stringify(metadata, null, 2) + \"\\n```\\n\" : \"\");\n  }\n  return JSON.stringify(safe, null, 2) || \"\";\n}\n\nexport function artifactLinks(text: string) {\n  const links = new Set<string>();\n  for (const match of text.matchAll(/https?:\\/\\/[^\\s\\\"'<>`]+/g)) {\n    if (links.size >= 25) break;\n    try {\n      const url = new URL(match[0].replace(/[.,;)\\]]+$/, \"\"));\n      if (url.username || url.password || /\\[segredo|token|client_secret|api_key|authorization/i.test(url.href)) continue;\n      if (url.protocol === \"https:\" || url.protocol === \"http:\") links.add(url.href);\n    } catch { /* Never fetch or treat these links as verified evidence. */ }\n  }\n  return [...links];\n}\n\nexport function buildArtifactOutputs(input: { taskId: string; steps: EvidenceRow[]; runs: EvidenceRow[]; reviews: EvidenceRow[] }) {\n  const entries = [\n    ...input.steps.filter((row) => row.artifact != null).map((row) => ({\n      id: `step-${row.step_number}-v${row.revision || 1}`, step: Number(row.step_number), revision: Number(row.revision || 1),\n      node: Array.isArray(row.node_ids) ? row.node_ids.join(\", \") : \"—\", kind: String(row.role || \"etapa\"),\n      source: \"checkpoint\", status: String(row.status), createdAt: row.completed_at || row.updated_at, output: row.artifact,\n    })),\n    ...input.runs.filter((row) => row.output != null).map((row) => ({\n      id: `run-${row.id}`, step: Number(row.step_number), revision: Number((row.input as { stepRevision?: number } | null)?.stepRevision || 1),\n      node: String(row.node_id || \"—\"), kind: String(row.adapter || \"execução\"), source: \"execução\",\n      status: String(row.status), createdAt: row.updated_at || row.created_at, output: row.output,\n    })),\n    ...input.reviews.filter((row) => row.output != null && row.decision === \"superseded\").map((row) => ({\n      id: `review-${row.id}`, step: Number(row.step_number), revision: Number(row.revision || 1),\n      node: \"histórico\", kind: \"versão anterior preservada\", source: \"revisão\", status: \"superseded\", createdAt: row.created_at, output: row.output,\n    })),\n  ].filter((entry) => !(entry.output as { deferred?: boolean } | null)?.deferred);\n  return entries.map(({ output, ...entry }) => {\n    const fullContent = artifactDocument(output);\n    const filename = `etapa-${String(entry.step).padStart(2, \"0\")}-revisao-${entry.revision}-${entry.id.replace(/[^a-z0-9-]/gi, \"\")}.md`;\n    return { ...entry, filename, fullContent,\n      content: fullContent.length > OUTPUT_PREVIEW_CHARS ? fullContent.slice(0, OUTPUT_PREVIEW_CHARS) + \"\\n… [baixe o arquivo completo]\" : fullContent,\n      truncated: fullContent.length > OUTPUT_PREVIEW_CHARS, links: artifactLinks(fullContent), linksVerified: false,\n      downloadUrl: `/api/tasks/${input.taskId}/outputs?download=${encodeURIComponent(entry.id)}`,\n    };\n  }).sort((a, b) => a.step - b.step || b.revision - a.revision || a.source.localeCompare(b.source));\n}\n","sha256":"76421a383791322adbf23315ed11933231edcec190cb0112e99b6557a98d64f0"},{"path":"regente/lib/phase-executor.ts","content":"import type { SupabaseClient } from \"@supabase/supabase-js\";\nimport {\n  buildCanvaSpec, executeCanvaBridge, executeCanvaInspectBridge,\n  executeIndependentOpenAIReviewer, executeOpenAIWorker, isOpenAINode, type PipelineStep,\n} from \"./adapters\";\nimport { executeA5LocalPreflight } from \"./a5-preflight\";\nimport { artifactFingerprint } from \"./artifact-fingerprint\";\nimport { buildPhaseReport, dependencyArtifacts, failureDisposition, redactSecrets, type PhaseState } from \"./phase-control\";\nimport { analyzeRecovery, reviewRecoveryWithOpenAI } from \"./recovery\";\nimport { collectOrchestraHealth } from \"./orchestra-health\";\n\ntype Artifact = { step: number; node: string; output: unknown };\nexport type PhaseTask = {\n  id: string; session_id: string; title: string; objective: string; pipeline: unknown; picker: unknown;\n  human_decision: unknown; execution_id: string; execution_invocation_id: string; engine_version?: string;\n};\n\nfunction message(error: unknown) {\n  return redactSecrets(error instanceof Error ? error.message : String(error || \"Falha desconhecida.\"));\n}\nfunction stepRunReusable(step: PipelineStep, revision: number, run: { adapter: string; input: unknown; output: unknown }, artifacts: Artifact[]) {\n  const input = run.input as { stepRevision?: number; step?: PipelineStep; priorArtifactFingerprint?: string } | null;\n  if (revision > 1 && input?.stepRevision !== revision) return false;\n  if (input?.step && artifactFingerprint(input.step) !== artifactFingerprint(step)) return false;\n  const node = step.nodes[0];\n  if (isOpenAINode(node) || node === \"A4\") return input?.priorArtifactFingerprint === artifactFingerprint(artifacts);\n  if (node !== \"F6\") return node === \"A5\";\n  // A legacy successful external effect must be reused, never recreated just because metadata was older.\n  if (step.canvaMode === \"create\") return run.adapter === \"canva_portal_bridge\" && (Boolean(input?.step) || revision === 1);\n  const references = run.input as { sourceRunIds?: string[]; designIds?: string[] } | null;\n  return run.adapter === \"canva_portal_inspect\" &&\n    artifactFingerprint([...(references?.sourceRunIds || [])].sort()) === artifactFingerprint([...(step.canvaSourceRunIds || [])].sort()) &&\n    artifactFingerprint([...(references?.designIds || [])].sort()) === artifactFingerprint([...(step.canvaDesignIds || [])].sort());\n}\n\n/** One workflow invocation produces ONE phase, then stops at the persisted human gate. */\nexport async function executePhase(input: { supabase: SupabaseClient; userId: string; task: PhaseTask }) {\n  const { supabase, userId, task } = input;\n  const pipeline = (Array.isArray(task.pipeline) ? task.pipeline : []) as PipelineStep[];\n  const stateResult = await supabase.from(\"regent_task_steps\")\n    .select(\"step_number,status,depends_on,revision,artifact,node_ids,validated_at,revision_guidance\")\n    .eq(\"task_id\", task.id).eq(\"user_id\", userId).order(\"step_number\");\n  if (stateResult.error) throw new Error(\"Não foi possível ler os checkpoints autenticados.\");\n  const states = (stateResult.data || []) as Array<PhaseState & { node_ids: string[]; revision_guidance?: string }>;\n  const decision = task.human_decision as { approved_steps?: number[]; note?: string; requested_decision?: string } | null;\n  const target = states.find((state) => state.step_number === decision?.approved_steps?.[0]);\n  if (!target || decision?.approved_steps?.length !== 1 || [\"succeeded\", \"skipped\"].includes(target.status)) {\n    throw new Error(\"A fase seguinte precisa de autorização humana específica. Nenhuma API externa foi executada.\");\n  }\n  const originalStep = pipeline.find((step) => step.step === target.step_number);\n  if (!originalStep) throw new Error(\"A etapa autorizada não corresponde à pipeline persistente.\");\n  const step = target.revision_guidance\n    ? { ...originalStep, input: originalStep.input + \"\\n\\nNOVA ORIENTAÇÃO HUMANA PARA ESTA VERSÃO:\\n\" + target.revision_guidance }\n    : originalStep;\n  const node = step.nodes[0] || \"unknown\";\n  const artifacts: Artifact[] = dependencyArtifacts(states, step.step);\n  let revision = Number(target.revision || 1);\n  let attempts = 0;\n\n  async function event(eventType: string, payload: unknown) {\n    const result = await supabase.from(\"regent_task_events\").insert({ task_id: task.id, user_id: userId, event_type: eventType, payload });\n    if (result.error) throw new Error(\"Não foi possível persistir o evento de execução.\");\n  }\n  async function begin() {\n    const result = await supabase.rpc(\"regent_begin_phase\", {\n      p_task_id: task.id, p_execution_id: task.execution_id, p_invocation_id: task.execution_invocation_id, p_step: step.step,\n    });\n    if (result.error) throw result.error;\n    revision = Number(result.data.revision);\n    attempts++;\n  }\n  async function finish(status: string, output: unknown, error: unknown, recovered = false) {\n    const report = [\"succeeded\", \"skipped\"].includes(status)\n      ? buildPhaseReport({ step, revision, output, states }) : null;\n    const result = await supabase.rpc(\"regent_finish_phase\", {\n      p_task_id: task.id, p_execution_id: task.execution_id, p_invocation_id: task.execution_invocation_id,\n      p_step: step.step, p_revision: revision, p_status: status, p_artifact: output, p_report: report, p_error: error, p_recovered: recovered,\n    });\n    if (result.error) throw result.error;\n    // The atomic checkpoint is the source of truth; a notification failure cannot undo it.\n    try { await supabase.from(\"regent_messages\").insert({\n      session_id: task.session_id, user_id: userId, role: \"assistant\",\n      content: report\n        ? `Fase ${step.step} concluída e persistida. Revise os outputs para continuar ou refazer. A missão ainda não foi finalizada.`\n        : `Fase ${step.step} pausada: ${(error as { action?: string } | null)?.action || \"Confira o diagnóstico no monitor.\"}`,\n      payload: { taskId: task.id, notification: true, phase: step.step, engineVersion: \"0.7.0\" },\n    }); } catch { console.error(\"regente_phase_notification_unavailable\", { taskId: task.id, step: step.step }); }\n    return { ...result.data, phaseReport: report, artifacts: output == null ? [] : [{ step: step.step, node, output }], recoveryEscalated: !report };\n  }\n\n  async function run() {\n    if (node === \"A5\") {\n      const preflight = await executeA5LocalPreflight({ supabase, taskId: task.id, userId, step });\n      const health = await collectOrchestraHealth({ supabase, userId, depth: \"basic\", taskId: task.id, requiredNodes: pipeline.flatMap((stage) => stage.nodes.slice(0, 1)) });\n      return { ...preflight, orchestra: health };\n    }\n    if (isOpenAINode(node) || node === \"A4\") {\n      if (!process.env.OPENAI_API_KEY?.trim()) throw new Error(\"OPENAI_API_KEY não configurada no runtime do Regente.\");\n      const adapter = node === \"A4\" ? \"openai_agents_independent_review\" : \"openai_agents\";\n      const created = await supabase.from(\"regent_tool_runs\").insert({\n        task_id: task.id, user_id: userId, step_number: step.step, node_id: node, adapter, status: \"running\",\n        input: { step, objective: task.objective, stepRevision: revision, executionId: task.execution_id, priorArtifactFingerprint: artifactFingerprint(artifacts) },\n      }).select(\"id\").single();\n      if (created.error || !created.data) throw new Error(\"Não foi possível registrar o run OpenAI.\");\n      const runId = created.data.id;\n      try {\n        const output = node === \"A4\"\n          ? await executeIndependentOpenAIReviewer({ step, objective: task.objective, priorArtifacts: artifacts })\n          : await executeOpenAIWorker({ node, step, objective: task.objective, priorArtifacts: artifacts });\n        if ((output as { blocked?: boolean }).blocked) throw new Error((output as { reason?: string }).reason || \"Revisor indisponível.\");\n        const saved = await supabase.from(\"regent_tool_runs\").update({ status: \"succeeded\", output, updated_at: new Date().toISOString() }).eq(\"id\", runId).eq(\"task_id\", task.id).eq(\"user_id\", userId);\n        if (saved.error) throw new Error(\"Output recebido, mas não persistido. Conferir o run original antes de retomar.\");\n        return output;\n      } catch (error) {\n        await supabase.from(\"regent_tool_runs\").update({ status: \"failed\", output: { message: message(error) }, updated_at: new Date().toISOString() }).eq(\"id\", runId).eq(\"task_id\", task.id).eq(\"user_id\", userId);\n        throw error;\n      }\n    }\n    if (node === \"F6\") {\n      if (step.canvaMode === \"inspect\") return executeCanvaInspectBridge({ supabase, taskId: task.id, userId, step, revision, executionId: task.execution_id, executionInvocationId: task.execution_invocation_id });\n      if (step.canvaMode !== \"create\") throw new Error(\"F6 precisa declarar canvaMode inspect/create e referências canônicas. Revise a etapa sem inventar IDs.\");\n      const active = await supabase.from(\"regent_tool_runs\").select(\"id,status,input\")\n        .eq(\"task_id\", task.id).eq(\"user_id\", userId).eq(\"step_number\", step.step)\n        .in(\"status\", [\"pending\", \"running\"]).eq(\"adapter\", \"canva_portal_bridge\");\n      if (active.error) throw new Error(\"Não foi possível conferir operações Canva em andamento.\");\n      if (active.data?.length) throw new Error(\"Existe uma criação Canva pendente no run original. Conferir o efeito externo antes de repetir.\");\n      if (!process.env.OPENAI_API_KEY?.trim()) throw new Error(\"OPENAI_API_KEY não configurada para preparar o design Canva.\");\n      const variants = Math.max(1, Math.min(3, Number((task.picker as { variantsRequested?: number } | null)?.variantsRequested || 1)));\n      const spec = await buildCanvaSpec({ step, objective: task.objective, title: task.title, priorArtifacts: artifacts, variants });\n      return executeCanvaBridge({ supabase, taskId: task.id, userId, step, spec, variants, revision, executionId: task.execution_id, executionInvocationId: task.execution_invocation_id });\n    }\n    if (node === \"A6\") {\n      const reviews = await supabase.from(\"regent_task_events\").select(\"id,payload,created_at\")\n        .eq(\"task_id\", task.id).eq(\"user_id\", userId).eq(\"event_type\", \"guardian_review_imported\")\n        .order(\"created_at\", { ascending: false }).limit(50);\n      if (reviews.error) throw new Error(\"Não foi possível ler a revisão externa autenticada.\");\n      const review = reviews.data?.find((entry) => {\n        const value = entry.payload as { providerDeclared?: string; step?: number; revisionDeclared?: number; revisionMatches?: boolean; sourceCommitMatches?: boolean | null } | null;\n        return value?.providerDeclared === \"claude\" && value.step === step.step && value.revisionDeclared === revision && value.revisionMatches === true && value.sourceCommitMatches === true;\n      });\n      if (!review) throw new Error(\"Adapter Claude automático não conectado. Baixe o pacote atualizado e importe uma revisão manual desta fase, revisão e commit do deployment; Claude.ai não comprova API.\");\n      const value = review.payload as { review?: string; sourceCommit?: string };\n      return { result: value.review, source: \"human_supplied\", claimedProvider: \"claude\", providerVerified: false, eventId: review.id,\n        notes: [\"Revisão externa anexada pelo operador; origem declarada, não verificada automaticamente. Validação humana ainda necessária.\"] };\n    }\n    throw new Error(`Adapter do nó ${node} ainda não conectado. O afinamento mostra a configuração necessária.`);\n  }\n\n  try {\n    await begin();\n    const unresolved = (target.depends_on || []).filter((dependency) => !states.some((state) => state.step_number === dependency && [\"succeeded\", \"skipped\"].includes(state.status)));\n    if (unresolved.length) throw new Error(\"Dependências pendentes: \" + unresolved.join(\", \"));\n    if (step.nodes.length > 1) {\n      throw new Error(\"A fase exige múltiplos adapters ainda não conectados. Separe os nós ou forneça as fontes documentais; não simular execução dos nós secundários.\");\n    }\n    const previous = await supabase.from(\"regent_tool_runs\").select(\"id,adapter,input,output,node_id\")\n      .eq(\"task_id\", task.id).eq(\"user_id\", userId).eq(\"step_number\", step.step).eq(\"status\", \"succeeded\").order(\"created_at\", { ascending: false }).limit(30);\n    if (previous.error) throw new Error(\"Não foi possível conferir os runs bem-sucedidos.\");\n    const reusable = node === \"A5\" ? null : previous.data?.find((run) => stepRunReusable(step, revision, run, artifacts));\n    if (reusable) return await finish(\"succeeded\", reusable.output, null);\n    // No auto-skips: only the persisted human skip decision can omit a phase.\n    const health = await collectOrchestraHealth({ supabase, userId, depth: \"basic\", taskId: task.id, requiredNodes: node === \"A6\" ? [\"A5\"] : node === \"F6\" && step.canvaMode === \"create\" ? [node, \"A1\"] : [node] });\n    await event(\"phase_preflight\", { step: step.step, revision, report: health });\n    if (health.summary.blockingCount > 0) {\n      const blockers = health.checks.filter((check) => check.blocking);\n      throw new Error(blockers.map((check) => check.action || check.detail).join(\" \") || \"Configuração de adapter incompleta; confira o afinamento.\");\n    }\n    let error: unknown;\n    const retryEvents: Array<Record<string, unknown>> = [];\n    for (let index = 0; index < 3; index++) {\n      try {\n        const output = await run();\n        return await finish(\"succeeded\", output, null, index > 0);\n      } catch (failure) {\n        error = failure;\n        const disposition = failureDisposition(failure, node, step.canvaMode);\n        retryEvents.push({ attempt: index + 1, ...disposition });\n        await event(\"phase_attempt_failed\", { step: step.step, revision, attempt: index + 1, ...disposition });\n        if (!disposition.retry || index === 2) break;\n        await event(\"phase_safe_retry\", { step: step.step, revision, nextAttempt: index + 2, delayMs: 1000 * (index + 1), sameScope: true });\n        await new Promise((resolve) => setTimeout(resolve, 1000 * (index + 1)));\n        await begin();\n      }\n    }\n    const disposition = failureDisposition(error, node, step.canvaMode);\n    let specialist: unknown = null;\n    // One dedicated diagnosis and one independent review. Never burn three analyses on a missing adapter.\n    if ([\"unknown\", \"transient\"].includes(disposition.kind) && process.env.OPENAI_API_KEY?.trim()) {\n      try {\n        const diagnosis = await analyzeRecovery({ objective: task.objective, taskTitle: task.title, step, node, error, artifacts, recurrence: attempts });\n        const review = await reviewRecoveryWithOpenAI({ objective: task.objective, taskTitle: task.title, step, node, error, firstDecision: diagnosis });\n        specialist = { provider: \"openai\", diagnosis, independentReview: review, codeApplied: false, externalClaudeInvoked: false };\n        await event(\"guardian_diagnosis\", { step: step.step, revision, specialist });\n      } catch (diagnosticError) { specialist = { available: false, message: message(diagnosticError), codeApplied: false }; }\n    }\n    return await finish(disposition.retry ? \"failed\" : \"blocked\", null, { ...disposition, attempts, history: retryEvents, specialist, at: new Date().toISOString() });\n  } catch (error) {\n    const disposition = failureDisposition(error, node, step.canvaMode);\n    if (!attempts) throw error;\n    return await finish(\"blocked\", null, { ...disposition, attempts, at: new Date().toISOString() });\n  }\n}\n","sha256":"66118bb4aaf66a4f0d06ed56c1d5cd53e4a7dc0ac229097aaee75d2452bb60d5"},{"path":"regente/lib/a5-preflight.ts","content":"import type { SupabaseClient } from \"@supabase/supabase-js\";\nimport type { PipelineStep } from \"./adapters\";\nimport { redactSecrets } from \"./phase-control.ts\";\n\ntype PersistedTask = {\n  id: string;\n  status: string;\n  current_step: number | null;\n  progress_percent: number | null;\n  next_action: string | null;\n  blocked_reason: string | null;\n  pipeline: unknown;\n};\n\ntype PersistedStep = {\n  step_number: number;\n  status: string;\n  depends_on: number[] | null;\n  node_ids: string[] | null;\n  action: string | null;\n  next_action: string | null;\n  revision?: number;\n};\n\ntype PersistedRun = {\n  id: string;\n  step_number: number;\n  node_id: string;\n  adapter: string;\n  status: string;\n  created_at: string;\n};\n\ntype CapabilityState = {\n  adapter: string;\n  connected: boolean;\n  credentialConfigured?: boolean;\n  operationalVerification?: \"verified_by_scoped_reads\" | \"not_verified\";\n};\n\nexport type A5PreflightReport = {\n  kind: \"local_recovery_preflight\";\n  generatedAt: string;\n  persistedState: {\n    taskStatus: string;\n    currentStep: number | null;\n    progressPercent: number;\n    nextAction: string | null;\n    blockedReason: string | null;\n    totalSteps: number;\n  };\n  /** Reuse eligibility requires revision/input fingerprint checks in the executor. */\n  reusableSucceededRuns: [];\n  historicalSucceededRuns: Array<{\n    runId: string;\n    step: number;\n    node: string;\n    adapter: string;\n    createdAt: string;\n    currentStepStatus: string | null;\n    currentStepRevision: number | null;\n    reuseVerified: false;\n  }>;\n  completedSteps: number[];\n  pendingDependencies: Array<{\n    step: number;\n    dependsOn: number[];\n    unresolved: number[];\n  }>;\n  blockers: Array<{\n    step: number;\n    status: string;\n    nodes: string[];\n    reason: string;\n  }>;\n  prospectiveContinuation: {\n    assumedCompletedStep: number;\n    nextStep: number | null;\n    node: string | null;\n    dependenciesSatisfied: boolean;\n  };\n  capabilityInventory: Record<\n    \"supabaseRls\" | \"A1\" | \"A2\" | \"A3\" | \"A4\" | \"A5\" | \"F6\" | \"F12\" | \"F13\",\n    CapabilityState\n  >;\n  verificationLimits: {\n    costLimits: \"not_verifiable\";\n    documentInputs: \"not_verifiable\";\n    canvaOAuth: \"not_verified\";\n    historicalRunReuse: \"not_verified\";\n  };\n  executionSafety: {\n    scopedByTaskIdAndUserId: true;\n    secretValuesIncluded: false;\n    providerCallsPerformed: false;\n    additionalAiConsumption: false;\n  };\n};\n\nfunction normalizePipeline(value: unknown): PipelineStep[] {\n  if (!Array.isArray(value)) return [];\n  return value.filter((step): step is PipelineStep => {\n    if (!step || typeof step !== \"object\") return false;\n    const candidate = step as Partial<PipelineStep>;\n    return Number.isInteger(candidate.step) && Array.isArray(candidate.nodes);\n  });\n}\n\nfunction uniqueSorted(values: number[]) {\n  return [...new Set(values)].sort((left, right) => left - right);\n}\n\nfunction safeText(value: string | null | undefined, limit = 1200) {\n  return typeof value === \"string\" ? redactSecrets(value).slice(0, limit) : null;\n}\n\nexport function buildA5PreflightReport(input: {\n  task: PersistedTask;\n  steps: PersistedStep[];\n  succeededRuns: PersistedRun[];\n  a5StepNumber: number;\n  openAICredentialConfigured: boolean;\n  generatedAt?: string;\n}): A5PreflightReport {\n  const pipeline = normalizePipeline(input.task.pipeline);\n  // A historical run can outlive an invalidated/revised checkpoint. It does not\n  // make that CURRENT phase completed and cannot satisfy its dependencies.\n  const completedSteps = uniqueSorted(input.steps\n    .filter((step) => [\"succeeded\", \"skipped\"].includes(step.status)).map((step) => step.step_number));\n  const completedSet = new Set(completedSteps);\n  const prospectiveCompleted = new Set([...completedSteps, input.a5StepNumber]);\n\n  const pendingDependencies = input.steps\n    .filter((step) => ![\"succeeded\", \"skipped\"].includes(step.status))\n    .map((step) => {\n      const dependsOn = uniqueSorted(step.depends_on || []);\n      return {\n        step: step.step_number,\n        dependsOn,\n        unresolved: dependsOn.filter((dependency) => !completedSet.has(dependency)),\n      };\n    })\n    .filter((step) => step.unresolved.length > 0);\n\n  const blockers = input.steps\n    .filter((step) => [\"blocked\", \"failed\", \"review\"].includes(step.status))\n    .map((step) => ({\n      step: step.step_number,\n      status: step.status,\n      nodes: (step.node_ids || []).map((node) => safeText(node, 120) || \"unknown\"),\n      reason: safeText(step.next_action || step.action) || \"Bloqueio persistido sem descrição adicional.\",\n    }));\n\n  const nextStep = [...input.steps]\n    .sort((left, right) => left.step_number - right.step_number)\n    .find((step) => {\n      if (step.step_number <= input.a5StepNumber || prospectiveCompleted.has(step.step_number)) return false;\n      // Database edges are authoritative, including legacy plans without dependsOn.\n      return (step.depends_on || []).every((dependency) => prospectiveCompleted.has(dependency));\n    }) || null;\n\n  const openAI = (adapter: string): CapabilityState => ({\n    adapter,\n    connected: true,\n    credentialConfigured: input.openAICredentialConfigured,\n  });\n\n  return {\n    kind: \"local_recovery_preflight\",\n    generatedAt: input.generatedAt || new Date().toISOString(),\n    persistedState: {\n      taskStatus: input.task.status,\n      currentStep: input.task.current_step,\n      progressPercent: Number(input.task.progress_percent || 0),\n      nextAction: safeText(input.task.next_action),\n      blockedReason: safeText(input.task.blocked_reason),\n      totalSteps: input.steps.length,\n    },\n    reusableSucceededRuns: [],\n    historicalSucceededRuns: input.succeededRuns.map((run) => ({\n      runId: run.id,\n      step: run.step_number,\n      node: safeText(run.node_id, 120) || \"unknown\",\n      adapter: safeText(run.adapter, 120) || \"unknown\",\n      createdAt: run.created_at,\n      currentStepStatus: input.steps.find((step) => step.step_number === run.step_number)?.status || null,\n      currentStepRevision: input.steps.find((step) => step.step_number === run.step_number)?.revision ?? null,\n      reuseVerified: false,\n    })),\n    completedSteps,\n    pendingDependencies,\n    blockers,\n    prospectiveContinuation: {\n      assumedCompletedStep: input.a5StepNumber,\n      nextStep: nextStep?.step_number || null,\n      node: safeText(nextStep?.node_ids?.[0] || pipeline.find((step) => step.step === nextStep?.step_number)?.nodes?.[0], 120),\n      dependenciesSatisfied: Boolean(nextStep),\n    },\n    capabilityInventory: {\n      supabaseRls: {\n        adapter: \"authenticated_supabase_rls\",\n        connected: true,\n        operationalVerification: \"verified_by_scoped_reads\",\n      },\n      A1: openAI(\"openai_agents\"),\n      A2: openAI(\"openai_agents\"),\n      A3: openAI(\"openai_agents\"),\n      A4: openAI(\"openai_agents_independent_review\"),\n      A5: { adapter: \"local_recovery_preflight\", connected: true },\n      F6: {\n        adapter: \"canva_portal_bridge\",\n        connected: true,\n        operationalVerification: \"not_verified\",\n      },\n      F12: { adapter: \"unavailable\", connected: false },\n      F13: { adapter: \"unavailable\", connected: false },\n    },\n    verificationLimits: {\n      costLimits: \"not_verifiable\",\n      documentInputs: \"not_verifiable\",\n      canvaOAuth: \"not_verified\",\n      historicalRunReuse: \"not_verified\",\n    },\n    executionSafety: {\n      scopedByTaskIdAndUserId: true,\n      secretValuesIncluded: false,\n      providerCallsPerformed: false,\n      additionalAiConsumption: false,\n    },\n  };\n}\n\nexport async function executeA5LocalPreflight(input: {\n  supabase: SupabaseClient;\n  taskId: string;\n  userId: string;\n  step: PipelineStep;\n}) {\n  const { data: runRow, error: runError } = await input.supabase\n    .from(\"regent_tool_runs\")\n    .insert({\n      task_id: input.taskId,\n      user_id: input.userId,\n      step_number: input.step.step,\n      node_id: \"A5\",\n      adapter: \"local_recovery_preflight\",\n      status: \"running\",\n      input: {\n        operation: \"inspect_persisted_recovery_state\",\n        scoped: true,\n      },\n    })\n    .select(\"id\")\n    .single();\n\n  if (runError || !runRow) {\n    throw new Error(\"Não foi possível registrar o preflight local A5.\");\n  }\n\n  try {\n    const [taskResult, stepsResult, runsResult] = await Promise.all([\n      input.supabase\n        .from(\"regent_tasks\")\n        .select(\"id,status,current_step,progress_percent,next_action,blocked_reason,pipeline\")\n        .eq(\"id\", input.taskId)\n        .eq(\"user_id\", input.userId)\n        .maybeSingle(),\n      input.supabase\n        .from(\"regent_task_steps\")\n        .select(\"step_number,status,depends_on,node_ids,action,next_action,revision\")\n        .eq(\"task_id\", input.taskId)\n        .eq(\"user_id\", input.userId)\n        .order(\"step_number\", { ascending: true }),\n      input.supabase\n        .from(\"regent_tool_runs\")\n        .select(\"id,step_number,node_id,adapter,status,created_at\")\n        .eq(\"task_id\", input.taskId)\n        .eq(\"user_id\", input.userId)\n        .eq(\"status\", \"succeeded\")\n        .order(\"created_at\", { ascending: true }),\n    ]);\n\n    if (taskResult.error || !taskResult.data) {\n      throw new Error(\"Não foi possível ler o estado persistente autenticado da tarefa no preflight A5.\");\n    }\n    if (stepsResult.error) throw new Error(\"Não foi possível ler os checkpoints autenticados no preflight A5.\");\n    if (runsResult.error) throw new Error(\"Não foi possível ler o histórico autenticado de runs no preflight A5.\");\n\n    const report = buildA5PreflightReport({\n      task: taskResult.data as PersistedTask,\n      steps: (stepsResult.data || []) as PersistedStep[],\n      succeededRuns: (runsResult.data || []) as PersistedRun[],\n      a5StepNumber: input.step.step,\n      openAICredentialConfigured: Boolean(process.env.OPENAI_API_KEY?.trim()),\n    });\n\n    const { error: updateError } = await input.supabase\n      .from(\"regent_tool_runs\")\n      .update({ status: \"succeeded\", output: report, updated_at: new Date().toISOString() })\n      .eq(\"id\", runRow.id)\n      .eq(\"task_id\", input.taskId)\n      .eq(\"user_id\", input.userId);\n    if (updateError) throw new Error(\"Não foi possível persistir o relatório do preflight A5.\");\n\n    return report;\n  } catch (error) {\n    const allowed = [\n      \"Não foi possível ler o estado persistente autenticado da tarefa no preflight A5.\",\n      \"Não foi possível ler os checkpoints autenticados no preflight A5.\",\n      \"Não foi possível ler o histórico autenticado de runs no preflight A5.\",\n      \"Não foi possível persistir o relatório do preflight A5.\",\n    ];\n    const description = error instanceof Error && allowed.includes(error.message)\n      ? error.message : \"O preflight local A5 não pôde confirmar o estado autenticado. Nenhuma continuação foi autorizada.\";\n    try {\n      const saved = await input.supabase.from(\"regent_tool_runs\").update({\n        status: \"failed\", output: { message: description }, updated_at: new Date().toISOString(),\n      }).eq(\"id\", runRow.id).eq(\"task_id\", input.taskId).eq(\"user_id\", input.userId);\n      if (saved.error) console.warn(\"regente_a5_failure_status_unconfirmed\", { taskId: input.taskId, runId: runRow.id });\n    } catch {\n      console.warn(\"regente_a5_failure_status_unconfirmed\", { taskId: input.taskId, runId: runRow.id });\n    }\n    throw new Error(description);\n  }\n}\n","sha256":"16600776b206d2e1fadc572e489dc90e005fc20c883c9654195098ee1cee8b6f"},{"path":"regente/lib/adapters.ts","content":"import { createHash, randomBytes } from \"node:crypto\";\nimport { Agent, run } from \"@openai/agents\";\nimport type { AgentInputItem } from \"@openai/agents\";\nimport type { SupabaseClient } from \"@supabase/supabase-js\";\nimport { z } from \"zod\";\nimport { guardianSpecialistInstructions } from \"./guardian-context\";\n\nexport type PipelineStep = {\n  step: number;\n  role: \"reference\" | \"planning\" | \"creative\" | \"critic\" | \"creation\" | \"picker\" | \"validation\";\n  nodes: string[];\n  action: string;\n  input: string;\n  expectedOutput: string;\n  executionState: \"planned\" | \"ready\" | \"requires_adapter\";\n  requiresApproval: boolean;\n  dependsOn?: number[];\n  checkpoint?: boolean;\n  canvaMode?: \"inspect\" | \"create\";\n  canvaSourceRunIds?: string[];\n  canvaDesignIds?: string[];\n  onUnavailable?: \"block\" | \"skip\";\n};\n\ntype PriorArtifact = {\n  step: number;\n  node: string;\n  output: unknown;\n};\n\nconst TextWorkerOutput = z.object({\n  result: z.string(),\n  notes: z.array(z.string()).max(8),\n});\n\nconst CanvaDesignSpec = z.object({\n  title: z.string().min(1).max(100),\n  width: z.number().int().min(320).max(4000),\n  height: z.number().int().min(320).max(4000),\n  pages: z.array(z.object({\n    eyebrow: z.string().max(90).default(\"\"),\n    headline: z.string().min(1).max(180),\n    body: z.string().max(500).default(\"\"),\n    cta: z.string().max(80).default(\"\"),\n    visualDirection: z.string().max(260).default(\"\"),\n    emphasis: z.enum([\"identity\", \"content\", \"urgency\", \"cta\", \"neutral\"]).default(\"neutral\"),\n  })).min(1).max(6),\n});\n\nfunction contextFromArtifacts(artifacts: PriorArtifact[]) {\n  if (!artifacts.length) return \"Nenhum artefato anterior.\";\n  return artifacts\n    .slice(-8)\n    .map((item) => `ETAPA ${item.step} / ${item.node}:\\n${typeof item.output === \"string\" ? item.output : JSON.stringify(item.output)}`)\n    .join(\"\\n\\n\");\n}\n\nfunction visualUrlsFromArtifacts(artifacts: PriorArtifact[]) {\n  const values: string[] = [];\n  const visit = (value: unknown) => {\n    if (!value || values.length >= 12) return;\n    if (typeof value === \"string\") {\n      if (/^https:\\/\\//i.test(value) && /(?:preview|export|\\.png(?:\\?|$)|\\.jpe?g(?:\\?|$)|\\.webp(?:\\?|$))/i.test(value)) {\n        values.push(value);\n      }\n      return;\n    }\n    if (Array.isArray(value)) {\n      value.forEach(visit);\n      return;\n    }\n    if (typeof value === \"object\") Object.values(value as Record<string, unknown>).forEach(visit);\n  };\n  artifacts.forEach((artifact) => visit(artifact.output));\n  return [...new Set(values)].slice(0, 12);\n}\n\nexport async function executeOpenAIWorker(input: {\n  node: string;\n  step: PipelineStep;\n  objective: string;\n  priorArtifacts: PriorArtifact[];\n}) {\n  const agent = new Agent({\n    name: `Executor ${input.node}`,\n    model: process.env.REGENT_WORKER_MODEL || process.env.REGENT_MODEL || \"gpt-5.6-sol\",\n    instructions: [\n      \"Você é um nó executor da rede Optótica + ENSAVIM.\",\n      \"Execute somente a etapa recebida. Não replaneje a tarefa inteira.\",\n      \"Execute apenas o nó recebido; referências a outras ferramentas não comprovam execução dessas ferramentas.\",\n      \"Não invente fontes, consultas jurídicas, vigência de normas, autorizações, documentos, gastos nem resultados externos. Sem fonte verificável, declare a limitação.\",\n      \"Use o contexto anterior quando ele melhorar a consistência.\",\n      \"Entregue conteúdo específico, aplicável e detalhado; evite prompts genéricos.\",\n      \"Se estiver revisando, critique e devolva uma versão melhorada.\",\n    ].join(\"\\n\"),\n    outputType: TextWorkerOutput,\n  });\n\n  const prompt = [\n    `OBJETIVO GERAL: ${input.objective}`,\n    `NÓ: ${input.node}`,\n    `FUNÇÃO DA ETAPA: ${input.step.role}`,\n    `AÇÃO: ${input.step.action}`,\n    `ENTRADA: ${input.step.input}`,\n    `SAÍDA ESPERADA: ${input.step.expectedOutput}`,\n    \"\",\n    \"ARTEFATOS ANTERIORES:\",\n    contextFromArtifacts(input.priorArtifacts),\n  ].join(\"\\n\");\n\n  const visualUrls = visualUrlsFromArtifacts(input.priorArtifacts);\n  const agentInput: string | AgentInputItem[] = visualUrls.length\n    ? [{\n        role: \"user\",\n        content: [\n          { type: \"input_text\", text: prompt },\n          ...visualUrls.map((image) => ({ type: \"input_image\" as const, image, detail: \"high\" })),\n        ],\n      }]\n    : prompt;\n  const result = await run(agent, agentInput, { maxTurns: 2, signal: AbortSignal.timeout(120_000) });\n  if (!result.finalOutput) throw new Error(\"O executor OpenAI retornou saída vazia.\");\n  return result.finalOutput;\n}\n\nexport async function executeIndependentOpenAIReviewer(input: {\n  step: PipelineStep;\n  objective: string;\n  priorArtifacts: PriorArtifact[];\n}) {\n  if (!process.env.OPENAI_API_KEY?.trim()) {\n    return {\n      blocked: true as const,\n      reason: \"OPENAI_API_KEY não configurada no ambiente do Regente.\",\n    };\n  }\n\n  const agent = new Agent({\n    name: \"Revisor independente A4\",\n    model:\n      process.env.REGENT_REVIEW_MODEL ||\n      process.env.REGENT_RECOVERY_MODEL ||\n      process.env.REGENT_WORKER_MODEL ||\n      process.env.REGENT_MODEL ||\n      \"gpt-5.6-sol\",\n    instructions: [\n      \"Você é o revisor independente A4 da rede Optótica + ENSAVIM.\",\n      guardianSpecialistInstructions(\"openai\"),\n      \"Trabalhe em uma execução separada dos demais nós e faça uma crítica genuína.\",\n      \"Não apenas confirme o material anterior: identifique falhas, riscos, lacunas e alternativas.\",\n      \"Preserve autenticação, RLS, aprovação humana e limites de custo.\",\n      \"Devolva uma versão melhorada e notas objetivas sobre as mudanças.\",\n    ].join(\"\\n\"),\n    outputType: TextWorkerOutput,\n  });\n\n  const prompt = [\n    `OBJETIVO GERAL: ${input.objective}`,\n    `FUNÇÃO DA ETAPA: ${input.step.role}`,\n    `AÇÃO: ${input.step.action}`,\n    `ENTRADA: ${input.step.input}`,\n    `SAÍDA ESPERADA: ${input.step.expectedOutput}`,\n    \"\",\n    \"ARTEFATOS ANTERIORES:\",\n    contextFromArtifacts(input.priorArtifacts),\n    \"\",\n    \"Faça uma revisão crítica independente e devolva a melhor versão possível.\",\n  ].join(\"\\n\");\n\n  const result = await run(agent, prompt, { maxTurns: 2, signal: AbortSignal.timeout(120_000) });\n  if (!result.finalOutput) {\n    throw new Error(\"O revisor independente A4 retornou saída vazia.\");\n  }\n  return {\n    blocked: false as const,\n    result: result.finalOutput.result,\n    notes: result.finalOutput.notes,\n  };\n}\n\nexport async function buildCanvaSpec(input: {\n  step: PipelineStep;\n  objective: string;\n  title: string;\n  priorArtifacts: PriorArtifact[];\n  variants: number;\n}) {\n  const agent = new Agent({\n    name: \"Arquiteto de design para Canva\",\n    model: process.env.REGENT_WORKER_MODEL || process.env.REGENT_MODEL || \"gpt-5.6-sol\",\n    instructions: [\n      \"Converta o briefing e os artefatos anteriores em uma especificação visual concreta para Canva.\",\n      \"Não invente dados factuais não fornecidos.\",\n      \"Para criativos verticais use 1080x1920 salvo se a tarefa pedir outra dimensão.\",\n      \"Para sequências de anúncio, normalmente use 4 páginas: identidade, conteúdo, urgência e CTA.\",\n      \"Mantenha textos curtos e hierarquia clara. A saída será importada como design editável.\",\n    ].join(\"\\n\"),\n    outputType: CanvaDesignSpec,\n  });\n\n  const prompt = [\n    `TAREFA: ${input.title}`,\n    `OBJETIVO: ${input.objective}`,\n    `AÇÃO CANVA: ${input.step.action}`,\n    `ENTRADA: ${input.step.input}`,\n    `SAÍDA ESPERADA: ${input.step.expectedOutput}`,\n    `VARIANTES SOLICITADAS: ${Math.max(1, Math.min(3, input.variants))}`,\n    \"\",\n    \"ARTEFATOS ANTERIORES:\",\n    contextFromArtifacts(input.priorArtifacts),\n  ].join(\"\\n\");\n\n  const result = await run(agent, prompt, { maxTurns: 2, signal: AbortSignal.timeout(120_000) });\n  if (!result.finalOutput) throw new Error(\"Não foi possível montar a especificação do Canva.\");\n  return result.finalOutput;\n}\n\nfunction tokenHash(token: string) {\n  return createHash(\"sha256\").update(token).digest(\"hex\");\n}\n\ntype CanvaBridgeContext = {\n  supabase: SupabaseClient;\n  taskId: string;\n  userId: string;\n  step: PipelineStep;\n  revision?: number;\n  executionId: string;\n  executionInvocationId: string;\n};\n\nclass CanvaBridgeError extends Error {\n  constructor(message: string, public status = 503, public code = \"canva_bridge_failed\") { super(message); }\n}\n\nfunction safeCanvaBridgeUrl(value: unknown) {\n  if (typeof value !== \"string\") return false;\n  try {\n    const url = new URL(value);\n    return url.protocol === \"https:\" && !url.username && !url.password && !url.port &&\n      (url.hostname === \"canva.com\" || url.hostname.endsWith(\".canva.com\"));\n  } catch { return false; }\n}\n\n/** HTTP 200 alone never proves that a Canva design exists or was saved. */\nexport function validCanvaBridgeOutput(value: unknown, expected: { mode: \"create\" | \"inspect\"; runId: string; step: number; revision: number; executionId: string; count: number; designIds?: string[] }) {\n  const output = value as { mode?: unknown; complete?: unknown; runId?: unknown; step?: unknown; revision?: unknown; executionId?: unknown; designs?: unknown } | null;\n  if (!output || output.mode !== expected.mode || output.complete !== true || output.runId !== expected.runId ||\n    output.step !== expected.step || output.revision !== expected.revision || output.executionId !== expected.executionId ||\n    !Array.isArray(output.designs) || output.designs.length !== expected.count) return false;\n  const ids = new Set<string>();\n  return output.designs.every((value) => {\n    const design = value as { id?: unknown; editUrl?: unknown; viewUrl?: unknown; inspectionComplete?: unknown; pageCount?: unknown; pages?: unknown; previewUrls?: unknown } | null;\n    if (!design || typeof design.id !== \"string\" || !/^[A-Za-z0-9_-]{6,80}$/.test(design.id) || ids.has(design.id) ||\n      !safeCanvaBridgeUrl(design.editUrl) || !safeCanvaBridgeUrl(design.viewUrl)) return false;\n    ids.add(design.id);\n    if (expected.mode === \"create\") return true;\n    return expected.designIds?.includes(design.id) === true && design.inspectionComplete === true &&\n      Number.isInteger(design.pageCount) && Number(design.pageCount) > 0 && Array.isArray(design.pages) &&\n      design.pages.length === design.pageCount && Array.isArray(design.previewUrls) && design.previewUrls.length > 0 &&\n      design.previewUrls.every(safeCanvaBridgeUrl);\n  });\n}\n\nasync function callCanvaPortal(input: CanvaBridgeContext, mode: \"create\" | \"inspect\", details: Record<string, unknown>, count: number, designIds?: string[]) {\n  const revision = input.revision ?? 1;\n  if (!Number.isInteger(revision) || revision < 1 || !input.executionId || !input.executionInvocationId) {\n    throw new CanvaBridgeError(\"A fase Canva precisa de revisão e invocação autorizadas. Atualize o monitor.\", 409, \"canva_execution_fence_required\");\n  }\n  const portal = new URL(process.env.REGENT_PORTAL_ORIGIN || \"https://app.optotica.com.br\");\n  if ((portal.protocol !== \"https:\" && !(portal.protocol === \"http:\" && portal.hostname === \"localhost\")) || portal.username || portal.password) {\n    throw new CanvaBridgeError(\"REGENT_PORTAL_ORIGIN precisa de um endereço HTTPS válido, sem credenciais.\", 503, \"invalid_portal_origin\");\n  }\n  const token = randomBytes(32).toString(\"base64url\");\n  const digest = tokenHash(token);\n  const { data: toolRun, error } = await input.supabase.from(\"regent_tool_runs\").insert({\n    task_id: input.taskId, user_id: input.userId, step_number: input.step.step, node_id: \"F6\",\n    adapter: mode === \"create\" ? \"canva_portal_bridge\" : \"canva_portal_inspect\", status: \"pending\",\n    input: { mode, step: input.step, stepRevision: revision, executionId: input.executionId,\n      executionInvocationId: input.executionInvocationId, ...details },\n    token_hash: digest, token_expires_at: new Date(Date.now() + 5 * 60_000).toISOString(),\n  }).select(\"id\").single();\n  if (error || !toolRun) throw new CanvaBridgeError(\"Não foi possível persistir a preparação da fase Canva; nenhuma chamada ao Portal foi feita.\", 503, \"canva_prepare_not_persisted\");\n  const expected = { mode, runId: toolRun.id, step: input.step.step, revision, executionId: input.executionId, count, designIds };\n\n  async function canonicalRun() {\n    const saved = await input.supabase.from(\"regent_tool_runs\").select(\"status,output\")\n      .eq(\"id\", toolRun!.id).eq(\"task_id\", input.taskId).eq(\"user_id\", input.userId).eq(\"node_id\", \"F6\").maybeSingle();\n    if (saved.error || !saved.data) throw new CanvaBridgeError(\"Não foi possível verificar o run Canva persistido. Não repita a criação até conferir o efeito externo.\", 503, \"canva_run_not_verified\");\n    return saved.data;\n  }\n  async function closeUnclaimed(message: string) {\n    // CAS with the same token: if Portal has claimed it, preserve its canonical output untouched.\n    const saved = await input.supabase.from(\"regent_tool_runs\").update({\n      status: \"failed\", token_hash: null, token_expires_at: null, updated_at: new Date().toISOString(),\n      output: { mode, complete: false, designs: [], jobs: [], externalEffect: \"none\", runId: toolRun!.id,\n        step: input.step.step, revision, executionId: input.executionId, message },\n    }).eq(\"id\", toolRun!.id).eq(\"task_id\", input.taskId).eq(\"user_id\", input.userId).eq(\"status\", \"pending\")\n      .eq(\"token_hash\", digest).select(\"id\").maybeSingle();\n    if (saved.error) throw new CanvaBridgeError(\"Não foi possível invalidar a credencial não consumida. Confira o run Canva original antes de retomar.\", 503, \"canva_pending_not_persisted\");\n    return Boolean(saved.data);\n  }\n\n  let response: Response;\n  try {\n    response = await fetch(new URL(\"/api/internal/regente/canva\", portal.origin), {\n      method: \"POST\", cache: \"no-store\", redirect: \"error\", signal: AbortSignal.timeout(110_000),\n      headers: { \"Content-Type\": \"application/json\" }, body: JSON.stringify({ runId: toolRun.id, token }),\n    });\n  } catch {\n    const persisted = await canonicalRun();\n    if (persisted.status === \"succeeded\" && validCanvaBridgeOutput(persisted.output, expected)) return persisted.output;\n    const unclaimed = await closeUnclaimed(\"O transporte com o Portal foi interrompido antes de consumir esta credencial.\");\n    throw new CanvaBridgeError(unclaimed\n      ? \"O Portal não consumiu a chamada Canva; a credencial foi invalidada sem efeito externo. Autorize somente esta fase para retomar.\"\n      : `O efeito externo Canva não foi confirmado. Confira o run ${toolRun.id}, os jobs e os outputs preservados; não repita a criação.`,\n      503, unclaimed ? \"canva_portal_not_claimed\" : \"canva_external_effect_unknown\");\n  }\n  const body = await response.json().catch(() => null);\n  if (!response.ok) {\n    const persisted = await canonicalRun();\n    if (persisted.status === \"succeeded\" && validCanvaBridgeOutput(persisted.output, expected)) return persisted.output;\n    if (persisted.status === \"pending\") await closeUnclaimed(\"O Portal recusou a chamada Canva antes de consumir a credencial.\");\n    throw new CanvaBridgeError(typeof body?.message === \"string\" ? body.message.slice(0, 2200) : `O Portal não concluiu a fase Canva (HTTP ${response.status}). Confira o run original.`, response.status);\n  }\n  if (!validCanvaBridgeOutput(body, expected)) {\n    await closeUnclaimed(\"O Portal retornou HTTP 200 sem confirmar o contrato de output Canva.\");\n    throw new CanvaBridgeError(`O Portal retornou um output Canva inválido. Confira o run ${toolRun.id}; um HTTP 200 não autoriza repetir a criação.`, 502, \"invalid_canva_bridge_output\");\n  }\n  const persisted = await canonicalRun();\n  if (persisted.status !== \"succeeded\" || !validCanvaBridgeOutput(persisted.output, expected)) {\n    throw new CanvaBridgeError(`O resultado Canva não foi confirmado no banco. Confira o run ${toolRun.id}; outputs parciais não serão sobrescritos.`, 503, \"canva_result_not_persisted\");\n  }\n  // The Portal is the sole writer of external results. Never overwrite it with a transport response.\n  return persisted.output;\n}\n\nexport async function executeCanvaBridge(input: CanvaBridgeContext & {\n  spec: z.infer<typeof CanvaDesignSpec>;\n  variants: number;\n}) {\n  if (!Number.isInteger(input.variants) || input.variants < 1 || input.variants > 3) throw new CanvaBridgeError(\"Quantidade de variantes Canva inválida.\", 422);\n  const previous = await input.supabase.from(\"regent_tool_runs\").select(\"id,status,output\")\n    .eq(\"task_id\", input.taskId).eq(\"user_id\", input.userId).eq(\"step_number\", input.step.step).eq(\"adapter\", \"canva_portal_bridge\")\n    .in(\"status\", [\"pending\", \"running\", \"failed\"]);\n  if (previous.error) throw new CanvaBridgeError(\"Não foi possível conferir criações Canva anteriores. Não iniciar outra importação.\");\n  const unsafe = previous.data?.find((run) => {\n    const output = run.output as { externalEffect?: unknown; jobs?: unknown[]; designs?: unknown[] } | null;\n    return run.status !== \"failed\" || output?.externalEffect !== \"none\" || Boolean(output.jobs?.length || output.designs?.length);\n  });\n  if (unsafe) throw new CanvaBridgeError(`Existe uma criação Canva não reconciliada no run ${unsafe.id}. Confira os designs e jobs preservados antes de autorizar outra importação.`, 409, \"canva_external_effect_unknown\");\n  return callCanvaPortal(input, \"create\", { spec: input.spec, variants: input.variants }, input.variants);\n}\n\nexport async function executeCanvaInspectBridge(input: CanvaBridgeContext) {\n  const sourceRunIds = [...new Set(input.step.canvaSourceRunIds || [])];\n  const designIds = [...new Set(input.step.canvaDesignIds || [])];\n  if (!sourceRunIds.length || !designIds.length) {\n    throw new Error(\"A inspeção Canva precisa de referências canônicas aprovadas.\");\n  }\n\n  if (sourceRunIds.length > 20 || designIds.length > 10 || designIds.some((id) => !/^[A-Za-z0-9_-]{6,80}$/.test(id))) {\n    throw new CanvaBridgeError(\"Referências canônicas Canva inválidas.\", 422);\n  }\n  return callCanvaPortal(input, \"inspect\", { sourceRunIds, designIds }, designIds.length, designIds);\n}\n\nexport function isOpenAINode(node: string) {\n  return [\"A1\", \"A2\", \"A3\"].includes(node);\n}\n","sha256":"20725d2e726f5573e3d58743a1ecd3d51a79dcc46bc70558204a9b71502aca62"},{"path":"regente/lib/recovery.ts","content":"import { Agent, run } from \"@openai/agents\";\nimport { z } from \"zod\";\nimport type { PipelineStep } from \"./adapters\";\nimport { guardianSpecialistInstructions, loadGuardianSourceSnapshot } from \"./guardian-context\";\nimport { redactSecrets } from \"./phase-control\";\n\nexport type RecoveryArtifact = { step: number; node: string; output: unknown };\n\nconst RecoveryDecision = z.object({\n  diagnosis: z.string(),\n  errorClass: z.enum([\"transient\", \"timeout\", \"access\", \"payload\", \"adapter\", \"code\", \"unknown\"]),\n  sameErrorLikely: z.boolean(),\n  canRetry: z.boolean(),\n  retryStrategy: z.enum([\"same\", \"rewrite_input\", \"reduce_scope\", \"none\"]),\n  revisedAction: z.string().nullable(),\n  revisedInput: z.string().nullable(),\n  revisedExpectedOutput: z.string().nullable(),\n  reduceVariantsTo: z.number().int().min(1).max(3).nullable(),\n  codeChangeRequired: z.boolean(),\n  patchProposal: z.string().nullable(),\n  confidence: z.enum([\"low\", \"medium\", \"high\"]),\n  operatorNote: z.string(),\n});\n\nexport type RecoveryDecisionOutput = z.infer<typeof RecoveryDecision>;\n\nconst IndependentRecoveryReview = z.object({\n  review: z.string().min(1),\n});\n\nfunction normalizeError(error: unknown) {\n  const message = redactSecrets(error instanceof Error ? error.message : String(error || \"Unknown error\"));\n  return message\n    .replace(/[0-9a-f]{8}-[0-9a-f-]{20,}/gi, \"<uuid>\")\n    .replace(/\\b\\d{4,}\\b/g, \"<n>\")\n    .replace(/https?:\\/\\/[^\\s]+/g, \"<url>\")\n    .replace(/\\s+/g, \" \")\n    .trim()\n    .slice(0, 1200);\n}\n\nexport function errorFingerprint(error: unknown) {\n  return normalizeError(error).toLowerCase();\n}\nfunction artifactsText(artifacts: RecoveryArtifact[]) {\n  if (!artifacts.length) return \"Nenhum output anterior.\";\n  return redactSecrets(artifacts.slice(-6).map((item) =>\n    `ETAPA ${item.step} / ${item.node}\\n${typeof item.output === \"string\" ? item.output : JSON.stringify(item.output)}`,\n  ).join(\"\\n\\n\")).slice(0, 12000);\n}\nasync function sourceContext(node: string) {\n  const sources = await loadGuardianSourceSnapshot();\n  const required = new Set([\n    \"regente/lib/phase-control.ts\", \"regente/lib/phase-executor.ts\", \"regente/lib/orchestra-health.ts\",\n    \"regente/app/api/tasks/[taskId]/execute/route.ts\", \"regente/app/api/tasks/[taskId]/decision/route.ts\",\n    \"regente/lib/adapters.ts\", ...(node === \"F6\" ? [\"app/api/internal/regente/canva/route.ts\"] : []),\n  ]);\n  return sources.filter((source) => required.has(source.path)).map((source) =>\n    `### ${source.path} @ ${source.commit || \"commit não comprovado\"} / ${source.state}\\n${source.content || \"Fonte indisponível: não presumir seu conteúdo.\"}`,\n  ).join(\"\\n\\n\").slice(0, 62000);\n}\nexport async function analyzeRecovery(input: {\n  objective: string;\n  taskTitle: string;\n  step: PipelineStep;\n  node: string;\n  error: unknown;\n  artifacts: RecoveryArtifact[];\n  previousRecovery?: RecoveryDecisionOutput | null;\n  independentReview?: string | null;\n  recurrence: number;\n}) {\n  const agent = new Agent({\n    name: \"Guardião externo OpenAI — Engenharia do Regente\",\n    model: process.env.REGENT_RECOVERY_MODEL || \"gpt-5.6-sol\",\n    modelSettings: {\n      reasoning: { effort: \"high\" },\n      text: { verbosity: \"medium\" },\n    },\n    instructions: [\n      guardianSpecialistInstructions(\"openai\"),\n      \"Você é o engenheiro de recuperação do Regente Optótica.\",\n      \"Sua função é diagnosticar falhas de execução de pipeline e propor a menor correção segura.\",\n      \"Você conhece a arquitetura do Regente e recebe trechos reais do código de produção.\",\n      \"Priorize correções operacionais que permitam retomar a etapa sem alterar produção.\",\n      \"Se o problema exigir mudança de código, não finja que aplicou: marque codeChangeRequired=true e proponha patch objetivo.\",\n      \"Nunca contorne autenticação, RLS, autorização humana, limites de custo ou segurança.\",\n      \"Não repita uma estratégia que já falhou sem uma razão concreta.\",\n      \"O runtime classifica erros determinísticos localmente e só repete falhas transitórias em operações seguras. Não invente três tentativas nem recomende repetir configuração ausente.\",\n      \"Seu diagnóstico é único e pode ser revisto pelo segundo guardião em contexto separado. Uma proposta de patch não significa código aplicado.\",\n      \"Quando houver revisão independente do A4, trate-a como contraponto: compare hipóteses, resolva divergências e produza uma decisão consolidada.\",\n    ].join(\"\\n\"),\n    outputType: RecoveryDecision,\n  });\n\n  const code = await sourceContext(input.node);\n  const prompt = [\n    `TAREFA: ${input.taskTitle}`,\n    `OBJETIVO: ${input.objective}`,\n    `ETAPA: ${input.step.step} / ${input.step.role}`,\n    `NÓ: ${input.node}`,\n    `AÇÃO: ${input.step.action}`,\n    `ENTRADA: ${input.step.input}`,\n    `SAÍDA ESPERADA: ${input.step.expectedOutput}`,\n    `RECORRÊNCIA DO ERRO: ${input.recurrence}`,\n    \"\",\n    \"ERRO NORMALIZADO:\",\n    normalizeError(input.error),\n    \"\",\n    \"OUTPUTS ANTERIORES:\",\n    artifactsText(input.artifacts),\n    \"\",\n    input.previousRecovery ? `RECUPERAÇÃO ANTERIOR:\\n${JSON.stringify(input.previousRecovery)}\\n` : \"\",\n    input.independentReview ? `REVISÃO INDEPENDENTE A4 (OPENAI, CONTEXTO SEPARADO):\\n${input.independentReview}\\n` : \"\",\n    \"CÓDIGO / ARQUITETURA RELEVANTE:\",\n    code,\n  ].filter(Boolean).join(\"\\n\");\n\n  const result = await run(agent, prompt, { maxTurns: 2, signal: AbortSignal.timeout(90_000) });\n  if (!result.finalOutput) throw new Error(\"Recovery Engineer retornou saída vazia.\");\n  return result.finalOutput;\n}\n\nexport async function reviewRecoveryWithOpenAI(input: {\n  objective: string;\n  taskTitle: string;\n  step: PipelineStep;\n  node: string;\n  error: unknown;\n  firstDecision: RecoveryDecisionOutput;\n}) {\n  const code = await sourceContext(input.node);\n  const agent = new Agent({\n    name: \"A4 — Revisor independente de recovery\",\n    model:\n      process.env.REGENT_REVIEW_MODEL ||\n      process.env.REGENT_RECOVERY_MODEL ||\n      process.env.REGENT_MODEL ||\n      \"gpt-5.6-sol\",\n    modelSettings: {\n      reasoning: { effort: \"high\" },\n      text: { verbosity: \"medium\" },\n    },\n    instructions: [\n      \"Você é o revisor independente A4 do mecanismo de recuperação do Regente.\",\n      guardianSpecialistInstructions(\"openai\"),\n      \"Você executa com contexto separado do A5 e deve produzir um contraponto real.\",\n      \"Analise o erro, a hipótese mais recente do Recovery Engineer e o código real.\",\n      \"Destaque discordâncias, hipóteses alternativas e testes objetivos.\",\n      \"Procure diagnóstico errado, repetição inútil, problemas de acesso, timeout, payload e bug de programação.\",\n      \"Não proponha atalhos que removam autenticação, RLS, aprovação humana ou controles de custo.\",\n    ].join(\"\\n\"),\n    outputType: IndependentRecoveryReview,\n  });\n\n  const prompt = [\n    `TAREFA: ${input.taskTitle}`,\n    `OBJETIVO: ${input.objective}`,\n    `ETAPA: ${input.step.step} / ${input.step.role} / nó ${input.node}`,\n    `ERRO: ${normalizeError(input.error)}`,\n    `PRIMEIRA CORREÇÃO PROPOSTA: ${JSON.stringify(input.firstDecision)}`,\n    \"\",\n    \"CÓDIGO RELEVANTE:\",\n    code,\n  ].join(\"\\n\");\n\n  const result = await run(agent, prompt, { maxTurns: 2, signal: AbortSignal.timeout(90_000) });\n  if (!result.finalOutput) {\n    throw new Error(\"O revisor independente A4 retornou saída vazia.\");\n  }\n  return { available: true as const, review: result.finalOutput.review };\n}\n\nexport function applyRecoveryDecision(step: PipelineStep, decision: RecoveryDecisionOutput) {\n  return {\n    ...step,\n    action: decision.revisedAction?.trim() || step.action,\n    input: decision.revisedInput?.trim() || step.input,\n    expectedOutput: decision.revisedExpectedOutput?.trim() || step.expectedOutput,\n  };\n}\n","sha256":"4911119a2c0a97526c84427f99e45efab9b8d38bf430d2cb2ff2c9b6dbe05b75"},{"path":"regente/lib/orchestra-health.ts","content":"import type { SupabaseClient } from \"@supabase/supabase-js\";\nimport { NETWORK_NODES } from \"./nodes.ts\";\nimport { credentialPresent, guardianProviders, type ProviderEnvironment } from \"./provider-registry.ts\";\n\nexport type HealthState = \"healthy\" | \"attention\" | \"unknown\" | \"unavailable\" | \"manual\";\nexport type OrchestraCheck = {\n  id: string;\n  label: string;\n  category: \"provider\" | \"tool\" | \"runtime\" | \"security\";\n  state: HealthState;\n  required: boolean;\n  blocking: boolean;\n  adapterConnected: boolean;\n  configured: boolean | null;\n  authenticated: boolean | null;\n  authorized: boolean | null;\n  operational: boolean | null;\n  financial: \"not_verified\";\n  account: string | null;\n  detail: string;\n  action: string | null;\n  observedSuccessAt: string | null;\n  requiresManualReview?: boolean;\n};\n\nexport type CanvaHealthEvidence = {\n  configured: boolean;\n  clientId?: string | null;\n  authenticated: boolean | null;\n  authorized: boolean | null;\n  operational: boolean | null;\n  identity: { userId: string; teamId: string } | null;\n  identityMatchesStored: boolean | null;\n  tokenState: \"absent\" | \"expired\" | \"current\" | \"invalid\" | \"not_checked\";\n  detail: string;\n  action: string | null;\n};\n\ntype ProviderEvidence = {\n  authenticated: boolean | null;\n  authorized: boolean | null;\n  detail: string;\n  action: string | null;\n};\n\ntype RunEvidence = {\n  node_id: string;\n  adapter: string;\n  status: string;\n  updated_at: string;\n};\n\ntype TaskEvidence = {\n  id: string;\n  status: string;\n  updated_at: string;\n  execution_lease_until?: string | null;\n};\n\nconst AUTOMATIC_NODES = new Set([\"A1\", \"A2\", \"A3\", \"A4\", \"A5\", \"F6\"]);\nconst OPENAI_NODES = new Set([\"A1\", \"A2\", \"A3\", \"A4\"]);\nconst DEFAULT_PORTAL_ORIGIN = \"https://app.optotica.com.br\";\n\nfunction currentCommit(env: ProviderEnvironment) {\n  return [env.VERCEL_GIT_COMMIT_SHA?.trim(), env.REGENT_SOURCE_COMMIT?.trim()]\n    .find((value): value is string => Boolean(value && /^[a-f0-9]{40}$/i.test(value))) || null;\n}\n\nexport function portalOrigin(env: ProviderEnvironment = process.env) {\n  try {\n    const url = new URL(env.REGENT_PORTAL_ORIGIN?.trim() || DEFAULT_PORTAL_ORIGIN);\n    if (url.username || url.password || url.search || url.hash || url.pathname !== \"/\") return null;\n    if (url.protocol !== \"https:\" && !(url.protocol === \"http:\" && url.hostname === \"localhost\" && env.NODE_ENV !== \"production\")) return null;\n    return url.origin;\n  } catch { return null; }\n}\n\nexport function buildOrchestraHealth(input: {\n  depth: \"basic\" | \"deep\";\n  databaseOperational: boolean;\n  databaseDetail?: string;\n  requiredNodes?: string[];\n  env?: ProviderEnvironment;\n  generatedAt?: string;\n  taskId?: string;\n  tasks?: TaskEvidence[];\n  recentRuns?: RunEvidence[];\n  canvaEvidence?: CanvaHealthEvidence | null;\n  openAIEvidence?: ProviderEvidence | null;\n}) {\n  const env = input.env || process.env;\n  const requiredNodes = new Set(input.requiredNodes || []);\n  const providers = guardianProviders(env);\n  const openAIConfigured = credentialPresent(\"OPENAI_API_KEY\", env);\n  const workflowConfigured = credentialPresent(\"REGENT_WORKFLOW_SECRET\", env);\n  const generatedAt = input.generatedAt || new Date().toISOString();\n  const recentSuccess = (node: string) => (input.recentRuns || [])\n    .filter((run) => run.node_id === node && run.status === \"succeeded\")\n    .sort((a, b) => b.updated_at.localeCompare(a.updated_at))[0]?.updated_at || null;\n\n  const check = (value: Omit<OrchestraCheck, \"financial\" | \"blocking\" | \"observedSuccessAt\"> & { observedSuccessAt?: string | null }): OrchestraCheck => ({\n    ...value,\n    financial: \"not_verified\",\n    observedSuccessAt: value.observedSuccessAt || null,\n    blocking: value.required && (\n      !value.adapterConnected || value.configured === false || value.authenticated === false ||\n      value.authorized === false || value.operational === false\n    ),\n  });\n\n  const checks: OrchestraCheck[] = [\n    check({\n      id: \"runtime:supabase\", label: \"Supabase / estado persistente\", category: \"runtime\",\n      state: input.databaseOperational ? \"healthy\" : \"attention\", required: true,\n      adapterConnected: true, configured: true, authenticated: input.databaseOperational,\n      authorized: input.databaseOperational, operational: input.databaseOperational, account: null,\n      detail: input.databaseDetail || \"Consultas com sessão autenticada e filtro user_id; auditoria completa das políticas RLS não realizada.\",\n      action: input.databaseOperational ? null : \"Revalidar sessão, projeto Supabase, grants e políticas RLS.\",\n    }),\n    check({\n      id: \"provider:openai\", label: providers[0].label, category: \"provider\",\n      state: !openAIConfigured || input.openAIEvidence?.authenticated === false || input.openAIEvidence?.authorized === false ? \"attention\" : \"unknown\",\n      required: [...requiredNodes].some((node) => OPENAI_NODES.has(node)), adapterConnected: true,\n      configured: openAIConfigured, authenticated: input.openAIEvidence?.authenticated ?? null,\n      authorized: input.openAIEvidence?.authorized ?? null, operational: null, account: null,\n      detail: input.openAIEvidence?.detail || (openAIConfigured\n        ? \"Chave presente neste runtime. Presença não comprova autenticação, acesso ao modelo ou saldo.\"\n        : \"OPENAI_API_KEY ausente neste runtime; nenhuma conta Anthropic é necessária para corrigir a rota OpenAI.\"),\n      action: input.openAIEvidence?.action || (!openAIConfigured ? \"Configurar OPENAI_API_KEY no projeto Regente e publicar o runtime correto.\" : null),\n      observedSuccessAt: recentSuccess(\"A4\") || recentSuccess(\"A1\") || recentSuccess(\"A2\") || recentSuccess(\"A3\"),\n    }),\n    check({\n      id: \"provider:claude\", label: providers[1].label, category: \"provider\", state: \"manual\",\n      required: false, adapterConnected: true, configured: true,\n      authenticated: null, authorized: null, operational: null, account: null,\n      detail: \"Revisão externa por pacote versionado e importação humana. Conta Claude.ai e autoria do parecer não foram verificadas pelo Regente; nenhuma execução Anthropic é presumida.\",\n      action: \"Baixar o pacote do guardião Claude e importar o parecer externo. A API Claude é opcional e não bloqueia a pipeline OpenAI.\",\n    }),\n    check({\n      id: \"runtime:workflow\", label: \"Vercel Workflow / execução durável\", category: \"runtime\",\n      state: workflowConfigured ? \"unknown\" : \"attention\",\n      required: [...requiredNodes].some((node) => node !== \"A5\"), adapterConnected: true,\n      configured: workflowConfigured, authenticated: null, authorized: null, operational: null,\n      account: null, detail: \"Segredo e código durável inventariados; um teste de presença não prova queue, deployment, lease ou execução atual.\",\n      action: workflowConfigured ? null : \"Configurar REGENT_WORKFLOW_SECRET no runtime que executa a missão e publicar.\",\n    }),\n  ];\n\n  for (const node of NETWORK_NODES) {\n    const connected = AUTOMATIC_NODES.has(node.id);\n    const isAI = OPENAI_NODES.has(node.id);\n    const required = requiredNodes.has(node.id);\n    if (isAI) {\n      const provider = checks.find((item) => item.id === \"provider:openai\")!;\n      checks.push(check({ ...provider, id: `node:${node.id}`, label: `${node.id} — ${node.role}`,\n        category: \"provider\", required, observedSuccessAt: recentSuccess(node.id) }));\n    } else if (node.id === \"A5\") {\n      checks.push(check({ id: \"node:A5\", label: \"A5 — preflight local\", category: \"runtime\",\n        state: input.databaseOperational ? \"healthy\" : \"attention\", required, adapterConnected: true,\n        configured: true, authenticated: input.databaseOperational, authorized: input.databaseOperational,\n        operational: input.databaseOperational, account: null,\n        detail: \"Preflight determinístico por leituras autenticadas, sem geração e sem segredo de provedor.\", action: null,\n        observedSuccessAt: recentSuccess(node.id) }));\n    } else if (node.id === \"F6\") {\n      const evidence = input.canvaEvidence;\n      const configured = evidence?.configured ?? Boolean(portalOrigin(env));\n      const failed = !configured || evidence?.operational === false || evidence?.identityMatchesStored === false;\n      checks.push(check({ id: \"node:F6\", label: \"F6 — Canva via Portal\", category: \"tool\",\n        state: failed ? \"attention\" : evidence?.operational === true ? \"healthy\" : \"unknown\",\n        required, adapterConnected: true, configured, authenticated: evidence?.authenticated ?? null,\n        authorized: evidence?.authorized ?? null, operational: evidence?.operational ?? null,\n        account: evidence?.identity ? `${evidence.identity.userId} / equipe ${evidence.identity.teamId}` : null,\n        detail: evidence?.detail || \"Bridge conectado no código. OAuth, usuário, equipe e plano pertencem ao Portal; não são inferidos pela URL configurada.\",\n        action: evidence?.action || (!configured ? \"Corrigir REGENT_PORTAL_ORIGIN para a origem HTTPS do Portal.\" : null),\n        observedSuccessAt: recentSuccess(node.id) }));\n    } else if (node.id === \"A6\") {\n      checks.push(check({ id: \"node:A6\", label: \"A6 — parecer externo Claude importado\", category: \"provider\",\n        state: \"manual\", required, adapterConnected: true, configured: true,\n        authenticated: null, authorized: null, operational: null, account: null, requiresManualReview: true,\n        detail: \"Consome um parecer de origem humana declarada que corresponda à etapa e revisão atual. Não chama a API Claude e não comprova a identidade do provedor.\",\n        action: \"Baixar o pacote Claude desta missão/etapa, revisar na sua conta e importar o parecer com a revisão correta; depois autorizar a fase.\" }));\n    } else {\n      checks.push(check({ id: `node:${node.id}`, label: `${node.id} — ${node.technology}`,\n        category: node.type === \"agent\" ? \"provider\" : \"tool\", state: \"unavailable\",\n        required, adapterConnected: false, configured: null, authenticated: null, authorized: null,\n        operational: null, account: null,\n        detail: \"Ator do mapa arquitetural; não possui branch de execução automática no Regente. Configuração no Portal ou plugin deste chat não comprova adapter no runtime.\",\n        action: required ? \"Revisar a fase e substituir por um adapter disponível, implementar a integração ou adiar explicitamente se for opcional.\"\n            : \"Nenhuma ação obrigatória para esta missão; integração automática não implementada.\",\n        observedSuccessAt: recentSuccess(node.id) }));\n    }\n  }\n\n  for (const node of requiredNodes) {\n    if (NETWORK_NODES.some((item) => item.id === node)) continue;\n    checks.push(check({ id: `node:${node}`, label: `${node} — nó não registrado`, category: \"tool\",\n      state: \"unavailable\", required: true, adapterConnected: false, configured: null,\n      authenticated: null, authorized: null, operational: null, account: null,\n      detail: \"A missão referencia um nó que não existe no registro desta versão.\",\n      action: \"Revisar a fase e indicar um nó registrado com adapter implementado.\" }));\n  }\n\n  const nodes = NETWORK_NODES.map((node) => {\n    const evidence = checks.find((item) => item.id === `node:${node.id}`)!;\n    const adapter = OPENAI_NODES.has(node.id) ? node.id === \"A4\" ? \"openai_agents_independent_review\" : \"openai_agents\"\n      : node.id === \"A5\" ? \"local_recovery_preflight\" : node.id === \"A6\" ? \"human_import\"\n        : node.id === \"F6\" ? \"canva_portal_bridge\" : \"not_implemented\";\n    return { ...node, label: node.technology, adapter, architecturalStatus: node.status, status: evidence.state,\n      adapterConnected: evidence.adapterConnected, configured: evidence.configured,\n      operational: evidence.operational, required: evidence.required, blocking: evidence.blocking,\n      requiresManualReview: evidence.requiresManualReview || false,\n      observedSuccessAt: evidence.observedSuccessAt,\n      executionScope: node.id === \"A6\" ? \"external_guardian\" : AUTOMATIC_NODES.has(node.id) ? \"runtime\" : \"architectural_only\" };\n  });\n  const links = [\n    ...[\"A1\", \"A2\", \"A3\", \"A4\"].map((id) => ({ id: `regente-${id}`, from: \"Regente\", to: id,\n      transport: \"openai_agents_sdk\", adapterConnected: true, accountSource: \"OPENAI_API_KEY@Regente\",\n      state: checks.find((item) => item.id === `node:${id}`)!.state })),\n    { id: \"regente-preflight\", from: \"Regente\", to: \"A5\", transport: \"local_authenticated_reads\", adapterConnected: true, accountSource: \"sessão Supabase do Master\", state: checks[0].state },\n    { id: \"preflight-database\", from: \"A5\", to: \"F3\", transport: \"supabase_rls\", adapterConnected: true, accountSource: \"sessão Supabase do Master\", state: checks[0].state },\n    { id: \"canva-bridge\", from: \"Regente\", to: \"F6\", transport: \"single_use_tool_run\", adapterConnected: true, accountSource: \"Canva OAuth@Portal\", state: checks.find((item) => item.id === \"node:F6\")!.state },\n    { id: \"canva-shared-account\", from: \"F6\", to: \"F5\", transport: \"shared_portal_connection\", adapterConnected: true, accountSource: \"canva_connections.user_id\", state: checks.find((item) => item.id === \"node:F6\")!.state },\n    { id: \"durable-workflow\", from: \"Regente\", to: \"Vercel Workflow\", transport: \"sealed_session_and_execution_lease\", adapterConnected: true, accountSource: \"sessão Master + segredo do workflow\", state: workflowConfigured ? \"unknown\" : \"attention\" },\n    { id: \"github-deployment\", from: \"F1\", to: \"F2\", transport: \"git_push_deployment\", adapterConnected: true, accountSource: \"configuração Git/Vercel não consultada\", state: \"unknown\" },\n    { id: \"claude-external-review\", from: \"Guardião Claude\", to: \"Regente\", transport: \"manual_packet_and_human_import\", adapterConnected: true, accountSource: \"origem declarada pelo operador; não verificada\", state: \"manual\" },\n    ...NETWORK_NODES.filter((node) => !AUTOMATIC_NODES.has(node.id) && node.id !== \"A6\").map((node) => ({\n      id: `unavailable-${node.id}`, from: \"Regente\", to: node.id, transport: \"not_implemented\",\n      adapterConnected: false, accountSource: \"não verificável pelo runtime\", state: \"unavailable\" })),\n  ];\n  const tasks = (input.tasks || []).map((task) => ({ id: task.id, status: task.status, updatedAt: task.updated_at,\n    leaseExpired: task.status === \"executing\" && Boolean(task.execution_lease_until) &&\n      new Date(task.execution_lease_until!).getTime() < new Date(generatedAt).getTime() }));\n  return {\n    version: \"0.7.0\", sourceCommit: currentCommit(env), depth: input.depth, generatedAt,\n    taskId: input.taskId || null, requiredNodes: [...requiredNodes],\n    summary: { nodes: nodes.length, links: links.length, checks: checks.length,\n      attention: checks.filter((item) => item.state === \"attention\" || (item.required && item.state === \"unavailable\")).length,\n      unknown: checks.filter((item) => item.state === \"unknown\").length,\n      healthy: checks.filter((item) => item.state === \"healthy\").length,\n      unavailable: checks.filter((item) => item.state === \"unavailable\").length,\n      blockingCount: checks.filter((item) => item.blocking).length,\n      expiredExecutions: tasks.filter((task) => task.leaseExpired).length },\n    checks, nodes, links, providers, tasks, canva: input.canvaEvidence || null,\n    safety: { secretValuesIncluded: false, generativeCallsPerformed: false, paidProbesPerformed: false, automaticCredentialChanges: false },\n    limitations: [\n      \"Créditos, faturamento, plano Pro e bloqueios financeiros são não verificáveis sem fonte própria; chave presente não significa saldo ou modelo autorizado.\",\n      \"Sucessos anteriores são evidência histórica com horário, não garantia de que a conexão atual continua operacional.\",\n      \"Uma consulta autenticada usa RLS, mas não comprova isoladamente a correção de todas as políticas de segurança.\",\n      \"O afinamento profundo só consulta banco, lista de modelos e identidade Canva; não cria designs, não publica anúncios, não renova OAuth nem realiza geração paga.\",\n      \"Claude interativo é uma revisão humana importada, não uma chamada automática à Anthropic. DeepSeek fica reservado para 0.8, fora da rede ativa.\",\n    ],\n  };\n}\n\nexport type OrchestraHealthReport = ReturnType<typeof buildOrchestraHealth>;\n\nexport class OrchestraReadError extends Error {\n  readonly code: string;\n  constructor(code: string, message: string) { super(message); this.code = code; }\n}\n\nasync function probeOpenAI(fetchImpl: typeof fetch, env: ProviderEnvironment): Promise<ProviderEvidence | null> {\n  if (!credentialPresent(\"OPENAI_API_KEY\", env)) return null;\n  try {\n    const response = await fetchImpl(\"https://api.openai.com/v1/models\", {\n      method: \"GET\", cache: \"no-store\", redirect: \"error\", signal: AbortSignal.timeout(7000),\n      headers: { Authorization: `Bearer ${env.OPENAI_API_KEY!.trim()}` },\n    });\n    if (response.ok) {\n      const body = await response.json().catch(() => null);\n      if (!Array.isArray(body?.data)) throw new Error(\"invalid_model_list\");\n      return { authenticated: true, authorized: true,\n        detail: \"Lista de modelos lida com autenticação no runtime atual. Isso não valida uma geração, o acesso ao modelo selecionado nem o saldo.\", action: null };\n    }\n    return { authenticated: response.status === 401 ? false : null, authorized: response.status === 403 ? false : null,\n      detail: `Leitura OpenAI não concluída (HTTP ${response.status}); resposta do provedor não reproduzida para proteger credenciais.`,\n      action: response.status === 401 || response.status === 403 ? \"Revalidar chave/projeto OpenAI do runtime Regente.\" : \"Repetir o afinamento posteriormente; não repetir geração às cegas.\" };\n  } catch {\n    return { authenticated: null, authorized: null, detail: \"Endpoint de modelos OpenAI não pôde ser verificado (rede, timeout ou resposta inválida).\",\n      action: \"Conferir disponibilidade da API e repetir o afinamento; não presumir falha de billing.\" };\n  }\n}\n\nasync function probeCanva(fetchImpl: typeof fetch, env: ProviderEnvironment, accessToken?: string): Promise<CanvaHealthEvidence | null> {\n  const origin = portalOrigin(env);\n  if (!origin || !accessToken) return null;\n  try {\n    const response = await fetchImpl(`${origin}/api/internal/regente/canva/health`, {\n      method: \"GET\", cache: \"no-store\", redirect: \"error\", signal: AbortSignal.timeout(15000),\n      headers: { Authorization: `Bearer ${accessToken}`, Accept: \"application/json\" },\n    });\n    if (!response.ok) return { configured: true, authenticated: null, authorized: null, operational: null,\n      identity: null, identityMatchesStored: null, tokenState: \"not_checked\",\n      detail: `Bridge de diagnóstico Canva não pôde ser consultado (HTTP ${response.status}). Isso não é prova de OAuth Canva inválido.`,\n      action: \"Verificar deployment do Portal, sessão Master e acesso à rota de diagnóstico; depois conferir a conexão Canva.\" };\n    const body = await response.json().catch(() => null);\n    const evidence = body?.canva;\n    if (!evidence || typeof evidence.configured !== \"boolean\") throw new Error(\"invalid_canva_report\");\n    // Return only the fixed non-secret contract, never arbitrary bridge output.\n    const booleanOrNull = (value: unknown) => typeof value === \"boolean\" ? value : null;\n    const identity = typeof evidence.identity?.userId === \"string\" && typeof evidence.identity?.teamId === \"string\"\n      ? { userId: evidence.identity.userId.slice(0, 128), teamId: evidence.identity.teamId.slice(0, 128) } : null;\n    const tokenState = [\"absent\", \"expired\", \"current\", \"invalid\", \"not_checked\"].includes(evidence.tokenState)\n      ? evidence.tokenState as CanvaHealthEvidence[\"tokenState\"] : \"not_checked\";\n    return { configured: evidence.configured,\n      clientId: typeof evidence.clientId === \"string\" && /^OC[A-Za-z0-9_-]{4,125}$/.test(evidence.clientId) ? evidence.clientId : null,\n      authenticated: booleanOrNull(evidence.authenticated),\n      authorized: booleanOrNull(evidence.authorized), operational: booleanOrNull(evidence.operational), identity,\n      identityMatchesStored: booleanOrNull(evidence.identityMatchesStored), tokenState,\n      detail: typeof evidence.detail === \"string\" ? evidence.detail.slice(0, 1200) : \"Verificação de identidade do Portal recebida.\",\n      action: typeof evidence.action === \"string\" ? evidence.action.slice(0, 800) : null };\n  } catch {\n    return { configured: true, authenticated: null, authorized: null, operational: null, identity: null,\n      identityMatchesStored: null, tokenState: \"not_checked\", detail: \"Bridge Canva sem resposta de diagnóstico válida; OAuth não foi comprovado.\",\n      action: \"Conferir acesso e deployment do Portal, sem alterar tokens ou executar designs para testar.\" };\n  }\n}\n\nexport async function collectOrchestraHealth(input: {\n  supabase: SupabaseClient;\n  userId: string;\n  depth: \"basic\" | \"deep\";\n  requiredNodes?: string[];\n  taskId?: string;\n  accessToken?: string;\n  env?: ProviderEnvironment;\n  fetchImpl?: typeof fetch;\n}): Promise<OrchestraHealthReport> {\n  const env = input.env || process.env;\n  const countResult = await input.supabase.from(\"regent_tasks\")\n    .select(\"id\", { count: \"exact\", head: true }).eq(\"user_id\", input.userId);\n  if (countResult.error) throw new OrchestraReadError(\"orchestra_tasks_read_failed\", \"A leitura autenticada do banco falhou; diagnóstico não aprovado.\");\n\n  let requiredNodes = input.requiredNodes || [];\n  if (input.taskId) {\n    const taskResult = await input.supabase.from(\"regent_tasks\").select(\"id,pipeline\")\n      .eq(\"id\", input.taskId).eq(\"user_id\", input.userId).maybeSingle();\n    if (taskResult.error) throw new OrchestraReadError(\"orchestra_task_read_failed\", \"Não foi possível ler a missão autorizada.\");\n    if (!taskResult.data) throw new OrchestraReadError(\"task_not_found\", \"Missão não encontrada para este operador.\");\n    if (!input.requiredNodes && Array.isArray(taskResult.data.pipeline)) {\n      requiredNodes = [...new Set(taskResult.data.pipeline.flatMap((step: { nodes?: unknown }) =>\n        Array.isArray(step?.nodes) ? step.nodes.filter((node): node is string => typeof node === \"string\") : []))] as string[];\n    }\n  }\n\n  let tasks: TaskEvidence[] = [];\n  let recentRuns: RunEvidence[] = [];\n  let canvaEvidence: CanvaHealthEvidence | null = null;\n  let openAIEvidence: ProviderEvidence | null = null;\n  if (input.depth === \"deep\") {\n    let tasksQuery = input.supabase.from(\"regent_tasks\")\n      .select(\"id,status,updated_at,execution_lease_until\").eq(\"user_id\", input.userId)\n      .order(\"updated_at\", { ascending: false }).limit(100);\n    let runsQuery = input.supabase.from(\"regent_tool_runs\")\n      .select(\"node_id,adapter,status,updated_at\").eq(\"user_id\", input.userId)\n      .order(\"updated_at\", { ascending: false }).limit(250);\n    if (input.taskId) { tasksQuery = tasksQuery.eq(\"id\", input.taskId); runsQuery = runsQuery.eq(\"task_id\", input.taskId); }\n    const [taskResult, runResult] = await Promise.all([tasksQuery, runsQuery]);\n    if (taskResult.error || runResult.error) throw new OrchestraReadError(\"orchestra_evidence_read_failed\", \"Falha nas consultas de runtime; não é seguro aprovar o diagnóstico.\");\n    tasks = taskResult.data || [];\n    recentRuns = runResult.data || [];\n    [canvaEvidence, openAIEvidence] = await Promise.all([\n      probeCanva(input.fetchImpl || fetch, env, input.accessToken),\n      probeOpenAI(input.fetchImpl || fetch, env),\n    ]);\n  }\n  return buildOrchestraHealth({ depth: input.depth, databaseOperational: true,\n    databaseDetail: `Leitura com sessão autenticada e filtro user_id: ${countResult.count || 0} missões visíveis. Não substitui auditoria completa das políticas RLS.`,\n    requiredNodes, env, taskId: input.taskId, tasks, recentRuns, canvaEvidence, openAIEvidence });\n}\n","sha256":"ec5f33b70169cfd2c172fa2f0c2e6f221629a56b97d93d0b3026b36f96fae401"},{"path":"regente/app/api/tasks/[taskId]/decision/route.ts","content":"import { NextResponse } from \"next/server\";\nimport { requireMaster } from \"../../../../../lib/require-master\";\nimport { createServerSupabaseClient } from \"../../../../../lib/supabase\";\nimport { validatePhasePatch } from \"../../../../../lib/phase-patch\";\n\nconst decisions = new Set([\"execute\", \"partial\", \"continue\", \"redo\", \"skip\", \"reject\", \"revise\", \"recover\"]);\nconst explanations: Record<string, string> = {\n  forbidden: \"Somente o operador Master ativo pode autorizar a execução.\",\n  task_not_ready: \"A pipeline ainda precisa ser preparada antes de executar.\",\n  task_closed: \"A missão está encerrada. Use Refazer com nova orientação para criar uma nova versão.\",\n  recovery_not_required: \"Não existe execução expirada a recuperar. Atualize e use a ação da fase atual.\",\n  phase_not_found: \"A fase escolhida não existe nesta missão.\",\n  note_too_long: \"A orientação deve ter no máximo 8.000 caracteres.\",\n  invalid_phase_patch: \"A configuração solicitada não é válida. Escolha um executor e referências canônicas para inspecionar Canva.\",\n  revision_conflict: \"O estado mudou desde a última leitura. Atualize o monitor antes de decidir.\",\n  execution_active: \"Há uma invocação ativa. Aguarde o término ou a expiração do lock; não iniciar outra cópia.\",\n  phase_validation_required: \"Revise os outputs e use Continuar para validar a fase antes de avançar.\",\n  phase_report_stale: \"O relatório pertence a outra versão. Atualize o estado.\",\n  guidance_required: \"Informe a orientação para refazer somente esta fase.\",\n  next_phase_only: \"A 0.7 libera somente a próxima fase; as demais continuam pendentes.\",\n  dependencies_pending: \"Há dependências pendentes. Revise a pipeline, sem simular resultados.\",\n  phase_not_optional: \"Esta fase não pode ser pulada. Configure o adapter ou revise o plano.\",\n  skip_requires_pending_phase_and_reason: \"Escolha uma fase opcional pendente e informe a razão para adiar.\",\n  task_not_found: \"Tarefa não encontrada.\",\n  final_validation_required: \"A última fase precisa ser validada antes de finalizar a missão.\",\n};\n\nexport async function POST(request: Request, { params }: { params: Promise<{ taskId: string }> }) {\n  const auth = await requireMaster();\n  if (!auth.ok) return NextResponse.json({ error: \"unauthorized\", message: auth.message }, { status: auth.status });\n  const origin = request.headers.get(\"origin\");\n  if (origin && origin !== new URL(request.url).origin) return NextResponse.json({ error: \"origin_mismatch\" }, { status: 403 });\n  const { taskId } = await params;\n  const body = await request.json().catch(() => ({}));\n  if (!decisions.has(body.decision)) return NextResponse.json({ error: \"invalid_decision\", message: \"Decisão inválida.\" }, { status: 400 });\n  if (!Number.isInteger(body.expectedRevision) || body.expectedRevision < 0) {\n    return NextResponse.json({ error: \"revision_required\", message: \"Atualize a página para carregar a revisão atual antes de decidir.\" }, { status: 409 });\n  }\n  const note = typeof body.note === \"string\" ? body.note.trim() : \"\";\n  const target = body.targetStep ?? body.step ?? (Array.isArray(body.approvedSteps) ? body.approvedSteps[0] : null);\n  if (target != null && (!Number.isInteger(target) || target < 1)) return NextResponse.json({ error: \"invalid_step\" }, { status: 400 });\n  let patch = null;\n  if (body.phasePatch != null) {\n    if (body.decision !== \"redo\" || !note || target == null) return NextResponse.json({ error: \"invalid_phase_patch\", message: \"Alterar a configuração exige Refazer, a fase e uma orientação explícita.\" }, { status: 400 });\n    try { patch = validatePhasePatch(body.phasePatch); } catch (error) {\n      return NextResponse.json({ error: \"invalid_phase_patch\", message: (error as Error).message }, { status: 400 });\n    }\n  }\n  const supabase = await createServerSupabaseClient();\n  const result = await supabase.rpc(\"regent_decide_phase\", {\n    p_task_id: taskId, p_expected_revision: body.expectedRevision, p_decision: body.decision, p_note: note, p_step: target, p_phase_patch: patch,\n  });\n  if (result.error) {\n    const key = Object.keys(explanations).find((key) => result.error.message.startsWith(key));\n    const status = key === \"task_not_found\" ? 404 : key ? 409 : 500;\n    if (!key) console.error(\"regente_phase_decision_failed\", { code: result.error.code });\n    return NextResponse.json({ error: key || \"decision_failed\", message: key ? explanations[key] : \"Não foi possível registrar a decisão com segurança.\" }, { status, headers: { \"Cache-Control\": \"no-store\" } });\n  }\n  return NextResponse.json(result.data, { headers: { \"Cache-Control\": \"no-store\" } });\n}\n","sha256":"46add1e90238ba969ddad47610559a7da0f3764cc2833bcf78adb2ef6b919285"},{"path":"regente/app/api/tasks/[taskId]/execute/route.ts","content":"import { randomUUID } from \"node:crypto\";\nimport { NextResponse } from \"next/server\";\nimport { start } from \"workflow/api\";\nimport { requireMaster, requireMasterBearer } from \"../../../../../lib/require-master\";\nimport { createBearerSupabaseClient, createServerSupabaseClient } from \"../../../../../lib/supabase\";\nimport { isValidWorkflowSecret, sealWorkflowSession } from \"../../../../../lib/workflow-auth\";\nimport { taskExecutionWorkflow } from \"../../../../../workflows/task-execution\";\nimport { executePhase, type PhaseTask } from \"../../../../../lib/phase-executor\";\nimport { redactSecrets } from \"../../../../../lib/phase-control\";\nimport { safeWorkflowOrigin } from \"../../../../../lib/workflow-state\";\n\nexport const runtime = \"nodejs\";\nexport const maxDuration = 800;\nconst NO_STORE = { \"Cache-Control\": \"no-store\" };\n\nexport async function POST(request: Request, { params }: { params: Promise<{ taskId: string }> }) {\n  const { taskId } = await params;\n  const workflowHeader = request.headers.get(\"x-regent-workflow\");\n  const internal = Boolean(workflowHeader);\n  if (internal && !isValidWorkflowSecret(workflowHeader)) {\n    return NextResponse.json({ error: \"workflow_unauthorized\", message: \"Execução durável não autorizada.\" }, { status: 401, headers: NO_STORE });\n  }\n  const bearer = request.headers.get(\"authorization\")?.replace(/^Bearer\\s+/i, \"\") || \"\";\n  const auth = internal ? await requireMasterBearer(bearer) : await requireMaster();\n  if (!auth.ok) return NextResponse.json({ error: \"unauthorized\", message: auth.message }, { status: auth.status, headers: NO_STORE });\n  const userId = auth.userId;\n  const supabase = internal ? createBearerSupabaseClient(bearer) : await createServerSupabaseClient();\n  const read = await supabase.from(\"regent_tasks\")\n    .select(\"id,session_id,title,objective,status,pipeline,picker,human_decision,control_revision,execution_id,execution_invocation_id,execution_lease_until,engine_version\")\n    .eq(\"id\", taskId).eq(\"user_id\", userId).maybeSingle();\n  if (read.error || !read.data) return NextResponse.json({ error: \"task_not_found\", message: \"Tarefa não encontrada.\" }, { status: read.error ? 500 : 404, headers: NO_STORE });\n  const task = read.data;\n\n  if (!internal) {\n    if (task.status === \"executing\") return NextResponse.json({\n      taskId, status: \"executing\", alreadyRunning: true,\n      message: \"A tarefa já está reservada. Se o monitor indicar expiração, use Recuperar execução, sem abrir outra cópia.\",\n    }, { status: 202, headers: NO_STORE });\n    if (task.status === \"succeeded\") return NextResponse.json({ taskId, status: \"succeeded\", alreadyCompleted: true }, { headers: NO_STORE });\n    const decision = task.human_decision as { approval_scope?: string; approved_steps?: number[] } | null;\n    if (task.status !== \"approved\" || decision?.approval_scope !== \"single_phase\" || decision.approved_steps?.length !== 1) {\n      return NextResponse.json({ error: \"reapproval_required\", message: \"Autorize somente a próxima fase no monitor. Checkpoints e outputs serão preservados.\" }, { status: 409, headers: NO_STORE });\n    }\n    const { data: { session }, error: sessionError } = await supabase.auth.getSession();\n    if (sessionError || !session?.access_token || !session.refresh_token) return NextResponse.json({ error: \"session_required\", message: \"Reentre no portal para renovar a sessão Master.\" }, { status: 401, headers: NO_STORE });\n    const origin = safeWorkflowOrigin(new URL(request.url).origin, process.env.NODE_ENV === \"production\");\n    if (!origin) return NextResponse.json({ error: \"workflow_origin_invalid\", message: \"Origem do Regente não configurada para execução durável. Nenhuma sessão será enviada a outro endereço.\" }, { status: 409, headers: NO_STORE });\n    let sealedSession: string;\n    try { sealedSession = sealWorkflowSession({ accessToken: session.access_token, refreshToken: session.refresh_token }); }\n    catch { return NextResponse.json({ error: \"workflow_configuration_required\", message: \"Configure REGENT_WORKFLOW_SECRET no projeto Regente, mantendo o segredo existente quando válido. Nenhuma execução foi iniciada.\" }, { status: 503, headers: NO_STORE }); }\n    const executionId = randomUUID();\n    const locked = await supabase.from(\"regent_tasks\").update({\n      status: \"executing\", execution_id: executionId, execution_invocation_id: null, execution_lease_until: null,\n      next_action: \"Enfileirando somente a fase autorizada.\", updated_at: new Date().toISOString(),\n    }).eq(\"id\", taskId).eq(\"user_id\", userId).eq(\"status\", \"approved\").eq(\"control_revision\", task.control_revision).select(\"id\").maybeSingle();\n    if (locked.error || !locked.data) return NextResponse.json({ error: \"execution_lock_conflict\", message: \"O estado mudou. Atualize o monitor; nenhuma nova cópia foi criada.\" }, { status: 409, headers: NO_STORE });\n    try {\n      const workflow = await start(taskExecutionWorkflow, [{\n        taskId, userId, executionId,\n        sealedSession, origin,\n      }]);\n      const queued = await supabase.from(\"regent_tasks\").update({\n        workflow_run_id: workflow.runId,\n        next_action: \"Fase em execução durável. Ao concluir, aguardará sua validação.\",\n        updated_at: new Date().toISOString(),\n      }).eq(\"id\", taskId).eq(\"user_id\", userId).eq(\"execution_id\", executionId).eq(\"status\", \"executing\");\n      if (queued.error) console.error(\"regente_workflow_metadata_failed\", { taskId, code: queued.error.code });\n      await supabase.from(\"regent_task_events\").insert({\n        task_id: taskId, user_id: userId, event_type: \"workflow_enqueued\",\n        payload: { run_id: workflow.runId, execution_id: executionId, version: \"0.7.0\", steps: decision.approved_steps },\n      });\n      return NextResponse.json({ taskId, status: \"executing\", runId: workflow.runId, message: \"Fase enfileirada. Fechar ou minimizar o painel não interrompe a execução.\" }, { status: 202, headers: NO_STORE });\n    } catch (error) {\n      const failure = redactSecrets(error instanceof Error ? error.message : String(error));\n      await supabase.from(\"regent_tasks\").update({\n        status: \"blocked\", execution_id: null, execution_invocation_id: null, execution_lease_until: null,\n        control_revision: task.control_revision + 1, workflow_run_id: null,\n        next_action: \"O envio à fila não foi confirmado. Confira os runs preservados antes de autorizar outra execução.\",\n        blocked_reason: \"Falha ao confirmar o envio à fila; não repetir automaticamente.\", last_error: { message: failure, kind: \"queue_dispatch_unknown\" },\n        updated_at: new Date().toISOString(),\n      }).eq(\"id\", taskId).eq(\"user_id\", userId).eq(\"execution_id\", executionId).eq(\"status\", \"executing\");\n      await supabase.from(\"regent_task_events\").insert({ task_id: taskId, user_id: userId, event_type: \"workflow_enqueue_failed\", payload: { message: failure } });\n      return NextResponse.json({ error: \"enqueue_failed\", message: \"Envio à fila não confirmado. A fase foi pausada; confira o diagnóstico antes de autorizar nova execução. Outputs preservados.\" }, { status: 503, headers: NO_STORE });\n    }\n  }\n\n  const body = await request.json().catch(() => ({})) as { executionId?: string; invocationId?: string };\n  if (!body.executionId || body.executionId !== task.execution_id) return NextResponse.json({ error: \"stale_workflow\", message: \"A execução foi substituída; a invocação antiga não pode alterar checkpoints.\" }, { status: 409, headers: NO_STORE });\n  if ([\"awaiting_validation\", \"succeeded\", \"blocked\", \"failed\", \"rejected\", \"needs_revision\"].includes(task.status)) {\n    return NextResponse.json({ taskId, status: task.status, checkpointPreserved: true, message: \"Invocação já encerrada; nenhuma fase foi repetida.\" }, { headers: NO_STORE });\n  }\n  if (task.status !== \"executing\") return NextResponse.json({ error: \"invalid_execution_state\", message: \"Fase não enfileirada.\" }, { status: 409, headers: NO_STORE });\n  const invocationId = body.invocationId || randomUUID();\n  if (task.execution_invocation_id || task.execution_lease_until) {\n    return NextResponse.json({ error: \"human_recovery_required\", message: \"Esta execução já recebeu uma invocação. Aguarde a reserva ou recupere pelo gate humano após expirar; nenhuma cópia será iniciada.\" }, { status: 409, headers: NO_STORE });\n  }\n  const claim = await supabase.from(\"regent_tasks\").update({\n    execution_invocation_id: invocationId, execution_lease_until: new Date(Date.now() + 810_000).toISOString(), updated_at: new Date().toISOString(),\n  }).eq(\"id\", taskId).eq(\"user_id\", userId).eq(\"execution_id\", body.executionId).eq(\"status\", \"executing\")\n    .is(\"execution_invocation_id\", null).is(\"execution_lease_until\", null).select(\"id\").maybeSingle();\n  if (claim.error) return NextResponse.json({ error: \"claim_failed\", message: \"Falha ao reservar a invocação; não foram executadas APIs externas.\" }, { status: 503, headers: NO_STORE });\n  if (!claim.data) return NextResponse.json({ error: \"workflow_lease_active\", message: \"Outra invocação ainda possui a fase.\" }, { status: 409, headers: NO_STORE });\n  try {\n    const result = await executePhase({ supabase, userId, task: { ...task, execution_invocation_id: invocationId } as PhaseTask });\n    return NextResponse.json(result, { headers: NO_STORE });\n  } catch (error) {\n    const failure = redactSecrets(error instanceof Error ? error.message : String(error));\n    // Fence the crash against a later human decision / workflow. Never erase the checkpoint.\n    const saved = await supabase.from(\"regent_tasks\").update({\n      status: \"blocked\", execution_invocation_id: null, execution_lease_until: null,\n      control_revision: task.control_revision + 1,\n      next_action: \"Confira o diagnóstico e autorize a retomada de somente esta fase.\",\n      blocked_reason: failure, last_error: { message: failure, at: new Date().toISOString() }, updated_at: new Date().toISOString(),\n    }).eq(\"id\", taskId).eq(\"user_id\", userId).eq(\"execution_id\", body.executionId).eq(\"execution_invocation_id\", invocationId).eq(\"status\", \"executing\").select(\"id\");\n    if (saved.data?.length) await supabase.from(\"regent_task_events\").insert({\n      task_id: taskId, user_id: userId, event_type: \"phase_runtime_failed\", payload: { message: failure },\n    });\n    return NextResponse.json({ taskId, status: \"blocked\", error: \"phase_runtime_failed\", message: failure }, { headers: NO_STORE });\n  }\n}\n","sha256":"03d44316f08cda442b7ad33269990cce4be2acdf33808439dfae1b42189fb109"},{"path":"regente/app/api/tasks/[taskId]/outputs/route.ts","content":"import { NextResponse } from \"next/server\";\nimport { requireMaster } from \"../../../../../lib/require-master\";\nimport { createServerSupabaseClient } from \"../../../../../lib/supabase\";\nimport { buildArtifactOutputs } from \"../../../../../lib/artifact-outputs\";\n\nexport const runtime = \"nodejs\";\nconst HEADERS = { \"Cache-Control\": \"no-store\" };\nconst MAX_ROWS = 1000;\n\nexport async function GET(request: Request, { params }: { params: Promise<{ taskId: string }> }) {\n  const auth = await requireMaster();\n  if (!auth.ok) return NextResponse.json({ error: \"unauthorized\", message: auth.message }, { status: auth.status, headers: HEADERS });\n  const { taskId } = await params;\n  const supabase = await createServerSupabaseClient();\n  const task = await supabase.from(\"regent_tasks\").select(\"id,title,status,engine_version\")\n    .eq(\"id\", taskId).eq(\"user_id\", auth.userId).maybeSingle();\n  if (task.error || !task.data) return NextResponse.json({ error: \"task_not_found\", message: \"Tarefa não encontrada.\" }, { status: task.error ? 500 : 404, headers: HEADERS });\n  const [steps, runs, reviews] = await Promise.all([\n    supabase.from(\"regent_task_steps\").select(\"step_number,role,node_ids,status,artifact,revision,validated_at,completed_at,updated_at\")\n      .eq(\"task_id\", taskId).eq(\"user_id\", auth.userId).order(\"step_number\").limit(MAX_ROWS),\n    // Failed/running runs can contain confirmed partial external effects; never conceal them.\n    supabase.from(\"regent_tool_runs\").select(\"id,step_number,node_id,adapter,status,input,output,created_at,updated_at\")\n      .eq(\"task_id\", taskId).eq(\"user_id\", auth.userId).not(\"output\", \"is\", null)\n      .order(\"created_at\", { ascending: false }).limit(MAX_ROWS),\n    supabase.from(\"regent_phase_reviews\").select(\"id,step_number,revision,decision,output,created_at\")\n      .eq(\"task_id\", taskId).eq(\"user_id\", auth.userId).eq(\"decision\", \"superseded\")\n      .order(\"created_at\", { ascending: false }).limit(MAX_ROWS),\n  ]);\n  if (steps.error || runs.error || reviews.error) return NextResponse.json({ error: \"outputs_failed\", message: \"Não foi possível ler os outputs preservados. Nenhum arquivo foi alterado.\" }, { status: 500, headers: HEADERS });\n  const outputs = buildArtifactOutputs({ taskId, steps: steps.data || [], runs: runs.data || [], reviews: reviews.data || [] });\n  const download = new URL(request.url).searchParams.get(\"download\");\n  if (download) {\n    const item = outputs.find((output) => output.id === download);\n    if (!item) return NextResponse.json({ error: \"output_not_found\" }, { status: 404, headers: HEADERS });\n    return new Response(\"# \" + task.data.title + \"\\n\\nEtapa \" + item.step + \" · revisão \" + item.revision + \" · \" + item.source + \" · estado \" + item.status + \"\\n\\n\" + item.fullContent, {\n      headers: { ...HEADERS, \"Content-Type\": \"text/markdown; charset=utf-8\", \"X-Content-Type-Options\": \"nosniff\",\n        \"Content-Disposition\": 'attachment; filename=\"' + item.filename + '\"' },\n    });\n  }\n  return NextResponse.json({ task: { ...task.data,\n    completedSteps: (steps.data || []).filter((step) => step.status === \"succeeded\").length,\n    skippedSteps: (steps.data || []).filter((step) => step.status === \"skipped\").length,\n    validatedSteps: (steps.data || []).filter((step) => step.validated_at != null).length,\n    failedSteps: (steps.data || []).filter((step) => [\"failed\", \"blocked\"].includes(step.status)).length,\n    totalSteps: steps.data?.length || 0, outputCount: outputs.length },\n    items: outputs.map(({ fullContent: _full, ...item }) => item),\n    historyLimitReached: [runs.data?.length, reviews.data?.length].some((count) => count === MAX_ROWS),\n    limitations: [\"Links de edição Canva não são arquivos exportados; acesso depende da conta e da permissão do design.\",\n      \"Links em textos generativos não foram verificados como fontes.\"] }, { headers: HEADERS });\n}\n","sha256":"eb5f3987b20c9431efb2c378e2d61c3a96d003082aca9cdc29d0628308abb94e"},{"path":"regente/app/api/tasks/[taskId]/status/route.ts","content":"import { NextResponse } from \"next/server\";\nimport { getWorld } from \"workflow/runtime\";\nimport { requireMaster } from \"../../../../../lib/require-master\";\nimport { createServerSupabaseClient } from \"../../../../../lib/supabase\";\nimport { taskRuntime } from \"../../../../../lib/task-runtime\";\nimport { safeWorkflowRunId, workflowObservation, withWorkflowObservation, type WorkflowObservation } from \"../../../../../lib/workflow-state\";\n\nexport const runtime = \"nodejs\";\nconst NO_STORE = { \"Cache-Control\": \"no-store\" };\n\nasync function readWorkflowObservation(runId: string | null): Promise<WorkflowObservation> {\n  if (!runId) return workflowObservation({ reason: \"not_linked\" });\n  if (!safeWorkflowRunId(runId)) return workflowObservation({ runId, reason: \"invalid_run\" });\n  // Never initialize a Local World on a production Vercel filesystem because\n  // system environment variables were omitted. No auth/config fallback here.\n  if (process.env.NODE_ENV === \"production\" && !process.env.VERCEL_DEPLOYMENT_ID && !process.env.WORKFLOW_TARGET_WORLD) {\n    return workflowObservation({ runId, reason: \"unavailable\" });\n  }\n  let timer: ReturnType<typeof setTimeout> | undefined;\n  const read = (async () => {\n    try {\n      const world = await getWorld();\n      const run = await world.runs.get(runId, { resolveData: \"none\" });\n      return workflowObservation({ runId, run: run as unknown as Record<string, unknown>, currentDeploymentId: process.env.VERCEL_DEPLOYMENT_ID });\n    } catch {\n      // Do not expose raw backend errors or inspect protected serialized IO.\n      return workflowObservation({ runId, reason: \"unavailable\" });\n    }\n  })();\n  try {\n    return await Promise.race([\n      read,\n      new Promise<WorkflowObservation>((resolve) => {\n        timer = setTimeout(() => resolve(workflowObservation({ runId, reason: \"timeout\" })), 2_000);\n      }),\n    ]);\n  } finally {\n    if (timer) clearTimeout(timer);\n  }\n}\n\nexport async function GET(request: Request, { params }: { params: Promise<{ taskId: string }> }) {\n  const auth = await requireMaster();\n  if (!auth.ok) return NextResponse.json({ error: \"unauthorized\", message: auth.message }, { status: auth.status, headers: NO_STORE });\n  const { taskId } = await params;\n  const supabase = await createServerSupabaseClient();\n  const compact = new URL(request.url).searchParams.get(\"compact\") === \"1\";\n  const [task, steps, events] = await Promise.all([\n    supabase.from(\"regent_tasks\").select(\"id,title,objective,status,current_step,progress_percent,next_action,autonomy_level,blocked_reason,last_error,updated_at,phase_report,validated_steps,control_revision,engine_version,workflow_run_id,execution_lease_until\").eq(\"id\", taskId).eq(\"user_id\", auth.userId).maybeSingle(),\n    supabase.from(\"regent_task_steps\").select(\"step_number,role,node_ids,action,expected_output,status,depends_on,checkpoint,attempt_count,last_error,next_action,started_at,completed_at,updated_at,revision,validated_at,recovered_at\").eq(\"task_id\", taskId).eq(\"user_id\", auth.userId).order(\"step_number\"),\n    compact ? Promise.resolve({ data: [], error: null }) : supabase.from(\"regent_task_events\").select(\"id,event_type,payload,created_at\").eq(\"task_id\", taskId).eq(\"user_id\", auth.userId).order(\"created_at\", { ascending: false }).limit(40),\n  ]);\n  if (task.error || !task.data) return NextResponse.json({ error: \"task_not_found\", message: \"Tarefa não encontrada.\" }, { status: task.error ? 500 : 404, headers: NO_STORE });\n  if (steps.error || events.error) return NextResponse.json({ error: \"task_state_failed\", message: \"Não foi possível ler o estado persistente. Nenhum checkpoint foi alterado.\" }, { status: 500, headers: NO_STORE });\n  // Only the run linked to this authenticated user's persisted task is queried.\n  // This GET does not enqueue, recover, cancel, write events or alter checkpoints.\n  const workflow = await readWorkflowObservation(task.data.workflow_run_id);\n  const observed = withWorkflowObservation(taskRuntime(task.data, steps.data || []), workflow);\n  return NextResponse.json({ task: observed, steps: steps.data || [], events: events.data || [] }, { headers: NO_STORE });\n}\n","sha256":"d5fd8fb35bf1def636520dad0adc0a291176a6ac03c3071245e327509215fcf8"},{"path":"regente/app/api/orchestra/guardians/route.ts","content":"import { NextResponse } from \"next/server\";\nimport { requireMaster } from \"../../../../lib/require-master\";\nimport { createServerSupabaseClient } from \"../../../../lib/supabase\";\nimport { buildGuardianPacket, guardianSourceCommit, loadGuardianSourceSnapshot, sanitizeGuardianEvidence } from \"../../../../lib/guardian-context\";\n\nexport const runtime = \"nodejs\";\nexport const dynamic = \"force-dynamic\";\nexport const maxDuration = 45;\nconst NO_STORE = { \"Cache-Control\": \"no-store\" };\nconst UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;\nconst validProvider = (provider: unknown): provider is \"openai\" | \"claude\" => provider === \"openai\" || provider === \"claude\";\n\n// Export a versioned evidence packet, with no automatic provider call, approval\n// or DB mutation. Source retrieval is pinned to the deployed commit or omitted.\nexport async function GET(request: Request) {\n  const auth = await requireMaster();\n  if (!auth.ok) return NextResponse.json({ error: \"access_denied\", message: auth.message }, { status: auth.status, headers: NO_STORE });\n  const url = new URL(request.url);\n  const provider = url.searchParams.get(\"provider\") || \"claude\";\n  const taskId = url.searchParams.get(\"taskId\");\n  const download = url.searchParams.get(\"download\") === \"1\";\n  if (!validProvider(provider) || (taskId && !UUID.test(taskId))) return NextResponse.json({ error: \"invalid_guardian_request\" }, { status: 400, headers: NO_STORE });\n  const supabase = await createServerSupabaseClient();\n  let task = null;\n  let steps: unknown[] = [];\n  let runs: unknown[] = [];\n  let events: unknown[] = [];\n  if (taskId) {\n    const taskResult = await supabase.from(\"regent_tasks\")\n      .select(\"id,title,objective,status,depth,risk,budget_tier,pipeline,human_decision,current_step,progress_percent,next_action,blocked_reason,engine_version,control_revision,phase_report,validated_steps,created_at,updated_at\")\n      .eq(\"id\", taskId).eq(\"user_id\", auth.userId).maybeSingle();\n    if (taskResult.error) return NextResponse.json({ error: \"guardian_task_read_failed\", message: \"Não foi possível ler a missão autorizada; nenhum pacote foi emitido.\" }, { status: 503, headers: NO_STORE });\n    if (!taskResult.data) return NextResponse.json({ error: \"task_not_found\" }, { status: 404, headers: NO_STORE });\n    task = taskResult.data;\n    const [stepResult, runResult, eventResult] = await Promise.all([\n      supabase.from(\"regent_task_steps\")\n        .select(\"step_number,role,node_ids,action,expected_output,status,depends_on,revision,validated_at,recovered_at,artifact,attempt_count,last_error,next_action,started_at,completed_at,updated_at\")\n        .eq(\"task_id\", taskId).eq(\"user_id\", auth.userId).order(\"step_number\", { ascending: true }).limit(50),\n      supabase.from(\"regent_tool_runs\").select(\"id,step_number,node_id,adapter,status,output,created_at,updated_at\")\n        .eq(\"task_id\", taskId).eq(\"user_id\", auth.userId).order(\"created_at\", { ascending: false }).limit(80),\n      supabase.from(\"regent_task_events\").select(\"id,event_type,payload,created_at\")\n        .eq(\"task_id\", taskId).eq(\"user_id\", auth.userId).order(\"created_at\", { ascending: false }).limit(80),\n    ]);\n    if (stepResult.error || runResult.error || eventResult.error) return NextResponse.json({ error: \"guardian_evidence_read_failed\",\n      message: \"A leitura de checkpoints/outputs/histórico falhou. O pacote não foi emitido como se estivesse completo.\" }, { status: 503, headers: NO_STORE });\n    steps = stepResult.data || []; runs = runResult.data || []; events = eventResult.data || [];\n  }\n  const reportResult = await supabase.from(\"regent_orchestra_checks\").select(\"report,created_at\")\n    .eq(\"user_id\", auth.userId).order(\"created_at\", { ascending: false }).limit(1).maybeSingle();\n  if (reportResult.error) return NextResponse.json({ error: \"guardian_orchestra_read_failed\", message: \"O histórico de afinamento está indisponível; confira a migração 0.7.\" }, { status: 503, headers: NO_STORE });\n  const sources = url.searchParams.get(\"source\") === \"0\" ? undefined : await loadGuardianSourceSnapshot();\n  const packet = buildGuardianPacket({ provider, task, steps, runs, events, sources,\n    orchestraReport: reportResult.data ? { ...reportResult.data.report, persistedAt: reportResult.data.created_at } : null });\n  if (download) return new Response(JSON.stringify(packet, null, 2), { headers: { ...NO_STORE,\n    \"Content-Type\": \"application/json; charset=utf-8\",\n    \"Content-Disposition\": `attachment; filename=\"regente-0.7-${provider}-${taskId || \"architecture\"}.json\"` } });\n  return NextResponse.json({ packet }, { headers: NO_STORE });\n}\n\n// A manual review is provenance-labelled evidence, not a task authorization or\n// proof that an API/model/account executed. Only the decision endpoint advances.\nexport async function POST(request: Request) {\n  const auth = await requireMaster();\n  if (!auth.ok) return NextResponse.json({ error: \"access_denied\", message: auth.message }, { status: auth.status, headers: NO_STORE });\n  const origin = request.headers.get(\"origin\");\n  if (origin && origin !== new URL(request.url).origin) return NextResponse.json({ error: \"invalid_origin\" }, { status: 403, headers: NO_STORE });\n  if (!request.headers.get(\"content-type\")?.includes(\"application/json\")) return NextResponse.json({ error: \"json_required\" }, { status: 415, headers: NO_STORE });\n  if (Number(request.headers.get(\"content-length\") || 0) > 120_000) return NextResponse.json({ error: \"review_too_large\" }, { status: 413, headers: NO_STORE });\n  const text = await request.text();\n  if (text.length > 100_000) return NextResponse.json({ error: \"review_too_large\" }, { status: 413, headers: NO_STORE });\n  let body: Record<string, unknown> | null = null;\n  try { body = JSON.parse(text); } catch { /* Invalid JSON is rejected below. */ }\n  if (!body || !validProvider(body.provider) || typeof body.taskId !== \"string\" || !UUID.test(body.taskId) ||\n    typeof body.review !== \"string\" || body.review.trim().length < 20 || body.review.length > 48_000 ||\n    body.acknowledgeManualSource !== true ||\n    (body.packetId !== undefined && (typeof body.packetId !== \"string\" || !/^gp7-[a-f0-9]{24}$/.test(body.packetId))) ||\n    (body.sourceCommit !== undefined && (typeof body.sourceCommit !== \"string\" || !/^[a-f0-9]{40}$/i.test(body.sourceCommit))) ||\n    (body.step !== undefined && (!Number.isInteger(body.step) || Number(body.step) < 1 || Number(body.step) > 50)) ||\n    (body.revision !== undefined && (!Number.isInteger(body.revision) || Number(body.revision) < 1))) {\n    return NextResponse.json({ error: \"invalid_guardian_review\", message: \"Informe missão, provedor declarado e parecer. Confirme que é uma importação humana, não uma execução automática verificada.\" }, { status: 400, headers: NO_STORE });\n  }\n  const supabase = await createServerSupabaseClient();\n  const taskResult = await supabase.from(\"regent_tasks\").select(\"id,engine_version,control_revision\")\n    .eq(\"id\", body.taskId).eq(\"user_id\", auth.userId).maybeSingle();\n  if (taskResult.error) return NextResponse.json({ error: \"guardian_task_read_failed\" }, { status: 503, headers: NO_STORE });\n  if (!taskResult.data) return NextResponse.json({ error: \"task_not_found\" }, { status: 404, headers: NO_STORE });\n  let revisionMatches: boolean | null = null;\n  if (body.step !== undefined) {\n    const stepResult = await supabase.from(\"regent_task_steps\").select(\"step_number,revision\")\n      .eq(\"task_id\", body.taskId).eq(\"user_id\", auth.userId).eq(\"step_number\", body.step).maybeSingle();\n    if (stepResult.error) return NextResponse.json({ error: \"guardian_step_read_failed\" }, { status: 503, headers: NO_STORE });\n    if (!stepResult.data) return NextResponse.json({ error: \"step_not_found\" }, { status: 404, headers: NO_STORE });\n    revisionMatches = body.revision === undefined ? null : stepResult.data.revision === body.revision;\n  }\n  const sourceCommit = guardianSourceCommit();\n  const payload = {\n    kind: \"external_guardian_review\", version: \"0.7.0\", providerDeclared: body.provider,\n    source: \"human_supplied\", transport: \"human_import\", providerIdentityVerified: false,\n    automaticProviderExecutionVerified: false, grantsApproval: false,\n    packetIdDeclared: body.packetId || null, sourceCommitDeclared: body.sourceCommit || null,\n    deployedSourceCommit: sourceCommit,\n    sourceCommitMatches: body.sourceCommit && sourceCommit ? body.sourceCommit === sourceCommit : null,\n    step: body.step || null, revisionDeclared: body.revision || null, revisionMatches,\n    taskControlRevision: taskResult.data.control_revision,\n    review: sanitizeGuardianEvidence(body.review.trim()), recordedAt: new Date().toISOString(),\n  };\n  const saved = await supabase.from(\"regent_task_events\").insert({ task_id: body.taskId,\n    user_id: auth.userId, event_type: \"guardian_review_imported\", payload }).select(\"id,created_at\").single();\n  if (saved.error || !saved.data) return NextResponse.json({ error: \"guardian_review_persist_failed\", message: \"O parecer não foi salvo; nenhuma fase foi aprovada.\" }, { status: 503, headers: NO_STORE });\n  return NextResponse.json({ review: { ...payload, id: saved.data.id, persistedAt: saved.data.created_at },\n    message: \"Parecer importado com origem humana declarada. Revise-o e use os controles de validação da fase; a importação não avançou a pipeline.\" }, { headers: NO_STORE });\n}\n","sha256":"c40036b06b1adcbaa45edff32e47aa31fce4f7091627e5b03803094d0b4a3054"},{"path":"supabase/migrations/20261009170000_regente_v07_orchestra_checks.sql","content":"begin;\n\nalter table public.regent_tasks add column if not exists engine_version text not null default '0.6.3';\nalter table public.regent_tasks alter column engine_version set default '0.7.0';\nalter table public.regent_tasks add column if not exists control_revision integer not null default 0;\nalter table public.regent_tasks add column if not exists phase_report jsonb;\nalter table public.regent_tasks add column if not exists validated_steps integer[] not null default '{}';\nalter table public.regent_tasks add column if not exists workflow_run_id text;\nalter table public.regent_tasks drop constraint regent_tasks_status_check;\nalter table public.regent_tasks add constraint regent_tasks_status_check check\n  (status in ('draft','planning','awaiting_approval','approved','executing','awaiting_validation','succeeded','failed','rejected','needs_revision','blocked'));\nalter table public.regent_task_steps add column if not exists revision integer not null default 1;\nalter table public.regent_task_steps add column if not exists validated_at timestamptz;\nalter table public.regent_task_steps add column if not exists recovered_at timestamptz;\nalter table public.regent_task_steps add column if not exists revision_guidance text;\n\ncreate table if not exists public.regent_orchestra_checks (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references auth.users(id) on delete cascade,\n  depth text not null check (depth in ('basic','deep')),\n  status text not null check (status in ('healthy','attention')),\n  report jsonb not null default '{}',\n  created_at timestamptz not null default now()\n);\ncreate index if not exists regent_orchestra_checks_user_created_idx on public.regent_orchestra_checks(user_id,created_at desc);\nalter table public.regent_orchestra_checks enable row level security;\ngrant select,insert on public.regent_orchestra_checks to authenticated;\ncreate policy regent_orchestra_checks_select_own on public.regent_orchestra_checks for select to authenticated using ((select auth.uid())=user_id);\ncreate policy regent_orchestra_checks_insert_own on public.regent_orchestra_checks for insert to authenticated with check ((select auth.uid())=user_id);\n\ncreate table if not exists public.regent_phase_reviews (\n  id uuid primary key default gen_random_uuid(),\n  task_id uuid not null references public.regent_tasks(id) on delete cascade,\n  user_id uuid not null references auth.users(id) on delete cascade,\n  step_number integer not null check(step_number>0),\n  revision integer not null check(revision>0),\n  decision text not null,\n  note text,\n  output jsonb,\n  created_at timestamptz not null default now()\n);\ncreate index if not exists regent_phase_reviews_owner_task_idx on public.regent_phase_reviews(user_id,task_id,step_number,created_at desc);\ncreate index if not exists regent_phase_reviews_task_idx on public.regent_phase_reviews(task_id);\nalter table public.regent_phase_reviews enable row level security;\ngrant select,insert on public.regent_phase_reviews to authenticated;\ncreate policy regent_phase_reviews_select_own on public.regent_phase_reviews for select to authenticated using ((select auth.uid())=user_id);\ncreate policy regent_phase_reviews_insert_own on public.regent_phase_reviews for insert to authenticated with check\n  ((select auth.uid())=user_id and exists(select 1 from public.regent_tasks t where t.id=task_id and t.user_id=(select auth.uid())));\n\n-- Row-lock, RLS and revision checking make a double click or stale browser harmless.\n-- SECURITY INVOKER is deliberate: this function never elevates an operator's privileges.\ncreate or replace function public.regent_decide_phase(\n  p_task_id uuid,p_expected_revision integer,p_decision text,p_note text default '',p_step integer default null,p_phase_patch jsonb default null\n) returns jsonb language plpgsql security invoker set search_path='' as $$\ndeclare\n  t public.regent_tasks%rowtype;\n  s public.regent_task_steps%rowtype;\n  chosen integer; unresolved integer[]; affected integer[]; new_status text; decision_payload jsonb; old_phase jsonb;\nbegin\n  if auth.uid() is null then raise exception 'unauthorized'; end if;\n  if not exists(select 1 from public.system_admins where user_id=auth.uid() and active and role='master_admin') then raise exception 'forbidden'; end if;\n  if p_expected_revision is null or p_expected_revision<0 or p_decision is null then raise exception 'invalid_decision'; end if;\n  select * into t from public.regent_tasks where id=p_task_id and user_id=auth.uid() for update;\n  if not found then raise exception 'task_not_found'; end if;\n  if t.control_revision<>p_expected_revision then raise exception 'revision_conflict'; end if;\n  if p_decision not in ('execute','partial','continue','redo','skip','reject','revise','recover') then raise exception 'invalid_decision'; end if;\n  if length(coalesce(p_note,''))>8000 then raise exception 'note_too_long'; end if;\n  if p_phase_patch is not null and (p_decision<>'redo' or jsonb_typeof(p_phase_patch)<>'object' or\n    jsonb_typeof(p_phase_patch->'nodes') is distinct from 'array' or jsonb_array_length(p_phase_patch->'nodes')<>1 or\n    p_phase_patch->'nodes'->>0 is null or p_phase_patch->'nodes'->>0 not in ('A1','A2','A3','A4','A5','A6','F9','F6') or\n    exists(select 1 from jsonb_object_keys(p_phase_patch) k where k not in ('nodes','canvaMode','canvaSourceRunIds','canvaDesignIds')))\n    then raise exception 'invalid_phase_patch'; end if;\n  if p_phase_patch->'nodes'->>0='F6' and (p_phase_patch->>'canvaMode' is null or p_phase_patch->>'canvaMode' not in ('inspect','create')) then raise exception 'invalid_phase_patch'; end if;\n  if p_phase_patch->'nodes'->>0='F6' and p_phase_patch->>'canvaMode'='inspect' then\n    if jsonb_typeof(p_phase_patch->'canvaSourceRunIds') is distinct from 'array' or jsonb_typeof(p_phase_patch->'canvaDesignIds') is distinct from 'array' then raise exception 'invalid_phase_patch'; end if;\n    if jsonb_array_length(p_phase_patch->'canvaSourceRunIds') not between 1 and 20 or jsonb_array_length(p_phase_patch->'canvaDesignIds') not between 1 and 10 then raise exception 'invalid_phase_patch'; end if;\n  end if;\n  if t.status in ('draft','planning') then raise exception 'task_not_ready'; end if;\n  if t.status in ('rejected','succeeded') and p_decision not in ('redo','reject') then raise exception 'task_closed'; end if;\n\n  if t.status='executing' then\n    if p_decision<>'recover' or\n       (t.execution_lease_until is not null and t.execution_lease_until>now()) or\n       (t.execution_lease_until is null and t.updated_at>now()-interval '15 minutes')\n      then raise exception 'execution_active'; end if;\n    -- The old execution is fenced out, without claiming any external operation succeeded.\n    update public.regent_task_steps set status='prepared',next_action='Invocação expirada; conferir outputs antes de repetir.',updated_at=now()\n      where task_id=t.id and user_id=auth.uid() and status in ('running','review');\n  elsif p_decision='recover' then\n    raise exception 'recovery_not_required';\n  end if;\n\n  if p_decision in ('reject','revise') then\n    new_status:=case when p_decision='reject' then 'rejected' else 'needs_revision' end;\n    update public.regent_tasks set status=new_status,control_revision=control_revision+1,\n      execution_id=null,execution_invocation_id=null,execution_lease_until=null,\n      next_action=case when p_decision='reject' then 'Missão encerrada pelo operador; outputs preservados.' else 'Revisar a orientação, sem apagar outputs ou checkpoints.' end,\n      updated_at=now() where id=t.id and user_id=auth.uid();\n    insert into public.regent_task_events(task_id,user_id,event_type,payload) values\n      (t.id,auth.uid(),'human_'||p_decision,jsonb_build_object('note',p_note,'outputsPreserved',true));\n    return jsonb_build_object('taskId',t.id,'status',new_status,'controlRevision',t.control_revision+1,'message','Decisão registrada; outputs preservados.');\n  end if;\n\n  if p_decision='continue' then\n    if t.phase_report is null then raise exception 'phase_validation_required'; end if;\n    chosen:=(t.phase_report->>'step')::integer;\n    if chosen is null or chosen<1 or nullif(t.phase_report->>'revision','') is null then raise exception 'phase_report_stale'; end if;\n    if p_step is not null and p_step<>chosen then raise exception 'next_phase_only'; end if;\n    select * into s from public.regent_task_steps where task_id=t.id and user_id=auth.uid() and step_number=chosen;\n    if not found or s.status not in ('succeeded','skipped') or s.revision is distinct from (t.phase_report->>'revision')::integer then raise exception 'phase_report_stale'; end if;\n    update public.regent_task_steps set validated_at=now(),updated_at=now() where task_id=t.id and user_id=auth.uid() and step_number=chosen;\n    insert into public.regent_phase_reviews(task_id,user_id,step_number,revision,decision,note,output)\n      values(t.id,auth.uid(),chosen,s.revision,'accepted',p_note,s.artifact);\n    update public.regent_tasks set validated_steps=array(select distinct unnest(validated_steps||array[chosen]) order by 1)\n      where id=t.id and user_id=auth.uid();\n  elsif t.phase_report is not null and p_decision<>'redo' then\n    raise exception 'phase_validation_required';\n  end if;\n\n  if p_decision='redo' then\n    if nullif(trim(p_note),'') is null then raise exception 'guidance_required'; end if;\n    chosen:=coalesce(p_step,(t.phase_report->>'step')::integer,t.current_step);\n    if t.phase_report is not null and chosen is distinct from (t.phase_report->>'step')::integer then raise exception 'phase_validation_required'; end if;\n    if chosen is null or not exists(select 1 from public.regent_task_steps where task_id=t.id and user_id=auth.uid() and step_number=chosen) then raise exception 'phase_not_found'; end if;\n    with recursive descendants(step_number) as (\n      select chosen\n      union\n      select r.step_number from public.regent_task_steps r join descendants d on d.step_number=any(r.depends_on)\n        where r.task_id=t.id and r.user_id=auth.uid()\n    ) select array_agg(step_number order by step_number) into affected from descendants;\n    insert into public.regent_phase_reviews(task_id,user_id,step_number,revision,decision,note,output)\n      select task_id,user_id,step_number,revision,'superseded',p_note,artifact from public.regent_task_steps\n        where task_id=t.id and user_id=auth.uid() and step_number=any(affected) and artifact is not null;\n    update public.regent_task_steps set revision=revision+1,status=case when step_number=chosen then 'prepared' else 'planned' end,\n      validated_at=null,recovered_at=null,artifact=null,last_error=null,completed_at=null,\n      revision_guidance=case when step_number=chosen then p_note else revision_guidance end,\n      next_action=case when step_number=chosen then 'Refazer somente esta fase com a nova orientação.' else 'Dependência revisada; output anterior preservado no histórico.' end,\n      updated_at=now() where task_id=t.id and user_id=auth.uid() and step_number=any(affected);\n    update public.regent_tasks set validated_steps=array(select unnest(validated_steps) except select unnest(affected))\n      where id=t.id and user_id=auth.uid();\n    if p_phase_patch is not null then\n      select p into old_phase from jsonb_array_elements(t.pipeline) p where (p->>'step')::integer=chosen;\n      if old_phase is null then raise exception 'phase_not_found'; end if;\n      if p_phase_patch->'nodes'->>0<>'F6' then p_phase_patch:=jsonb_build_object('nodes',p_phase_patch->'nodes'); end if;\n      update public.regent_tasks set pipeline=(select jsonb_agg(case when (p->>'step')::integer=chosen then\n        (p-'canvaMode'-'canvaSourceRunIds'-'canvaDesignIds')||p_phase_patch||jsonb_build_object('checkpoint',true,'requiresApproval',true) else p end order by (p->>'step')::integer)\n        from jsonb_array_elements(pipeline) p) where id=t.id and user_id=auth.uid();\n      update public.regent_task_steps set node_ids=array(select jsonb_array_elements_text(p_phase_patch->'nodes'))\n        where task_id=t.id and user_id=auth.uid() and step_number=chosen;\n      insert into public.regent_task_events(task_id,user_id,event_type,payload) values(t.id,auth.uid(),'phase_plan_amended',\n        jsonb_build_object('step',chosen,'previousPhase',old_phase,'patch',p_phase_patch,'note',p_note,'humanExplicit',true));\n    end if;\n  else\n    select step_number into chosen from public.regent_task_steps\n      where task_id=t.id and user_id=auth.uid() and status not in ('succeeded','skipped') order by step_number limit 1;\n  end if;\n\n  if chosen is null then\n    if p_decision<>'continue' then raise exception 'final_validation_required'; end if;\n    update public.regent_tasks set status='succeeded',phase_report=null,control_revision=control_revision+1,\n      current_step=null,progress_percent=100,blocked_reason=null,last_error=null,\n      execution_id=null,execution_invocation_id=null,execution_lease_until=null,\n      next_action='Todas as fases do escopo foram concluídas e a última foi validada pelo operador.',updated_at=now()\n      where id=t.id and user_id=auth.uid();\n    insert into public.regent_task_events(task_id,user_id,event_type,payload) values\n      (t.id,auth.uid(),'mission_validated',jsonb_build_object('note',p_note,'finalHumanValidation',true));\n    return jsonb_build_object('taskId',t.id,'status','succeeded','controlRevision',t.control_revision+1,'message','Missão validada; outputs preservados.');\n  end if;\n\n  if p_step is not null and p_decision in ('execute','partial','recover','skip') and p_step<>chosen then raise exception 'next_phase_only'; end if;\n  select * into s from public.regent_task_steps where task_id=t.id and user_id=auth.uid() and step_number=chosen;\n  select array_agg(dep) into unresolved from unnest(coalesce(s.depends_on,'{}')) dep where not exists (\n    select 1 from public.regent_task_steps d where d.task_id=t.id and d.user_id=auth.uid() and d.step_number=dep and d.status in ('succeeded','skipped')\n  );\n  if cardinality(unresolved)>0 then raise exception 'dependencies_pending:%',unresolved; end if;\n\n  if p_decision='skip' then\n    if t.phase_report is not null or nullif(trim(p_note),'') is null then raise exception 'skip_requires_pending_phase_and_reason'; end if;\n    if not exists(select 1 from jsonb_array_elements(t.pipeline) p where (p->>'step')::integer=chosen and\n      (p->>'onUnavailable'='skip' or p->'nodes' ? 'F9')) then raise exception 'phase_not_optional'; end if;\n    update public.regent_task_steps set status='skipped',artifact=jsonb_build_object('deferred',true,'humanSkip',true,'reason',p_note),\n      completed_at=now(),next_action='Fase adiada pelo operador, sem execução externa.',updated_at=now()\n      where task_id=t.id and user_id=auth.uid() and step_number=chosen;\n    update public.regent_tasks set status='awaiting_validation',\n      phase_report=jsonb_build_object('kind','phase_checkpoint','step',chosen,'revision',s.revision,'title',s.action,\n        'summary','Fase adiada, sem execução externa.','output',jsonb_build_object('deferred',true,'humanSkip',true,'reason',p_note),\n        'completedAt',now(),'final',not exists(select 1 from public.regent_task_steps where task_id=t.id and user_id=auth.uid() and status not in ('succeeded','skipped'))),\n      control_revision=control_revision+1,current_step=chosen,blocked_reason=null,last_error=null,\n      execution_id=null,execution_invocation_id=null,execution_lease_until=null,\n      next_action='Validar o adiamento e seguir para a próxima fase.',updated_at=now() where id=t.id and user_id=auth.uid();\n    insert into public.regent_task_events(task_id,user_id,event_type,payload) values(t.id,auth.uid(),'human_phase_skipped',jsonb_build_object('step',chosen,'reason',p_note));\n    return jsonb_build_object('taskId',t.id,'status','awaiting_validation','controlRevision',t.control_revision+1,'message','Fase adiada; nenhuma ação externa foi executada.');\n  end if;\n\n  decision_payload:=jsonb_build_object('decision','partial','requested_decision',p_decision,'note',nullif(p_note,''),\n    'decided_at',now(),'approval_scope','single_phase','approved_steps',jsonb_build_array(chosen),\n    'approved_pipeline_steps',jsonb_build_array(chosen),'recovery_authorized',t.status in ('failed','blocked','executing'),\n    'recovery_steps',jsonb_build_array(chosen),'phase_revision',s.revision,'invalidated_steps',affected);\n  update public.regent_task_steps set status='prepared',next_action='Fase autorizada; aguardando execução durável.',last_error=null,updated_at=now()\n    where task_id=t.id and user_id=auth.uid() and step_number=chosen and status not in ('succeeded','skipped');\n  update public.regent_tasks set status='approved',human_decision=decision_payload,phase_report=null,\n    control_revision=control_revision+1,current_step=chosen,blocked_reason=null,last_error=null,\n    engine_version='0.7.0',execution_id=null,execution_invocation_id=null,execution_lease_until=null,\n    next_action='Executar somente a fase '||chosen||'; depois aguardar validação humana.',updated_at=now()\n    where id=t.id and user_id=auth.uid();\n  insert into public.regent_task_events(task_id,user_id,event_type,payload) values(t.id,auth.uid(),'human_phase_authorized',decision_payload);\n  return jsonb_build_object('taskId',t.id,'status','approved','controlRevision',t.control_revision+1,'step',chosen,\n    'invalidatedSteps',affected,'message','Somente a fase '||chosen||' foi autorizada. Outputs anteriores preservados.');\nend $$;\nrevoke all on function public.regent_decide_phase(uuid,integer,text,text,integer,jsonb) from public,anon;\ngrant execute on function public.regent_decide_phase(uuid,integer,text,text,integer,jsonb) to authenticated;\n\ncreate or replace function public.regent_begin_phase(\n  p_task_id uuid,p_execution_id uuid,p_invocation_id uuid,p_step integer\n) returns jsonb language plpgsql security invoker set search_path='' as $$\ndeclare t public.regent_tasks%rowtype; s public.regent_task_steps%rowtype;\nbegin\n  if auth.uid() is null or p_execution_id is null or p_invocation_id is null or p_step is null then raise exception 'invalid_execution_identity'; end if;\n  if not exists(select 1 from public.system_admins where user_id=auth.uid() and active and role='master_admin') then raise exception 'forbidden'; end if;\n  select * into t from public.regent_tasks where id=p_task_id and user_id=auth.uid() for update;\n  if not found or t.status<>'executing' or t.execution_id is distinct from p_execution_id or t.execution_invocation_id is distinct from p_invocation_id then raise exception 'stale_execution'; end if;\n  if t.human_decision->>'approval_scope' is distinct from 'single_phase' or\n    coalesce(t.human_decision->'approved_steps','[]'::jsonb) <> jsonb_build_array(p_step) then raise exception 'phase_not_authorized'; end if;\n  select * into s from public.regent_task_steps where task_id=t.id and user_id=auth.uid() and step_number=p_step;\n  if not found or s.status in ('succeeded','skipped') then raise exception 'phase_not_pending'; end if;\n  if (t.human_decision->>'phase_revision')::integer is distinct from s.revision then raise exception 'phase_revision_conflict'; end if;\n  if t.phase_report is not null then raise exception 'phase_validation_required'; end if;\n  if exists(select 1 from unnest(s.depends_on) dep where not exists(\n    select 1 from public.regent_task_steps d where d.task_id=t.id and d.user_id=auth.uid() and d.step_number=dep and d.status in ('succeeded','skipped')\n  )) then raise exception 'dependencies_pending'; end if;\n  update public.regent_task_steps set status='running',attempt_count=attempt_count+1,started_at=coalesce(started_at,now()),\n    completed_at=null,next_action='Executando fase '||p_step||'; resultados serão persistidos antes da validação.',updated_at=now()\n    where task_id=t.id and user_id=auth.uid() and step_number=p_step;\n  update public.regent_tasks set current_step=p_step,execution_lease_until=now()+interval '810 seconds',updated_at=now()\n    where id=t.id and user_id=auth.uid();\n  return jsonb_build_object('revision',s.revision,'attempt',s.attempt_count+1);\nend $$;\nrevoke all on function public.regent_begin_phase(uuid,uuid,uuid,integer) from public,anon;\ngrant execute on function public.regent_begin_phase(uuid,uuid,uuid,integer) to authenticated;\n\ncreate or replace function public.regent_finish_phase(\n  p_task_id uuid,p_execution_id uuid,p_invocation_id uuid,p_step integer,p_revision integer,\n  p_status text,p_artifact jsonb,p_report jsonb,p_error jsonb default null,p_recovered boolean default false\n) returns jsonb language plpgsql security invoker set search_path='' as $$\ndeclare t public.regent_tasks%rowtype; phase_status text; action text; done integer; total integer;\nbegin\n  if auth.uid() is null or p_execution_id is null or p_invocation_id is null or p_step is null or p_revision is null or p_status is null then raise exception 'invalid_execution_identity'; end if;\n  if not exists(select 1 from public.system_admins where user_id=auth.uid() and active and role='master_admin') then raise exception 'forbidden'; end if;\n  select * into t from public.regent_tasks where id=p_task_id and user_id=auth.uid() for update;\n  if not found or t.status<>'executing' or t.execution_id is distinct from p_execution_id or t.execution_invocation_id is distinct from p_invocation_id then raise exception 'stale_execution'; end if;\n  if p_status not in ('succeeded','skipped','failed','blocked') then raise exception 'invalid_phase_status'; end if;\n  if t.human_decision->>'approval_scope' is distinct from 'single_phase' or\n    coalesce(t.human_decision->'approved_steps','[]'::jsonb) <> jsonb_build_array(p_step) then raise exception 'phase_not_authorized'; end if;\n  if not exists(select 1 from public.regent_task_steps where task_id=t.id and user_id=auth.uid() and step_number=p_step and revision=p_revision and status='running') then raise exception 'phase_revision_conflict'; end if;\n  if p_status in ('succeeded','skipped') and (p_artifact is null or p_report is null or\n    (p_report->>'step')::integer is distinct from p_step or (p_report->>'revision')::integer is distinct from p_revision)\n    then raise exception 'phase_report_stale'; end if;\n  phase_status:=case when p_status in ('succeeded','skipped') then 'awaiting_validation' else p_status end;\n  action:=case when phase_status='awaiting_validation' then 'Revise os outputs da fase '||p_step||' e escolha continuar ou refazer.' else coalesce(p_error->>'action','Resolver o bloqueio indicado e retomar somente esta fase.') end;\n  update public.regent_task_steps set status=p_status,artifact=coalesce(p_artifact,artifact),\n    last_error=p_error,recovered_at=case when p_recovered then now() else recovered_at end,\n    next_action=action,completed_at=now(),updated_at=now() where task_id=t.id and user_id=auth.uid() and step_number=p_step;\n  select count(*) filter(where status in ('succeeded','skipped')),count(*) into done,total from public.regent_task_steps where task_id=t.id and user_id=auth.uid();\n  update public.regent_tasks set status=phase_status,phase_report=p_report,control_revision=control_revision+1,\n    current_step=p_step,progress_percent=case when total>0 then round(done*100.0/total)::integer else 0 end,\n    next_action=action,blocked_reason=case when phase_status in ('failed','blocked') then action else null end,last_error=p_error,\n    execution_invocation_id=null,execution_lease_until=null,updated_at=now() where id=t.id and user_id=auth.uid();\n  insert into public.regent_task_events(task_id,user_id,event_type,payload) values(t.id,auth.uid(),\n    case when phase_status='awaiting_validation' then 'phase_awaiting_validation' else 'phase_blocked' end,\n    jsonb_build_object('step',p_step,'revision',p_revision,'status',phase_status,'report',p_report,'error',p_error));\n  return jsonb_build_object('taskId',t.id,'status',phase_status,'controlRevision',t.control_revision+1,'message',action);\nend $$;\nrevoke all on function public.regent_finish_phase(uuid,uuid,uuid,integer,integer,text,jsonb,jsonb,jsonb,boolean) from public,anon;\ngrant execute on function public.regent_finish_phase(uuid,uuid,uuid,integer,integer,text,jsonb,jsonb,jsonb,boolean) to authenticated;\n\ncommit;\n\n","sha256":"03af4b2f13c566f94aaf50d4c8b8811a6283ca3f9c5b742eaa214e0c71e60088"},{"path":"regente/workflows/task-execution.ts","content":"import { randomUUID } from \"node:crypto\";\nimport { FatalError } from \"workflow\";\nimport { createAuthSupabaseClient, createBearerSupabaseClient } from \"../lib/supabase\";\nimport {\n  safeWorkflowOrigin,\n  workflowFailureKind,\n  workflowFailureMessage,\n  workflowHttpFailure,\n  type WorkflowFailureKind,\n} from \"../lib/workflow-state\";\nimport {\n  getWorkflowSecretForInternalRequest,\n  sealWorkflowSession,\n  unsealWorkflowSession,\n} from \"../lib/workflow-auth\";\n\nexport type TaskExecutionWorkflowInput = {\n  taskId: string;\n  userId: string;\n  sealedSession: string;\n  origin: string;\n  executionId: string;\n};\n\nasync function prepareWorkflowSession(input: TaskExecutionWorkflowInput) {\n  \"use step\";\n\n  console.log(\"regente_workflow_session_started\", { taskId: input.taskId });\n  const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;\n  if (![input.taskId, input.userId, input.executionId].every((value) => typeof value === \"string\" && uuid.test(value)) ||\n      !safeWorkflowOrigin(input.origin, process.env.NODE_ENV === \"production\")) {\n    throw new FatalError(workflowFailureMessage(\"configuration\"));\n  }\n  try { getWorkflowSecretForInternalRequest(); } catch {\n    throw new FatalError(workflowFailureMessage(\"configuration\"));\n  }\n  try {\n    const storedSession = unsealWorkflowSession(input.sealedSession);\n    const authClient = createAuthSupabaseClient();\n    const { data, error } = await authClient.auth.setSession({\n      access_token: storedSession.accessToken,\n      refresh_token: storedSession.refreshToken,\n    });\n    if (error || !data.session?.access_token || !data.session.refresh_token || data.user?.id !== input.userId) {\n      throw new FatalError(workflowFailureMessage(\"session\"));\n    }\n    console.log(\"regente_workflow_session_prepared\", { taskId: input.taskId });\n    return sealWorkflowSession({\n      accessToken: data.session.access_token,\n      refreshToken: data.session.refresh_token,\n    });\n  } catch {\n    // No raw auth/provider exception is persisted: it may contain credentials.\n    throw new FatalError(workflowFailureMessage(\"session\"));\n  }\n}\nprepareWorkflowSession.maxRetries = 0;\n\nasync function executeTaskRequest(\n  input: TaskExecutionWorkflowInput,\n  preparedSession: string,\n) {\n  \"use step\";\n\n  console.log(\"regente_workflow_step_started\", {\n    taskId: input.taskId,\n    userId: input.userId,\n  });\n\n  let session;\n  let workflowSecret: string;\n  try {\n    session = unsealWorkflowSession(preparedSession);\n    workflowSecret = getWorkflowSecretForInternalRequest();\n  } catch {\n    throw new FatalError(workflowFailureMessage(\"configuration\"));\n  }\n  const origin = safeWorkflowOrigin(input.origin, process.env.NODE_ENV === \"production\");\n  if (!origin) throw new FatalError(workflowFailureMessage(\"configuration\"));\n  const invocationId = randomUUID();\n  // Below the 800s Function limit; the worker's 810s lease still fences recovery.\n  // Aborting this HTTP request does not prove that the server stopped its phase.\n  const signal = AbortSignal.timeout(770_000);\n  try {\n    const response = await fetch(\n      `${origin}/api/tasks/${encodeURIComponent(input.taskId)}/execute`,\n      {\n        method: \"POST\", cache: \"no-store\", redirect: \"error\", signal,\n        headers: {\n          Authorization: `Bearer ${session.accessToken}`,\n          \"X-Regent-Workflow\": workflowSecret,\n          \"Content-Type\": \"application/json\",\n        },\n        body: JSON.stringify({\n          source: \"vercel_workflow\",\n          executionId: input.executionId,\n          invocationId,\n        }),\n      },\n    );\n    if (!response.ok) throw new FatalError(workflowFailureMessage(workflowHttpFailure(response.status)));\n    let payload: Record<string, unknown>;\n    try { payload = await response.json() as Record<string, unknown>; } catch {\n      throw new FatalError(workflowFailureMessage(\"response_invalid\"));\n    }\n    const statuses = [\"awaiting_validation\", \"succeeded\", \"blocked\", \"failed\", \"rejected\", \"needs_revision\"];\n    if (!payload || typeof payload !== \"object\" || !statuses.includes(String(payload.status))) {\n      throw new FatalError(workflowFailureMessage(\"response_invalid\"));\n    }\n    console.log(\"regente_workflow_step_finished\", {\n      taskId: input.taskId, httpStatus: response.status, taskStatus: payload.status,\n    });\n    // Outputs are in the authenticated task store, not duplicated into Workflow IO.\n    return {\n      httpStatus: response.status,\n      payload: { taskId: input.taskId, status: String(payload.status), checkpointPreserved: payload.checkpointPreserved === true },\n    };\n  } catch (error) {\n    if (FatalError.is(error)) throw error;\n    throw new FatalError(workflowFailureMessage(signal.aborted ? \"timeout\" : \"dispatch_unknown\"));\n  }\n}\n// HTTP can fail after an external effect. A retry must be a new human decision,\n// never the SDK's default blind redelivery of this POST.\nexecuteTaskRequest.maxRetries = 0;\n\nasync function recordWorkflowFailure(input: TaskExecutionWorkflowInput, preparedSession: string | null, kind: WorkflowFailureKind) {\n  \"use step\";\n  console.warn(\"regente_workflow_failed\", { taskId: input.taskId, kind });\n  try {\n    const session = unsealWorkflowSession(preparedSession || input.sealedSession);\n    const supabase = createBearerSupabaseClient(session.accessToken);\n    const { data: { user }, error: authError } = await supabase.auth.getUser(session.accessToken);\n    if (authError || !user || user.id !== input.userId) return { recorded: false };\n    const master = await supabase.from(\"system_admins\").select(\"user_id\")\n      .eq(\"user_id\", user.id).eq(\"active\", true).maybeSingle();\n    if (master.error || !master.data) return { recorded: false };\n    const task = await supabase.from(\"regent_tasks\").select(\"id\")\n      .eq(\"id\", input.taskId).eq(\"user_id\", user.id).eq(\"execution_id\", input.executionId).maybeSingle();\n    if (task.error || !task.data) return { recorded: false };\n    const saved = await supabase.from(\"regent_task_events\").insert({\n      task_id: input.taskId, user_id: user.id, event_type: \"workflow_execution_failed\",\n      payload: {\n        kind, message: workflowFailureMessage(kind), execution_id: input.executionId,\n        human_recovery_required: true, checkpoint_preserved: true, version: \"0.7.0\",\n      },\n    });\n    if (saved.error) console.warn(\"regente_workflow_failure_event_unconfirmed\", { taskId: input.taskId });\n    return { recorded: !saved.error };\n  } catch {\n    // Invalid/expired normal session is a stop condition, not permission to use a\n    // service key. The SDK failure remains visible through metadata-only status.\n    return { recorded: false };\n  }\n}\nrecordWorkflowFailure.maxRetries = 0;\n\nexport async function taskExecutionWorkflow(input: TaskExecutionWorkflowInput) {\n  \"use workflow\";\n\n  console.log(\"regente_workflow_started\", {\n    taskId: input.taskId,\n    userId: input.userId,\n  });\n\n  let preparedSession: string | null = null;\n  try {\n    preparedSession = await prepareWorkflowSession(input);\n    const result = await executeTaskRequest(input, preparedSession);\n    console.log(\"regente_workflow_finished\", { taskId: input.taskId, httpStatus: result.httpStatus });\n    return result;\n  } catch (error) {\n    const kind = workflowFailureKind(error);\n    await recordWorkflowFailure(input, preparedSession, kind);\n    throw error;\n  }\n}\n","sha256":"ffd5eae5354c51072e8bef85a4eec0310da6abd06173997a456a64ecbd5aab43"},{"path":"app/api/internal/regente/canva/route.ts","content":"import { createHash } from \"node:crypto\";\nimport { NextResponse } from \"next/server\";\nimport { createAdminSupabaseClient } from \"@/lib/supabase/server\";\nimport {\n  createRegentCanvaDesigns,\n  inspectRegentCanvaDesigns,\n  regentCanvaRunIsAuthorized,\n  regentCanvaSourceIsValidated,\n  type RegentCanvaProgress,\n  type RegentCanvaSpec,\n} from \"@/lib/canva/regent\";\nimport { designIdsFromRegentRuns } from \"@/lib/canva/regent-provenance\";\nimport { CanvaError } from \"@/lib/canva/security\";\n\nexport const runtime = \"nodejs\";\nexport const maxDuration = 120;\nexport const dynamic = \"force-dynamic\";\n\nfunction hash(value: string) {\n  return createHash(\"sha256\").update(value).digest(\"hex\");\n}\n\nfunction validSpec(value: unknown): value is RegentCanvaSpec {\n  if (!value || typeof value !== \"object\") return false;\n  const spec = value as RegentCanvaSpec;\n  return (\n    typeof spec.title === \"string\" &&\n    spec.title.length > 0 && spec.title.length <= 100 &&\n    Number.isInteger(spec.width) &&\n    spec.width >= 320 &&\n    spec.width <= 4000 &&\n    Number.isInteger(spec.height) &&\n    spec.height >= 320 &&\n    spec.height <= 4000 &&\n    Array.isArray(spec.pages) &&\n    spec.pages.length >= 1 &&\n    spec.pages.length <= 6 &&\n    spec.pages.every((page) => page && typeof page.headline === \"string\" && page.headline.length > 0 && page.headline.length <= 180 &&\n      [[page.eyebrow, 90], [page.body, 500], [page.cta, 80], [page.visualDirection, 260]].every(([text, maximum]) =>\n        text === undefined || typeof text === \"string\" && text.length <= Number(maximum)))\n  );\n}\n\nfunction failure(error: unknown, output?: unknown) {\n  const status = error instanceof CanvaError ? error.status : 500;\n  const message =\n    error instanceof CanvaError\n      ? error.message\n      : error instanceof Error\n        ? error.message\n        : \"Não foi possível concluir a execução do Canva.\";\n  return NextResponse.json({ ...(output && typeof output === \"object\" ? output : {}), message }, { status, headers: { \"Cache-Control\": \"no-store\" } });\n}\n\nexport async function POST(request: Request) {\n  const admin = createAdminSupabaseClient();\n\n  try {\n    const body = await request.json().catch(() => null);\n    const runId = typeof body?.runId === \"string\" ? body.runId.trim() : \"\";\n    const token = typeof body?.token === \"string\" ? body.token.trim() : \"\";\n\n    if (!runId || !token || token.length > 256) {\n      return NextResponse.json({ message: \"Credencial de execução inválida.\" }, { status: 400 });\n    }\n\n    const tokenDigest = hash(token);\n    const now = new Date().toISOString();\n    const { data: toolRun, error } = await admin\n      .from(\"regent_tool_runs\")\n      .select(\"id, task_id, user_id, node_id, step_number, adapter, status, input, token_hash, token_expires_at\")\n      .eq(\"id\", runId)\n      .eq(\"node_id\", \"F6\")\n      .eq(\"status\", \"pending\")\n      .eq(\"token_hash\", tokenDigest)\n      .gt(\"token_expires_at\", now)\n      .maybeSingle();\n\n    if (error || !toolRun) {\n      return NextResponse.json({ message: \"Execução expirada, já utilizada ou inválida.\" }, { status: 403 });\n    }\n\n    const [masterResult, taskResult, stepResult] = await Promise.all([\n      admin\n        .from(\"system_admins\")\n        .select(\"user_id, active\")\n        .eq(\"user_id\", toolRun.user_id)\n        .eq(\"active\", true)\n        .maybeSingle(),\n      admin\n        .from(\"regent_tasks\")\n        .select(\"id,status,pipeline,human_decision,current_step,execution_id,execution_invocation_id,execution_lease_until\")\n        .eq(\"id\", toolRun.task_id)\n        .eq(\"user_id\", toolRun.user_id)\n        .maybeSingle(),\n      admin.from(\"regent_task_steps\").select(\"step_number,status,revision\")\n        .eq(\"task_id\", toolRun.task_id).eq(\"user_id\", toolRun.user_id).eq(\"step_number\", toolRun.step_number).maybeSingle(),\n    ]);\n\n    if (masterResult.error || taskResult.error || stepResult.error) {\n      throw new CanvaError(\"Não foi possível verificar a autorização da fase Canva.\", 503);\n    }\n    const task = taskResult.data;\n    if (!masterResult.data || !regentCanvaRunIsAuthorized({ task, step: stepResult.data, run: toolRun })) {\n      return NextResponse.json({ message: \"Esta invocação ou revisão da fase Canva não está autorizada. Atualize o monitor, sem repetir a criação.\" }, { status: 403 });\n    }\n\n    const input = (toolRun.input || {}) as {\n      mode?: unknown;\n      spec?: unknown;\n      variants?: unknown;\n      sourceRunIds?: unknown;\n      designIds?: unknown;\n    };\n    const mode = input.mode === \"inspect\" ? \"inspect\" : \"create\";\n    const canonicalPhase = Array.isArray(task?.pipeline) ? task.pipeline.find((phase) => phase?.step === toolRun.step_number) : null;\n    if (!canonicalPhase || canonicalPhase.nodes?.[0] !== \"F6\" || canonicalPhase.canvaMode !== mode) {\n      return NextResponse.json({ message: \"A operação Canva não corresponde à fase autorizada na pipeline.\" }, { status: 403 });\n    }\n    if (mode === \"inspect\" && toolRun.adapter !== \"canva_portal_inspect\") {\n      return NextResponse.json({ message: \"Adapter de inspeção Canva inválido.\" }, { status: 403 });\n    }\n    if (mode === \"create\" && toolRun.adapter !== \"canva_portal_bridge\") {\n      return NextResponse.json({ message: \"Adapter de criação Canva inválido.\" }, { status: 403 });\n    }\n    if (mode === \"create\" && !validSpec(input.spec)) {\n      return NextResponse.json({ message: \"A especificação do design é inválida.\" }, { status: 422 });\n    }\n\n    const variants = Number(input.variants ?? 1);\n    if (mode === \"create\" && (!Number.isInteger(variants) || variants < 1 || variants > 3)) {\n      return NextResponse.json({ message: \"Quantidade de variantes Canva inválida.\" }, { status: 422 });\n    }\n    let inspectedDesignIds: string[] = [];\n    let expectedAccount: { userId: string; teamId: string } | undefined;\n    if (mode === \"inspect\") {\n      const sourceRunIds = Array.isArray(input.sourceRunIds)\n        ? [...new Set(input.sourceRunIds.filter((value): value is string => typeof value === \"string\"))]\n        : [];\n      const requestedDesignIds = Array.isArray(input.designIds)\n        ? [...new Set(input.designIds.filter((value): value is string => typeof value === \"string\"))]\n        : [];\n      if (!sourceRunIds.length || !requestedDesignIds.length || sourceRunIds.length > 20 || requestedDesignIds.length > 10) {\n        return NextResponse.json({ message: \"Referências canônicas do Canva ausentes ou inválidas.\" }, { status: 422 });\n      }\n      if (sourceRunIds.some((id) => !canonicalPhase.canvaSourceRunIds?.includes(id)) ||\n        requestedDesignIds.some((id) => !canonicalPhase.canvaDesignIds?.includes(id))) {\n        return NextResponse.json({ message: \"As referências Canva diferem da fase autorizada.\" }, { status: 403 });\n      }\n\n      const { data: sourceRuns, error: sourceRunsError } = await admin\n        .from(\"regent_tool_runs\")\n        .select(\"id,task_id,user_id,node_id,step_number,status,input,output\")\n        .eq(\"user_id\", toolRun.user_id)\n        .eq(\"node_id\", \"F6\")\n        .eq(\"status\", \"succeeded\")\n        .in(\"id\", sourceRunIds);\n      if (sourceRunsError || !sourceRuns || sourceRuns.length !== sourceRunIds.length) {\n        return NextResponse.json({ message: \"Não foi possível comprovar a origem dos designs Canva.\" }, { status: 403 });\n      }\n\n      const sourceTaskIds = [...new Set(sourceRuns.map((run) => run.task_id))];\n      const [tasksResult, phasesResult, reviewsResult] = await Promise.all([\n        admin.from(\"regent_tasks\").select(\"id,status,engine_version,validated_steps\").eq(\"user_id\", toolRun.user_id).in(\"id\", sourceTaskIds),\n        admin.from(\"regent_task_steps\").select(\"task_id,step_number,status,revision,validated_at\").eq(\"user_id\", toolRun.user_id).in(\"task_id\", sourceTaskIds),\n        admin.from(\"regent_phase_reviews\").select(\"task_id,step_number,revision,decision\").eq(\"user_id\", toolRun.user_id).in(\"task_id\", sourceTaskIds),\n      ]);\n      if (tasksResult.error || phasesResult.error || reviewsResult.error || !tasksResult.data ||\n        tasksResult.data.length !== sourceTaskIds.length || sourceRuns.some((run) => !regentCanvaSourceIsValidated({\n          run, task: tasksResult.data.find((source) => source.id === run.task_id) || null,\n          step: phasesResult.data?.find((phase) => phase.task_id === run.task_id && phase.step_number === run.step_number) || null,\n          reviews: (reviewsResult.data || []).filter((review) => review.task_id === run.task_id),\n        }))) {\n        return NextResponse.json({ message: \"Uma fase de origem Canva não foi validada, foi substituída ou pertence a outra revisão. Confira o output canônico.\" }, { status: 403 });\n      }\n\n      const allowedDesignIds = new Set(designIdsFromRegentRuns(sourceRuns));\n      if (requestedDesignIds.some((designId) => !allowedDesignIds.has(designId))) {\n        return NextResponse.json({ message: \"Um design Canva solicitado não pertence aos resultados aprovados.\" }, { status: 403 });\n      }\n      inspectedDesignIds = requestedDesignIds;\n      const accounts = sourceRuns.map((run) => (run.output as { account?: { userId?: unknown; teamId?: unknown } } | null)?.account)\n        .filter((account): account is { userId: string; teamId: string } => typeof account?.userId === \"string\" && typeof account.teamId === \"string\");\n      if (new Set(accounts.map((account) => account.userId + \":\" + account.teamId)).size > 1) {\n        return NextResponse.json({ message: \"As referências Canva pertencem a contas ou equipes diferentes. Confira a conexão antes de inspecionar.\" }, { status: 403 });\n      }\n      expectedAccount = accounts[0];\n    }\n\n    const { data: claimed, error: claimError } = await admin\n      .from(\"regent_tool_runs\")\n      .update({\n        status: \"running\",\n        token_hash: null,\n        token_expires_at: null,\n        updated_at: new Date().toISOString(),\n      })\n      .eq(\"id\", toolRun.id)\n      .eq(\"task_id\", toolRun.task_id)\n      .eq(\"user_id\", toolRun.user_id)\n      .eq(\"status\", \"pending\")\n      .eq(\"token_hash\", tokenDigest)\n      .gt(\"token_expires_at\", new Date().toISOString())\n      .select(\"id\")\n      .maybeSingle();\n\n    if (claimError || !claimed) {\n      return NextResponse.json({ message: \"Esta execução já foi consumida.\" }, { status: 409 });\n    }\n\n    const runInput = toolRun.input as { stepRevision: number; executionId: string };\n    const identity = { runId: toolRun.id, step: toolRun.step_number, revision: runInput.stepRevision, executionId: runInput.executionId };\n    let progress: RegentCanvaProgress = { mode, designs: [], jobs: [], complete: false, externalEffect: \"none\" };\n    async function assertAuthorized() {\n      const [currentTask, currentPhase] = await Promise.all([\n        admin.from(\"regent_tasks\").select(\"status,human_decision,current_step,execution_id,execution_invocation_id,execution_lease_until\")\n          .eq(\"id\", toolRun!.task_id).eq(\"user_id\", toolRun!.user_id).maybeSingle(),\n        admin.from(\"regent_task_steps\").select(\"step_number,status,revision\")\n          .eq(\"task_id\", toolRun!.task_id).eq(\"user_id\", toolRun!.user_id).eq(\"step_number\", toolRun!.step_number).maybeSingle(),\n      ]);\n      if (currentTask.error || currentPhase.error) throw new CanvaError(\"Não foi possível reconfirmar a autorização da fase. Nenhuma nova importação será iniciada.\", 503);\n      if (!regentCanvaRunIsAuthorized({ task: currentTask.data, step: currentPhase.data, run: toolRun! })) {\n        throw new CanvaError(\"A invocação Canva foi substituída ou perdeu a autorização. Os jobs conhecidos foram preservados.\", 409, \"stale_canva_execution\");\n      }\n    }\n    async function onProgress(next: RegentCanvaProgress) {\n      progress = next;\n      const saved = await admin.from(\"regent_tool_runs\").update({ output: { ...progress, ...identity }, updated_at: new Date().toISOString() })\n        .eq(\"id\", toolRun!.id).eq(\"task_id\", toolRun!.task_id).eq(\"user_id\", toolRun!.user_id).eq(\"status\", \"running\").select(\"id\").maybeSingle();\n      if (saved.error || !saved.data) throw new CanvaError(\"Não foi possível persistir o progresso Canva. Confira o run original antes de retomar; não repita a criação.\", 503, \"canva_progress_not_persisted\");\n    }\n    try {\n      await assertAuthorized();\n      const options = { onProgress, assertAuthorized, expectedAccount, deadline: Date.now() + 80_000 };\n      const designs = mode === \"inspect\"\n        ? await inspectRegentCanvaDesigns(admin, toolRun.user_id, inspectedDesignIds, options)\n        : await createRegentCanvaDesigns(admin, toolRun.user_id, input.spec as RegentCanvaSpec, variants, options);\n      if (!progress.complete || !Array.isArray(designs) || designs.length !== (mode === \"inspect\" ? inspectedDesignIds.length : variants) ||\n        designs.some((design) => !design || typeof design.id !== \"string\" || typeof design.editUrl !== \"string\" || typeof design.viewUrl !== \"string\")) {\n        throw new CanvaError(\"O Canva não confirmou todos os resultados esperados. Confira os designs e jobs preservados.\", 502, \"invalid_canva_bridge_output\");\n      }\n      const output = { ...progress, ...identity, designs };\n      const saved = await admin\n        .from(\"regent_tool_runs\")\n        .update({ status: \"succeeded\", output, updated_at: new Date().toISOString() })\n        .eq(\"id\", toolRun.id).eq(\"task_id\", toolRun.task_id).eq(\"user_id\", toolRun.user_id).eq(\"status\", \"running\").select(\"id\").maybeSingle();\n      if (saved.error || !saved.data) throw new CanvaError(\"Resultados Canva recebidos, mas a conclusão não foi persistida. Confira o run original; não repita a criação.\", 503, \"canva_result_not_persisted\");\n      return NextResponse.json(output, { headers: { \"Cache-Control\": \"no-store\" } });\n    } catch (executionError) {\n      const output = { ...progress, ...identity, complete: false,\n        message: executionError instanceof Error ? executionError.message : \"Falha Canva\",\n        code: executionError instanceof CanvaError ? executionError.code : \"canva_execution_failed\" };\n      const saved = await admin\n        .from(\"regent_tool_runs\")\n        .update({\n          status: \"failed\",\n          output,\n          updated_at: new Date().toISOString(),\n        })\n        .eq(\"id\", toolRun.id).eq(\"task_id\", toolRun.task_id).eq(\"user_id\", toolRun.user_id).eq(\"status\", \"running\").select(\"id\").maybeSingle();\n      if (saved.error || !saved.data) return failure(new CanvaError(\"Falha ao persistir o diagnóstico Canva. Confira o run e os IDs informados antes de retomar; não repita a criação.\", 503, \"canva_failure_not_persisted\"), output);\n      return failure(executionError, output);\n    }\n  } catch (error) {\n    return failure(error);\n  }\n}\n","sha256":"4a7b9bcf0cf322054f6a5858573f958a761cd0bed44c1f526a413bceb63bab31"},{"path":"regente/docs/v0.7-architecture.md","content":"# Regente 0.7 — arquitetura operacional\n\n## Rede e provedores\n\n| Nó | Adapter | Evidência e limites |\n| --- | --- | --- |\n| A1/A2/A3 | OpenAI Agents SDK | Uma chamada delimitada por fase; fontes de contexto são somente dependências declaradas. |\n| A4 | Revisor OpenAI independente | Novo contexto de execução, não outro provedor. Não é Claude. |\n| A5 | Preflight local Supabase | Leituras autenticadas e inventário booleano. Sem geração, sem custos de API, sem patch automático. |\n| A6 | Parecer externo Claude manual | Pacote de conhecimento e importação do operador por etapa/revisão/commit. Origem declarada, identidade não verificada. Não concede aprovação. |\n| F6 | Bridge Portal Canva | Uma única conexão OAuth armazenada pelo Portal; identidade e permissões verificadas separadamente. |\n| Outros | Inventário explícito | Um nó sem adapter bloqueia só a fase que o exige. Não pode ser simulado por um worker. |\n\nClaude.ai, Claude Code e a API Anthropic são transportes diferentes. A assinatura\nClaude.ai não é prova de chave API nem de cobrança programática. Nenhuma chave\nAnthropic é obrigatória na 0.7. DeepSeek está reservado para a versão 0.8.\n\n## Uma fase, uma decisão\n\nUma missão nova sempre começa por A5. O planner fornece no máximo onze outras\nfases, cada qual com um nó executor, entrada, output esperado e dependências.\nA autorização humana persistida libera exatamente uma fase, nunca a missão\ninteira. A conclusão grava o artifact e um relatório e muda o estado para\n`awaiting_validation`. Continuar aceita esse output e autoriza somente a próxima\nfase; a última aceitação encerra a missão. Um estado de execução ou um parecer de\nguardião não substitui esse aceite.\n\nAs três funções SQL são SECURITY INVOKER com RLS, Master ativo, filtros do\nproprietário, row-lock e controle de revisão. `execution_id`, `invocation_id` e\nrevisão da fase impedem que uma execução antiga grave sobre uma versão nova.\nO endpoint público enfileira um Workflow, que renova a sessão cifrada. A sessão\ncontinua sujeita a Auth/RLS; não existe service-role no Regente.\n\nRefazer exige orientação, incrementa a revisão e preserva a versão anterior em\n`regent_phase_reviews`. Apenas consumidores transitivos declarados são\ninvalidados. Os workers não recebem outputs de etapas independentes, o que mantém\no grafo de invalidação igual ao grafo de contexto efetivamente utilizado.\nMissões antigas não são renumeradas ou marcadas como validadas retrospectivamente.\n\n## Recuperação e visibilidade\n\nFalhas determinísticas de adapter, autenticação, escopo ou billing não geram\ntrês tentativas idênticas. Timeout/429/5xx de operações seguras podem ter até três\ntentativas delimitadas. Uma criação Canva de resultado desconhecido nunca é\nrepetida automaticamente. Jobs e designs parciais permanecem no run original.\nDiagnóstico e revisão especializados OpenAI são separados da orquestra; não\naplicam código nem declaram participação de Claude sem parecer importado real.\n\nReservas de execução expiram e a recuperação exige decisão humana persistida.\nO monitor mostra estado atual, fase, atualização, erro, tentativas, próxima ação,\noutputs produzidos, validações e adiamentos separadamente. O histórico do chat é\nidentificado como histórico, não como estado corrente.\n\n## Afinamento e guardiões\n\nAfinamento básico usa somente leituras locais autenticadas e configuração\nbooleana. Afinamento profundo é solicitado pelo operador e faz probes GET sem\ngeração/criação/envio. Presença de chave não comprova autenticação, operação,\nsaldo ou acesso à geração. Billing, corpus legal e conta Pro são não verificáveis\nsem uma fonte real. Divergências conhecidas da conta Canva são mostradas, não\ncorrigidas trocando IDs à força.\n\nPacotes de guardião contêm constituição, objetivos, registry, estados e snapshot\ndo código relevante com hashes e commit do deployment. Segredos são excluídos e\nmascarados; arquivos ausentes e truncados são declarados. O guardião externo\nrecebe um contrato de diagnóstico, correção mínima, riscos, testes e rollback.\nO parecer importado não chama APIs externas, não libera uma fase e não modifica\ncheckpoints. A6 aceita apenas etapa, revisão e commit correspondentes.\n\n## Outputs e publicação\n\nArtifacts/checkpoints, runs e versões substituídas continuam consultáveis pelo\nproprietário. O preview é limitado; o download autenticado conserva o documento\ncompleto, com mascaramento de segredos. Links de edição Canva não são exportações\nduráveis e links gerados em texto não são automaticamente fontes verificadas.\nNão se afirma que uma campanha foi publicada, que WhatsApp foi enviado ou que\numa revisão jurídica terminou sem evidência do adapter e da documentação real.\n\nO release usa GitHub main → deployments Vercel de Portal e Regente. A verificação\nde `/api/version` separa a versão do cliente da versão/commit do servidor. Uma\nfalha do conector de administração Vercel não é contornada; a publicação utiliza\na integração CI/CD GitHub já autorizada.\n\nRollback operacional: promover o deployment anterior ou reverter o commit por\nGitHub. O banco é aditivo: não remover tabelas, artifacts, revisões ou checkpoints\npara voltar o código. A versão anterior não deve executar missões 0.7 aprovadas\nenquanto os gates da fase não forem preservados.\n","sha256":"e55667d47559244026b92c1347ccc7e25900856560155b69e307460e5e26a831"}];
